// app/api/compensation-settings/route.ts
import { NextRequest, NextResponse } from "next/server";

type HttpMethod = "GET" | "POST" | "PATCH" | "DELETE";

function corsHeaders() {
  return {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, POST, PATCH, DELETE, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type, Authorization",
  };
}

export async function OPTIONS() {
  return new Response(null, {
    status: 204,
    headers: corsHeaders(),
  });
}

const API_BASE =
  process.env.API_BASE ||
  process.env.NEXT_PUBLIC_API_BASE ||
  "";

const DIRECTUS_TOKEN =
  process.env.DIRECTUS_TOKEN ||
  process.env.DIRECTUS_STATIC_TOKEN ||
  process.env.NEXT_PUBLIC_DIRECTUS_TOKEN ||
  "";

function buildUrl(path: string) {
  const base = String(API_BASE || "").replace(/\/+$/, "");
  const p = path.startsWith("/") ? path : `/${path}`;
  return `${base}${p}`;
}

async function directusFetch(method: HttpMethod, path: string, body?: unknown) {
  const url = buildUrl(path);
  const headers: Record<string, string> = {
    Accept: "application/json",
  };
  if (method !== "GET") headers["Content-Type"] = "application/json";
  if (DIRECTUS_TOKEN) headers.Authorization = `Bearer ${DIRECTUS_TOKEN}`;

  const res = await fetch(url, {
    method,
    headers,
    body: body === undefined ? undefined : JSON.stringify(body),
    cache: "no-store",
  });

  const text = await res.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch (e) { }

  if (!res.ok) {
    return {
      ok: false as const,
      status: res.status,
      error: json?.errors?.[0]?.message || `Request failed (${res.status})`,
      raw: json ?? text,
    };
  }
  return { ok: true as const, status: res.status, data: json };
}

// Helper to map resource to table name
function getTableName(resource: string | null) {
  switch (resource) {
    case "area": return "payroll_logistics_area";
    case "location": return "payroll_logistics_location";
    case "staff": return "payroll_logistics_staff";
    case "vehicle_type": return "payroll_logistics_vehicle_type";
    default: return null;
  }
}

export async function GET(req: NextRequest) {
  const url = new URL(req.url);
  const resource = url.searchParams.get("resource");
  const table = getTableName(resource);

  if (!table) return NextResponse.json({ error: "Invalid resource" }, { status: 400 });

  const result = await directusFetch("GET", `/items/${table}`);
  if (!result.ok) return NextResponse.json({ error: result.error }, { status: result.status });
  return NextResponse.json(result.data, { headers: corsHeaders() });
}

export async function POST(req: NextRequest) {
  const url = new URL(req.url);
  const resource = url.searchParams.get("resource");
  const table = getTableName(resource);

  if (!table) return NextResponse.json({ error: "Invalid resource" }, { status: 400 });

  const payload = await req.json().catch(() => null);
  const result = await directusFetch("POST", `/items/${table}`, payload);
  if (!result.ok) return NextResponse.json({ error: result.error }, { status: result.status });
  return NextResponse.json(result.data, { headers: corsHeaders() });
}

export async function PATCH(req: NextRequest) {
  const url = new URL(req.url);
  const resource = url.searchParams.get("resource");
  const table = getTableName(resource);

  if (!table) return NextResponse.json({ error: "Invalid resource" }, { status: 400 });

  const payload = await req.json().catch(() => null);
  const id = payload?.id;
  if (!id) return NextResponse.json({ error: "Missing ID" }, { status: 400 });

  const result = await directusFetch("PATCH", `/items/${table}/${id}`, payload);
  if (!result.ok) return NextResponse.json({ error: result.error }, { status: result.status });
  return NextResponse.json(result.data, { headers: corsHeaders() });
}

export async function DELETE(req: NextRequest) {
  const url = new URL(req.url);
  const resource = url.searchParams.get("resource");
  const table = getTableName(resource);
  const id = url.searchParams.get("id");

  if (!table || !id) return NextResponse.json({ error: "Invalid resource or missing ID" }, { status: 400 });

  const result = await directusFetch("DELETE" as HttpMethod, `/items/${table}/${id}`);
  if (!result.ok) return NextResponse.json({ error: result.error }, { status: result.status });
  return NextResponse.json({ message: "Deleted" }, { headers: corsHeaders() });
}

// app/api/cutoff-settings/route.ts
import { NextRequest, NextResponse } from "next/server";

type HttpMethod = "GET" | "POST" | "PATCH" | "DELETE";

function corsHeaders() {
  return {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, POST, PATCH, DELETE, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type, Authorization",
  };
}

export async function OPTIONS() {
  return new Response(null, {
    status: 204,
    headers: corsHeaders(),
  });
}

const API_BASE =
  process.env.API_BASE ||
  process.env.NEXT_PUBLIC_API_BASE ||
  "";

const DIRECTUS_TOKEN =
  process.env.DIRECTUS_TOKEN ||
  process.env.DIRECTUS_STATIC_TOKEN ||
  process.env.NEXT_PUBLIC_DIRECTUS_TOKEN ||
  "";

function normalizeBaseUrl(url: string) {
  return String(url || "").replace(/\/+$/, "");
}

function buildUrl(path: string) {
  const base = normalizeBaseUrl(API_BASE);
  const p = path.startsWith("/") ? path : `/${path}`;
  return `${base}${p}`;
}

function parseIdsParam(idsParam: string | null): string[] {
  if (!idsParam) return [];
  return idsParam
    .split(",")
    .map((s) => s.trim())
    .filter(Boolean);
}

async function safeJsonParse(text: string) {
  try {
    return text ? JSON.parse(text) : null;
  } catch {
    return null;
  }
}

/**
 * Authenticated fetch (uses DIRECTUS_TOKEN if available)
 * Good for collections that require token access.
 */
async function directusFetchAuth(method: HttpMethod, path: string, body?: unknown) {
  const url = buildUrl(path);

  const headers: Record<string, string> = {
    Accept: "application/json",
  };

  if (method !== "GET") headers["Content-Type"] = "application/json";
  if (DIRECTUS_TOKEN) headers.Authorization = `Bearer ${DIRECTUS_TOKEN}`;

  const res = await fetch(url, {
    method,
    headers,
    body: body === undefined ? undefined : JSON.stringify(body),
    cache: "no-store",
  });

  const text = await res.text();
  const json = await safeJsonParse(text);

  if (!res.ok) {
    const message =
      json?.errors?.[0]?.message ||
      json?.message ||
      `Directus request failed (${res.status}).`;

    return {
      ok: false as const,
      status: res.status,
      error: message,
      raw: json ?? text,
    };
  }

  return {
    ok: true as const,
    status: res.status,
    data: json,
  };
}

/**
 * No-auth fetch (NO Bearer token)
 * Matches your /api/auth/login behavior for /items/user
 */
async function directusFetchNoAuth(method: HttpMethod, path: string, body?: unknown) {
  const url = buildUrl(path);

  const headers: Record<string, string> = {
    Accept: "application/json",
  };

  if (method !== "GET") headers["Content-Type"] = "application/json";

  const res = await fetch(url, {
    method,
    headers,
    body: body === undefined ? undefined : JSON.stringify(body),
    cache: "no-store",
  });

  const text = await res.text();
  const json = await safeJsonParse(text);

  if (!res.ok) {
    const message =
      json?.errors?.[0]?.message ||
      json?.message ||
      `Directus request failed (${res.status}).`;

    return {
      ok: false as const,
      status: res.status,
      error: message,
      raw: json ?? text,
    };
  }

  return {
    ok: true as const,
    status: res.status,
    data: json,
  };
}

function buildCutoffSettingsQuery(month?: string | null, year?: string | null) {
  const qs = new URLSearchParams();
  qs.set("fields", "*");
  qs.set("limit", "200");
  qs.set("sort", "cutoff_type");

  if (month) qs.set("filter[month][_eq]", month);
  if (year) qs.set("filter[year][_eq]", year);

  return qs.toString();
}

/**
 * Logs history to cutoff_settings_history
 */
async function logHistory(
  eventType: "INSERT" | "UPDATE" | "DELETE",
  data: any,
  changedBy: string | null
) {
  try {
    const historyData = {
      cutoff_setting_id: data.id,
      event_type: eventType,
      event_at: new Date().toISOString(),
      changed_by: changedBy || data.updated_by || data.created_by,
      status: data.status,
      source_date_created: data.date_created,
      source_date_updated: data.date_updated,
      month: data.month,
      year: data.year,
      cutoff_type: data.cutoff_type,
      start_date: data.start_date,
      end_date: data.end_date,
      payout_date: data.payout_date,
      period_status: data.period_status,
      created_by: data.created_by,
      updated_by: data.updated_by,
      raw_payload: data,
    };

    await directusFetchAuth("POST", "/items/cutoff_settings_history", historyData);
  } catch (error) {
    console.error("Failed to log history:", error);
  }
}

/**
 * Synchronizes benefit_cutoff_settings based on cutoff_settings changes
 */
async function syncBenefitCutoffs(
  cutoffType: string,
  startDate: string,
  endDate: string,
  updatedBy: string | null
) {
  try {
    // 1. Fetch matching benefit cutoff settings
    const qs = new URLSearchParams();
    qs.set("filter[cutoff][_eq]", cutoffType);
    qs.set("fields", "id");

    const getRes = await directusFetchAuth("GET", `/items/benefit_cutoff_settings?${qs}`);
    if (!getRes.ok) {
      console.error("Failed to fetch benefit cutoffs for sync:", getRes.error);
      return;
    }

    const items = (getRes.data as any)?.data || [];
    if (!items.length) return;

    // 2. Update each matching row
    for (const item of items) {
      const patchBody = {
        effective_from: startDate,
        effective_to: endDate,
        updated_by: updatedBy,
      };

      const patchRes = await directusFetchAuth(
        "PATCH",
        `/items/benefit_cutoff_settings/${item.id}`,
        patchBody
      );

      if (!patchRes.ok) {
        console.error(`Failed to sync benefit cutoff id ${item.id}:`, patchRes.error);
      }
    }
  } catch (error) {
    console.error("Benefit cutoff sync error:", error);
  }
}

/**
 * Checks if relevant fields have changed between old and new data
 */
function hasChanged(oldData: any, newData: any) {
  const fieldsToCompare = [
    "status",
    "month",
    "year",
    "cutoff_type",
    "start_date",
    "end_date",
    "payout_date",
    "period_status",
    "created_by",
    "updated_by",
  ];

  return fieldsToCompare.some((field) => {
    const oldVal = oldData?.[field];
    const newVal = newData?.[field];
    // Simple comparison; adjust if needed for dates/json
    return oldVal !== newVal;
  });
}

/**
 * Builds query for /items/user.
 * If ids are provided: filters by OR(id in ids, user_id in ids).
 */
function buildUsersQuery(ids: string[]) {
  const qs = new URLSearchParams();
  qs.set("fields", "user_id,user_fname,user_mname,user_lname,user_email");
  qs.set("limit", "500");

  // If you want stable ordering. Some roles block sort; remove if needed.
  // qs.set("sort", "user_lname");

  if (ids.length) {
    // Filter by user_id in ids
    qs.set("filter[user_id][_in]", ids.join(","));
  }

  return qs.toString();
}

/**
 * GET /api/cutoff-settings
 * - default: returns cutoff_settings (optionally filtered by month/year)
 * - if ?resource=users : returns user list (optionally filtered by ids)
 */
export async function GET(req: NextRequest) {
  if (!API_BASE) {
    return NextResponse.json(
      { error: "API base not configured" },
      { status: 500 }
    );
  }

  const url = new URL(req.url);
  const resource = url.searchParams.get("resource");

  // Users proxy
  if (resource === "users") {
    const ids = parseIdsParam(url.searchParams.get("ids"));
    const qs = buildUsersQuery(ids);

    // Use no-auth for users, like login
    const result = await directusFetchNoAuth("GET", `/items/user?${qs}`);

    if (!result.ok) {
      return NextResponse.json(
        { error: result.error, raw: result.raw },
        { status: result.status }
      );
    }

    return NextResponse.json(result.data, {
      status: 200,
      headers: corsHeaders(),
    });
  }

  // Cutoff settings proxy (token-based if available)
  const month = url.searchParams.get("month");
  const year = url.searchParams.get("year");
  const qs = buildCutoffSettingsQuery(month, year);

  const result = await directusFetchAuth("GET", `/items/cutoff_settings?${qs}`);

  if (!result.ok) {
    return NextResponse.json(
      { error: result.error, raw: result.raw },
      { status: result.status, headers: corsHeaders() }
    );
  }

  return NextResponse.json(result.data, {
    status: 200,
    headers: corsHeaders(),
  });
}

export async function POST(req: NextRequest) {
  if (!API_BASE) {
    return NextResponse.json(
      { error: "API base not configured" },
      { status: 500 }
    );
  }

  const payload = await req.json().catch(() => null);
  if (!payload) {
    return NextResponse.json({ error: "Invalid JSON body." }, { status: 400 });
  }

  const result = await directusFetchAuth("POST", `/items/cutoff_settings`, payload);

  if (!result.ok) {
    return NextResponse.json(
      { error: result.error, raw: result.raw },
      { status: result.status, headers: corsHeaders() }
    );
  }

  // Log History for INSERT
  const newData = (result.data as any)?.data || result.data;
  if (newData) {
    await logHistory("INSERT", newData, newData.created_by);
    await syncBenefitCutoffs(
      newData.cutoff_type,
      newData.start_date,
      newData.end_date,
      newData.created_by
    );
  }

  return NextResponse.json(result.data, {
    status: 200,
    headers: corsHeaders(),
  });
}

export async function PATCH(req: NextRequest) {
  if (!API_BASE) {
    return NextResponse.json(
      { error: "API base not configured" },
      { status: 500 }
    );
  }

  const payload = await req.json().catch(() => null);
  if (!payload) {
    return NextResponse.json({ error: "Invalid JSON body." }, { status: 400 });
  }

  const items = Array.isArray(payload) ? payload : [payload];
  const results: unknown[] = [];

  for (const item of items) {
    const id = item?.id;

    if (id) {
      // Fetch OLD data for comparison if needed
      const oldRes = await directusFetchAuth("GET", `/items/cutoff_settings/${id}`);
      const oldData = oldRes.ok ? (oldRes.data as any)?.data || oldRes.data : null;

      const { id: _id, ...patchBody } = item;
      const r = await directusFetchAuth(
        "PATCH",
        `/items/cutoff_settings/${id}`,
        patchBody
      );

      if (!r.ok) {
        return NextResponse.json(
          { error: r.error, raw: r.raw },
          { status: r.status, headers: corsHeaders() }
        );
      }

      const newData = (r.data as any)?.data || r.data;
      if (newData && oldData && hasChanged(oldData, newData)) {
        await logHistory("UPDATE", newData, newData.updated_by);

        // Sync if relevant fields changed
        if (
          oldData.start_date !== newData.start_date ||
          oldData.end_date !== newData.end_date ||
          oldData.cutoff_type !== newData.cutoff_type
        ) {
          await syncBenefitCutoffs(
            newData.cutoff_type,
            newData.start_date,
            newData.end_date,
            newData.updated_by
          );
        }
      }

      results.push(newData);
    } else {
      const r = await directusFetchAuth("POST", `/items/cutoff_settings`, item);

      if (!r.ok) {
        return NextResponse.json(
          { error: r.error, raw: r.raw },
          { status: r.status, headers: corsHeaders() }
        );
      }

      const newData = (r.data as any)?.data || r.data;
      if (newData) {
        await logHistory("INSERT", newData, newData.created_by);
        await syncBenefitCutoffs(
          newData.cutoff_type,
          newData.start_date,
          newData.end_date,
          newData.created_by
        );
      }

      results.push(newData);
    }
  }

  return NextResponse.json(
    { data: results },
    { status: 200, headers: corsHeaders() }
  );
}

export async function DELETE(req: NextRequest) {
  if (!API_BASE) {
    return NextResponse.json(
      { error: "API base not configured" },
      { status: 500, headers: corsHeaders() }
    );
  }

  const url = new URL(req.url);
  const id = url.searchParams.get("id");

  if (!id) {
    return NextResponse.json(
      { error: "Missing ID for deletion" },
      { status: 400, headers: corsHeaders() }
    );
  }

  // Fetch data BEFORE deletion for history
  const getOld = await directusFetchAuth("GET", `/items/cutoff_settings/${id}`);
  const oldData = getOld.ok ? (getOld.data as any)?.data || getOld.data : null;

  const result = await directusFetchAuth("DELETE" as any, `/items/cutoff_settings/${id}`);

  if (!result.ok) {
    return NextResponse.json(
      { error: result.error, raw: result.raw },
      { status: result.status, headers: corsHeaders() }
    );
  }

  if (oldData) {
    await logHistory("DELETE", oldData, oldData.updated_by);
  }

  return NextResponse.json(
    { message: "Deleted successfully" },
    { status: 200, headers: corsHeaders() }
  );
}

// Testable helpers
export const __testables = {
  normalizeBaseUrl,
  buildCutoffSettingsQuery,
  buildUsersQuery,
  buildUrl,
  parseIdsParam,
};

import type { NextRequest } from "next/server";
import { NextResponse } from "next/server";

const BASE = process.env.API_BASE || process.env.NEXT_PUBLIC_API_BASE;

const SERVICE_TOKEN =
  process.env.DIRECTUS_TOKEN ||
  process.env.DIRECTUS_SERVICE_TOKEN ||
  process.env.NEXT_PUBLIC_DIRECTUS_TOKEN ||
  "";

function joinUrl(base: string, path: string) {
  const b = (base || "").replace(/\/+$/, "");
  const p = (path || "").startsWith("/") ? path : `/${path}`;
  return `${b}${p}`;
}

function buildForwardHeaders(req: NextRequest, contentType?: string) {
  const headers: Record<string, string> = {};
  if (contentType) headers["Content-Type"] = contentType;

  const auth = req.headers.get("authorization");
  if (auth) headers["Authorization"] = auth;

  if (!headers["Authorization"] && SERVICE_TOKEN) {
    headers["Authorization"] = `Bearer ${SERVICE_TOKEN}`;
  }

  return headers;
}

async function parseJsonSafe(res: Response) {
  const text = await res.text();
  if (!text) return null;
  try {
    return JSON.parse(text);
  } catch {
    return { raw: text };
  }
}

export async function GET(req: NextRequest) {
  try {
    if (!BASE) {
      return NextResponse.json(
        { error: "Missing API base URL" },
        { status: 500 }
      );
    }

    const url = new URL(req.url);
    const path = url.searchParams.get("path") || "";

    url.searchParams.delete("path");
    const extra = url.searchParams.toString();

    const fetchUrl = `${joinUrl(BASE, path)}${extra ? (path.includes("?") ? "&" : "?") + extra : ""}`;
    console.log(`[dashboardProxy] Final Fetch URL: ${fetchUrl}`);

    const res = await fetch(fetchUrl, {
      method: "GET",
      headers: buildForwardHeaders(req),
      cache: "no-store",
    });

    const data = await parseJsonSafe(res);
    console.log(`[dashboardProxy] Downstream response: ${res.status}, items: ${data?.data?.length ?? 0}`);
    return NextResponse.json(data, { status: res.status });
  } catch (e: any) {
    console.error("API dashboard GET error:", e);
    return NextResponse.json(
      { error: e?.message || "GET failed" },
      { status: 500 }
    );
  }
}

// app/api/payroll-run/payslips-pdf/route.ts
import { NextRequest, NextResponse } from "next/server";
import PDFDocument from "pdfkit";

export const runtime = "nodejs";
export const dynamic = "force-dynamic";

type AnyRow = Record<string, any>;

function n(v: any): number {
  const x = Number(v ?? 0);
  return Number.isFinite(x) ? x : 0;
}

function money(v: any): string {
  const x = n(v);
  return `₱${x.toLocaleString("en-PH", {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  })}`;
}

function s(v: any): string {
  return String(v ?? "");
}

function parseJsonMaybe(v: any): any | null {
  if (!v) return null;
  if (typeof v === "object") return v;
  if (typeof v === "string") {
    try {
      return JSON.parse(v);
    } catch {
      return null;
    }
  }
  return null;
}

async function readBody(req: NextRequest) {
  try {
    return await req.json();
  } catch {
    return null;
  }
}

function baseUrl() {
  const b = process.env.API_BASE ?? process.env.NEXT_PUBLIC_API_BASE;
  return b ? String(b).replace(/\/+$/, "") : "";
}

function pickAuth(req: NextRequest) {
  const incoming = req.headers.get("authorization");
  if (incoming) return incoming;

  const staticToken =
    process.env.DIRECTUS_TOKEN ??
    process.env.DIRECTUS_STATIC_TOKEN ??
    process.env.API_TOKEN ??
    null;

  return staticToken ? `Bearer ${staticToken}` : null;
}

async function fetchPayrollRunEmployees(req: NextRequest, payrollRunId: number) {
  const directus = baseUrl();
  if (!directus) throw new Error("Missing API_BASE / NEXT_PUBLIC_API_BASE env");

  const auth = pickAuth(req);

  const url =
    `${directus}/items/payroll_run_employee` +
    `?filter[payroll_run_id][_eq]=${encodeURIComponent(String(payrollRunId))}` +
    `&limit=5000` +
    `&sort=employee_name`;

  const res = await fetch(url, {
    method: "GET",
    headers: {
      ...(auth ? { Authorization: auth } : {}),
    },
    cache: "no-store",
  });

  const text = await res.text();
  let json: any = null;
  try {
    json = text ? JSON.parse(text) : null;
  } catch {
    json = null;
  }

  if (!res.ok) {
    const msg = json?.error || json?.errors || json?.message || "Request failed";
    throw new Error(typeof msg === "string" ? msg : JSON.stringify(msg));
  }

  return Array.isArray(json?.data) ? (json.data as AnyRow[]) : [];
}

/**
 * ✅ SAFE DEDUPE:
 * - Prefer payroll_run_employee primary key (row.id) when present.
 * - Fallback to explicit payroll_run_employee_id if present.
 * - Fallback to (payroll_run_id + user_id) only if BOTH exist.
 * - If we cannot compute a reliable key, we DO NOT dedupe that row (prevents “missing 1 payslip”).
 */
function payslipKey(r: AnyRow): string | null {
  const primary =
    r?.id ?? r?.payroll_run_employee_id ?? r?.payrollRunEmployeeId ?? null;

  if (primary !== null && primary !== undefined && String(primary).trim() !== "") {
    return `pre:${String(primary)}`;
  }

  const run = r?.payroll_run_id ?? r?.payrollRunId ?? null;
  const user = r?.user_id ?? r?.userId ?? null;

  if (
    run !== null &&
    run !== undefined &&
    String(run).trim() !== "" &&
    user !== null &&
    user !== undefined &&
    String(user).trim() !== ""
  ) {
    return `ru:${String(run)}-${String(user)}`;
  }

  return null;
}

function dedupeRows(rows: AnyRow[]): AnyRow[] {
  const seen = new Set<string>();
  const out: AnyRow[] = [];

  for (const r of rows) {
    const k = payslipKey(r);
    if (!k) {
      // no reliable key -> keep it (prevents accidental dropping)
      out.push(r);
      continue;
    }
    if (seen.has(k)) continue;
    seen.add(k);
    out.push(r);
  }

  return out;
}

function buildEarningsLines(row: AnyRow) {
  const b = parseJsonMaybe(row.breakdown_json ?? row.breakdownJson);

  const allowanceItems =
    b?.earnings?.allowance_items ?? b?.earnings?.allowanceItems ?? [];

  const allowanceLines: string[] = Array.isArray(allowanceItems)
    ? allowanceItems
      .map((x: any) => {
        const desc = s(x?.description ?? x?.name ?? "Allowance").trim();
        const amt = n(
          x?.amount_this_cutoff ?? x?.amount ?? x?.amountThisCutoff
        );
        if (!desc || amt === 0) return "";
        return `${desc} (${money(amt)})`;
      })
      .filter(Boolean)
    : [];

  const manualItems =
    b?.earnings?.manual_additions_items ??
    b?.earnings?.manualAdditionsItems ??
    b?.earnings?.manual_items ??
    [];

  const manualLines: string[] = Array.isArray(manualItems)
    ? manualItems
      .map((x: any) => {
        const desc = s(x?.description ?? x?.name ?? "Addition").trim();
        const amt = n(x?.amount ?? x?.value ?? 0);
        if (!desc || amt === 0) return "";
        return `${desc} (${money(amt)})`;
      })
      .filter(Boolean)
    : [];

  return { allowanceLines, manualLines };
}

function buildDeductionLines(row: AnyRow) {
  const loanVale = n(row.loan_vale);
  const loanCar = n(row.loan_car);
  const loanCoop = n(row.loan_coop);

  const loanLines: string[] = [];
  if (loanVale) loanLines.push(`Vale (${money(loanVale)})`);
  if (loanCar) loanLines.push(`Car Loan (${money(loanCar)})`);
  if (loanCoop) loanLines.push(`Coop Loan (${money(loanCoop)})`);

  const benefitLoanSSS = n(row.benefit_loan_sss);
  const benefitLoanPagibig = n(row.benefit_loan_pagibig);

  const benefitLoanLines: string[] = [];
  if (benefitLoanSSS) benefitLoanLines.push(`SSS Loan (${money(benefitLoanSSS)})`);
  if (benefitLoanPagibig)
    benefitLoanLines.push(`Pag-IBIG Loan (${money(benefitLoanPagibig)})`);

  return { loanLines, benefitLoanLines };
}

function drawSlip(
  doc: PDFKit.PDFDocument,
  row: AnyRow,
  x: number,
  y: number,
  w: number,
  h: number
) {
  const pad = 10;
  const innerX = x + pad;
  const innerY = y + pad;
  const innerW = w - pad * 2;
  const innerH = h - pad * 2;

  doc.save().lineWidth(1).rect(x, y, w, h).stroke("#111111").restore();

  doc.font("Helvetica-Bold").fontSize(10).fillColor("#111111");
  doc.text("PAYSLIP", innerX, innerY, { width: innerW, align: "left" });

  const employeeName = s(
    row.employee_name ?? row.employeeName ?? row.full_name ?? row.name ?? ""
  ).trim();
  const position = s(row.position_name ?? row.position ?? "").trim();
  const department = s(
    row.department_name_snapshot ?? row.department_name ?? row.departmentName ?? ""
  ).trim();
  const userId = s(row.user_id ?? row.userId ?? "").trim();

  const cutoffLabel = s(row.cutoff_label ?? "").trim();
  const cutoffStart = s(row.cutoff_start ?? "").slice(0, 10);
  const cutoffEnd = s(row.cutoff_end ?? "").slice(0, 10);
  const period =
    cutoffLabel ||
    (cutoffStart && cutoffEnd ? `${cutoffStart} to ${cutoffEnd}` : "-");

  const topY = innerY + 14;
  doc.font("Helvetica").fontSize(8).fillColor("#111111");

  const leftW = innerW * 0.62;
  const rightW = innerW - leftW;
  const lh = 10;

  doc.text(`Period: ${period}`, innerX, topY, { width: leftW });
  doc.text(`Designation: ${position || "-"}`, innerX + leftW, topY, {
    width: rightW,
  });

  doc.text(`Employee: ${employeeName || "-"}`, innerX, topY + lh, {
    width: leftW,
  });
  doc.text(`ID No.: ${userId || "-"}`, innerX + leftW, topY + lh, {
    width: rightW,
  });

  doc.text(`Department: ${department || "-"}`, innerX, topY + lh * 2, {
    width: leftW,
  });

  const bandY = topY + lh * 3 + 2;
  const bandH = 38;

  doc.save().lineWidth(1).rect(innerX, bandY, innerW, bandH).stroke("#111111").restore();

  const daysWorked = n(row.total_days_worked);
  const hoursWorked = n(row.total_hours_worked);
  const lateMin = Math.floor(n(row.late_minutes));
  const utMin = Math.floor(n(row.undertime_minutes));
  const otMin = Math.floor(n(row.overtime_minutes));
  const ndMin = Math.floor(n(row.night_diff_minutes));

  const dailyRate = n(row.daily_rate ?? row.basic_daily_rate);

  const bandLeftX = innerX + 6;
  const bandRightX = innerX + innerW * 0.55;

  doc.font("Helvetica").fontSize(8);
  doc.text(`Days Worked: ${daysWorked.toFixed(2)}`, bandLeftX, bandY + 6);
  doc.text(`Hours Worked: ${hoursWorked.toFixed(2)}`, bandLeftX, bandY + 16);
  doc.text(`OT (min): ${otMin}   ND (min): ${ndMin}`, bandLeftX, bandY + 26);

  doc.text(`Late (min): ${lateMin}`, bandRightX, bandY + 6);
  doc.text(`Undertime (min): ${utMin}`, bandRightX, bandY + 16);
  doc.text(`Daily Rate: ${money(dailyRate)}`, bandRightX, bandY + 26);

  const tableY = bandY + bandH + 6;
  const tableH = innerH - (tableY - innerY) - 34;
  const midX = innerX + innerW / 2;

  doc
    .save()
    .lineWidth(1)
    .rect(innerX, tableY, innerW, tableH)
    .stroke("#111111")
    .moveTo(midX, tableY)
    .lineTo(midX, tableY + tableH)
    .stroke("#111111")
    .restore();

  doc.font("Helvetica-Bold").fontSize(9);
  doc.text("EARNINGS", innerX, tableY + 4, { width: innerW / 2, align: "center" });
  doc.text("DEDUCTIONS", midX, tableY + 4, { width: innerW / 2, align: "center" });

  doc
    .save()
    .lineWidth(1)
    .moveTo(innerX, tableY + 18)
    .lineTo(innerX + innerW, tableY + 18)
    .stroke("#111111")
    .restore();

  const earningsX = innerX + 6;
  const deductionsX = midX + 6;
  const colW = innerW / 2 - 12;

  const basicPay = n(row.basic_pay);
  const otAmount = n(row.ot_amount);
  const holidayPay = n(row.holiday_pay ?? row.holiday);
  const restDayAmount = n(row.rest_day_amount);
  const nightDiffAmount = n(row.night_diff_amount);
  const allowanceTotal = n(row.allowance);
  const manualAdditions = n(row.manual_additions);
  const leaveAmount = n(row.leave_amount);
  const retroPay = n(row.retro_pay);

  const lateDed = n(row.late_deduction);
  const utDed = n(row.undertime_deduction);
  const shortageDed = n(row.shortage_deduction);
  const drDed = n(row.dr_deduction);

  const loanTotal = n(
    row.loan_total ?? (n(row.loan_vale) + n(row.loan_car) + n(row.loan_coop))
  );
  const coopSavings = n(row.coop_savings);
  const coopLoan = n(row.coop_loan);

  const benSSS = n(row.benefit_sss);
  const benPhil = n(row.benefit_philhealth);
  const benPag = n(row.benefit_pagibig);
  const benLoanSSS = n(row.benefit_loan_sss);
  const benLoanPag = n(row.benefit_loan_pagibig);

  const otherDed = n(row.other_deductions);
  const manualDed = n(row.manual_deductions);

  const grossPay = n(row.gross_pay);
  const totalDeductions = n(row.total_deductions);
  const netPay = n(row.net_pay);

  const { allowanceLines, manualLines } = buildEarningsLines(row);
  const { loanLines, benefitLoanLines } = buildDeductionLines(row);

  const eItems: Array<[string, number]> = [
    ["Basic Pay", basicPay],
    ["Overtime Pay", otAmount],
    ["Holiday Pay", holidayPay],
    ["Rest Day Pay", restDayAmount],
    ["Night Diff", nightDiffAmount],
    ["Allowance (Total)", allowanceTotal],
    ["Manual Additions (Total)", manualAdditions],
    ["Leave Amount", leaveAmount],
    ["Retro Pay", retroPay],
  ];

  const dItems: Array<[string, number]> = [
    ["Late Deduction", lateDed],
    ["Undertime Deduction", utDed],
    ["Shortage Deduction", shortageDed],
    ["Stock Payments (DR)", drDed],
    ["Employee Loans (Total)", loanTotal],
    ["SSS Contribution", benSSS],
    ["PhilHealth Contribution", benPhil],
    ["Pag-IBIG Contribution", benPag],
    ["SSS Loan", benLoanSSS],
    ["Pag-IBIG Loan", benLoanPag],
    ["Coop Savings", coopSavings],
    ["Coop Loan", coopLoan],
    ["Other Deductions", otherDed],
    ["Manual Deductions", manualDed],
  ];

  const startY = tableY + 22;
  const rowH = 10;
  const maxRows = Math.floor((tableH - 26) / rowH);

  doc.font("Helvetica").fontSize(8);

  function drawList(
    x0: number,
    y0: number,
    items: Array<[string, number]>,
    extraLines: string[]
  ) {
    let yPos = y0;
    let used = 0;

    for (const [label, val] of items) {
      if (used >= maxRows - 3) break;
      if (n(val) === 0) continue;

      doc.text(label, x0, yPos, { width: colW * 0.68, ellipsis: true });
      doc.text(money(val), x0 + colW * 0.68, yPos, {
        width: colW * 0.32,
        align: "right",
      });

      yPos += rowH;
      used += 1;
    }

    if (extraLines?.length) {
      const take = Math.max(0, Math.min(extraLines.length, maxRows - used - 1));
      if (take > 0) {
        doc.font("Helvetica-Oblique").fontSize(7);
        for (let i = 0; i < take; i++) {
          doc.text(`- ${extraLines[i]}`, x0, yPos, { width: colW, ellipsis: true });
          yPos += 9;
        }
        doc.font("Helvetica").fontSize(8);
      }
      if (extraLines.length > take) {
        doc.font("Helvetica-Oblique").fontSize(7);
        doc.text("…", x0, yPos, { width: colW });
        doc.font("Helvetica").fontSize(8);
      }
    }
  }

  drawList(earningsX, startY, eItems, [...allowanceLines, ...manualLines]);
  drawList(deductionsX, startY, dItems, [...loanLines, ...benefitLoanLines]);

  const footY = tableY + tableH + 6;
  const footH = 22;

  doc.save().lineWidth(1).rect(innerX, footY, innerW, footH).stroke("#111111").restore();

  doc.font("Helvetica-Bold").fontSize(9);
  doc.text(`Gross Pay: ${money(grossPay)}`, innerX + 8, footY + 6, {
    width: innerW / 3,
  });
  doc.text(`Deductions: ${money(totalDeductions)}`, innerX + innerW / 3, footY + 6, {
    width: innerW / 3,
    align: "center",
  });
  doc.text(`NET PAY: ${money(netPay)}`, innerX + (innerW * 2) / 3 - 8, footY + 6, {
    width: innerW / 3,
    align: "right",
  });
}

async function buildPdfBuffer(rows: AnyRow[]) {
  const doc = new PDFDocument({
    size: "LEGAL",
    layout: "portrait",
    margins: { top: 24, bottom: 24, left: 24, right: 24 },
    autoFirstPage: true,
  });

  const chunks: Buffer[] = [];
  doc.on("data", (c) => chunks.push(Buffer.isBuffer(c) ? c : Buffer.from(c)));
  const done = new Promise<Buffer>((resolve, reject) => {
    doc.on("end", () => resolve(Buffer.concat(chunks)));
    doc.on("error", reject);
  });

  const perPage = 5;
  const pageW = doc.page.width;
  const pageH = doc.page.height;

  const marginX = 24;
  const marginY = 24;
  const gap = 10;

  const slipW = pageW - marginX * 2;
  const usableH = pageH - marginY * 2 - gap * (perPage - 1);
  const slipH = usableH / perPage;

  for (let i = 0; i < rows.length; i++) {
    const idxOnPage = i % perPage;
    if (i > 0 && idxOnPage === 0) doc.addPage();

    const x = marginX;
    const y = marginY + idxOnPage * (slipH + gap);

    drawSlip(doc, rows[i], x, y, slipW, slipH);
  }

  doc.end();
  return done;
}

export async function POST(req: NextRequest) {
  try {
    const body = await readBody(req);

    const payrollRunIdRaw = body?.payrollRunId ?? body?.payroll_run_id ?? null;
    const payrollRunId = Number(payrollRunIdRaw);

    if (!Number.isFinite(payrollRunId) || payrollRunId <= 0) {
      return NextResponse.json(
        { error: "Missing or invalid payrollRunId" },
        { status: 400 }
      );
    }

    let rows = await fetchPayrollRunEmployees(req, payrollRunId);

    if (!rows.length) {
      return NextResponse.json(
        { error: "No payroll_run_employee rows found for this run" },
        { status: 404 }
      );
    }

    rows = dedupeRows(rows);

    rows.sort((a, b) =>
      s(a.employee_name ?? a.employeeName ?? "").localeCompare(
        s(b.employee_name ?? b.employeeName ?? "")
      )
    );

    const pdf = await buildPdfBuffer(rows);

    return new NextResponse(new Uint8Array(pdf), {
      status: 200,
      headers: {
        "Content-Type": "application/pdf",
        "Content-Disposition": `inline; filename="payslips-run-${payrollRunId}.pdf"`,
        "Cache-Control": "no-store",
      },
    });
  } catch (e: any) {
    return NextResponse.json(
      { error: "Failed to generate payslip PDF", details: e?.message ?? String(e) },
      { status: 500 }
    );
  }
}

