import { NextRequest, NextResponse } from "next/server";

type ResourceKey =
  | "payroll_run"
  | "payroll_run_employee"
  | "cutoff_settings"
  | "department"
  | "user"
  | "user_wage_management"
  | "attendance_approval"
  | "holiday_calendar"
  | "payroll_other_additions"
  | "payroll_other_deductions"
  | "benefit_cutoff_settings"
  | "employee_loan"
  | "benefit_loans"
  | "employee_allowance"
  | "dr_payment"
  // ✅ NEW
  | "user_wage_proration_log"
  | "payroll_run_employee_item"
  | "retro_pay"
  | "coop_savings_membership"
  | "payroll_run_access_log"
  | "benefit_logs"
  ;

const ALLOWED: Record<ResourceKey, true> = {
  payroll_run: true,
  payroll_run_employee: true,
  cutoff_settings: true,
  department: true,
  user: true,
  user_wage_management: true,
  attendance_approval: true,
  holiday_calendar: true,
  payroll_other_additions: true,
  payroll_other_deductions: true,
  benefit_cutoff_settings: true,
  employee_loan: true,
  benefit_loans: true,
  employee_allowance: true,
  dr_payment: true,
  // ✅ NEW
  user_wage_proration_log: true,
  payroll_run_employee_item: true,
  retro_pay: true,
  coop_savings_membership: true,
  payroll_run_access_log: true,
  benefit_logs: true,
};

function baseUrl() {
  const b = process.env.API_BASE ?? process.env.NEXT_PUBLIC_API_BASE;
  if (!b) return "";
  return String(b).replace(/\/+$/, "");
}

function pickAuth(req: NextRequest) {
  const incoming = req.headers.get("authorization");
  if (incoming) return incoming;

  const staticToken =
    process.env.DIRECTUS_TOKEN ??
    process.env.DIRECTUS_STATIC_TOKEN ??
    process.env.API_TOKEN ??
    null;

  return staticToken ? `Bearer ${staticToken}` : null;
}

function jsonError(status: number, error: string, details?: any) {
  return NextResponse.json({ error, details }, { status });
}

async function proxy(req: NextRequest): Promise<NextResponse> {
  const url = req.nextUrl;
  const resource = (url.searchParams.get("resource") ?? "") as ResourceKey;
  const idRaw = url.searchParams.get("id");

  if (!resource || !(resource in ALLOWED)) {
    return jsonError(400, "Invalid or missing resource", { resource });
  }

  const directus = baseUrl();
  if (!directus) {
    return jsonError(500, "Missing API_BASE / NEXT_PUBLIC_API_BASE env");
  }

  const sp = new URLSearchParams(url.searchParams);
  sp.delete("resource");
  sp.delete("id");

  // ✅ Optional safety clamp (prevents accidental 20k+ queries from breaking anything)
  // If you don't want this behavior, you can remove this block.
  const limitRaw = sp.get("limit");
  if (limitRaw != null) {
    const lim = Number(limitRaw);
    if (Number.isFinite(lim) && lim > 0) {
      sp.set("limit", String(Math.min(lim, 5000)));
    }
  }

  const endpoint =
    idRaw && String(idRaw).trim() !== ""
      ? `${directus}/items/${resource}/${encodeURIComponent(String(idRaw))}`
      : `${directus}/items/${resource}`;

  const finalUrl = sp.toString() ? `${endpoint}?${sp.toString()}` : endpoint;

  const auth = pickAuth(req);

  let body: any = undefined;
  if (req.method !== "GET" && req.method !== "HEAD") {
    const raw = await req.json().catch(() => null);
    body = raw?.payload ?? raw ?? null;
  }

  const res = await fetch(finalUrl, {
    method: req.method,
    headers: {
      ...(body != null ? { "Content-Type": "application/json" } : {}),
      ...(auth ? { Authorization: auth } : {}),
    },
    ...(body != null ? { body: JSON.stringify(body) } : {}),
    cache: "no-store",
  });

  // ✅ IMPORTANT: Directus DELETE commonly returns 204 No Content
  if (res.status === 204 || res.status === 205) {
    return new NextResponse(null, { status: res.status });
  }

  const text = await res.text();
  let data: any = null;
  try {
    data = text ? JSON.parse(text) : null;
  } catch {
    data = text;
  }

  // If Directus returns empty body on other statuses, still respond safely
  const companyName = process.env.API_BASE_NAME || "";

  // If data is an object, inject companyName into metadata
  if (data && typeof data === "object" && !Array.isArray(data)) {
    return NextResponse.json(
      {
        ...data,
        meta: {
          ...(data.meta || {}),
          companyName,
        },
      },
      { status: res.status },
    );
  }

  // Fallback for arrays or other types
  return NextResponse.json(
    {
      data: data ?? null,
      meta: { companyName },
    },
    { status: res.status },
  );
}

export async function GET(req: NextRequest) {
  return proxy(req);
}
export async function POST(req: NextRequest) {
  return proxy(req);
}
export async function PATCH(req: NextRequest) {
  return proxy(req);
}
export async function DELETE(req: NextRequest) {
  return proxy(req);
}

// app/api/wage-matrix/route.ts
import { NextRequest, NextResponse } from "next/server";

type HttpMethod = "GET" | "POST" | "PATCH" | "DELETE";

function corsHeaders() {
  return {
    "Access-Control-Allow-Origin": "*",
    "Access-Control-Allow-Methods": "GET, POST, PATCH, DELETE, OPTIONS",
    "Access-Control-Allow-Headers": "Content-Type, Authorization",
  };
}

export async function OPTIONS() {
  return new Response(null, {
    status: 204,
    headers: corsHeaders(),
  });
}

const API_BASE =
  process.env.API_BASE ||
  process.env.NEXT_PUBLIC_API_BASE ||
  "";

const DIRECTUS_TOKEN =
  process.env.DIRECTUS_TOKEN ||
  process.env.DIRECTUS_STATIC_TOKEN ||
  process.env.NEXT_PUBLIC_DIRECTUS_TOKEN ||
  "";

function buildUrl(path: string) {
  const base = String(API_BASE || "").replace(/\/+$/, "");
  const p = path.startsWith("/") ? path : `/${path}`;
  return `${base}${p}`;
}

async function directusFetch(method: HttpMethod, path: string, body?: unknown) {
  const url = buildUrl(path);
  const headers: Record<string, string> = {
    Accept: "application/json",
  };
  if (method !== "GET") headers["Content-Type"] = "application/json";
  if (DIRECTUS_TOKEN) headers.Authorization = `Bearer ${DIRECTUS_TOKEN}`;

  const res = await fetch(url, {
    method,
    headers,
    body: body === undefined ? undefined : JSON.stringify(body),
    cache: "no-store",
  });

  const text = await res.text();
  let json = null;
  try { json = text ? JSON.parse(text) : null; } catch (e) { }

  if (!res.ok) {
    return {
      ok: false as const,
      status: res.status,
      error: json?.errors?.[0]?.message || `Request failed (${res.status})`,
      raw: json ?? text,
    };
  }
  return { ok: true as const, status: res.status, data: json };
}

export async function GET() {
  const [areas, staff, vehicleTypes, matrix] = await Promise.all([
    directusFetch("GET", "/items/payroll_logistics_area"),
    directusFetch("GET", "/items/payroll_logistics_staff"),
    directusFetch("GET", "/items/payroll_logistics_vehicle_type"),
    directusFetch("GET", "/items/payroll_logistics_salary_matrix")
  ]);

  if (!areas.ok) return NextResponse.json({ error: areas.error }, { status: areas.status });

  return NextResponse.json({
    areas: areas.data?.data || [],
    staff: staff.ok ? (staff.data?.data || []) : [],
    vehicleTypes: vehicleTypes.ok ? (vehicleTypes.data?.data || []) : [],
    matrix: matrix.ok ? (matrix.data?.data || []) : []
  }, { headers: corsHeaders() });
}

export async function POST(req: NextRequest) {
  const payload = await req.json().catch(() => null);

  // payload should be an array of items for bulk upsert
  if (!Array.isArray(payload)) {
    return NextResponse.json({ error: "Payload must be an array of records" }, { status: 400 });
  }

  // Directus supports bulk create/update if we use the /items/collection endpoint with an array
  // However, we need to handle upsert logic. 
  // If the record has an ID, it's an update. If not, it's a create.
  // For simplicity in this specific project context, we'll use the "create many" approach 
  // or handle individual updates if needed.

  const result = await directusFetch("POST", "/items/payroll_logistics_salary_matrix", payload);
  if (!result.ok) return NextResponse.json({ error: result.error }, { status: result.status });
  return NextResponse.json(result.data, { headers: corsHeaders() });
}

export async function PATCH(req: NextRequest) {
  const payload = await req.json().catch(() => null);

  if (Array.isArray(payload)) {
    // Bulk patch
    const result = await directusFetch("PATCH", "/items/payroll_logistics_salary_matrix", payload);
    if (!result.ok) return NextResponse.json({ error: result.error }, { status: result.status });
    return NextResponse.json(result.data, { headers: corsHeaders() });
  }

  const id = payload?.id;
  if (!id) return NextResponse.json({ error: "Missing ID" }, { status: 400 });
  const result = await directusFetch("PATCH", `/items/payroll_logistics_salary_matrix/${id}`, payload);
  if (!result.ok) return NextResponse.json({ error: result.error }, { status: result.status });
  return NextResponse.json(result.data, { headers: corsHeaders() });
}

export async function DELETE(req: NextRequest) {
  const url = new URL(req.url);
  const id = url.searchParams.get("id");
  if (!id) return NextResponse.json({ error: "Missing ID" }, { status: 400 });
  const result = await directusFetch("DELETE" as any, `/items/payroll_logistics_salary_matrix/${id}`);
  if (!result.ok) return NextResponse.json({ error: result.error }, { status: result.status });
  return NextResponse.json({ message: "Deleted" }, { headers: corsHeaders() });
}

