        viewport={{ once: false, amount: 0.1 }}
        transition={{ duration: 0.8, ease: "easeOut" }}
        className="container mx-auto px-6 pt-32 pb-24 relative z-10 text-center will-change-transform will-change-opacity"
      >
        <motion.div
