import { ALLOWANCE_TYPES } from "../types";
import type {
  Allowance,
  AllowanceMode,
  AllowanceSaveMeta,
  AllowanceType,
  FormRow,
  PayCycle,
  User,
} from "../types";

import {
  computeCutoffFromDate,
  flagToBool,
  formatCurrency,
  fullnameFromUser,
  iso,
} from "../providers/allowanceApi";

interface Props {
  open: boolean;
  onOpenChange: (open: boolean) => void;

  editing: Allowance | null;

  users: User[];
  usersLoading: boolean;

  /** When creating new, default tab mode follows parent tab */
  defaultMode: AllowanceMode;

  onSave: (
    rows: FormRow[],
    employeeId: number,
    meta: AllowanceSaveMeta
  ) => Promise<void>;
}



export default function AllowanceModal({
  open,
  onOpenChange,
  editing,
  users,
  usersLoading,
  defaultMode,
  onSave,
}: Props) {
  const [formMode, setFormMode] = useState<AllowanceMode>(defaultMode);

  const [formEmployee, setFormEmployee] = useState<number | null>(null);

  // One-time reference date -> cutoff preview
  const [formDate, setFormDate] = useState(() => iso(new Date()));

  // Recurring fields
  const [payCycle, setPayCycle] = useState<PayCycle>("PER_MONTH");
  const [startDate, setStartDate] = useState<string>(() => iso(new Date()));
  const [endDate, setEndDate] = useState<string>(""); // optional
  const [isActive, setIsActive] = useState<boolean>(true);

  const [formRows, setFormRows] = useState<FormRow[]>([
    { type: "Meals", other: "", amount: "" },
  ]);

  const [employeeOpen, setEmployeeOpen] = useState(false);

  const cutoffPreview = useMemo(
    () => computeCutoffFromDate(formDate),
    [formDate]
  );

  useEffect(() => {
    if (!open) return;

    if (editing) {
      const recurring = flagToBool(editing.is_recurring);
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setFormMode(recurring ? "recurring" : "one_time");

      // eslint-disable-next-line react-hooks/set-state-in-effect
      setFormEmployee(editing.user_id);

      // One-time defaults
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setFormDate(editing.cutoff_start || iso(new Date()));

      // Recurring defaults
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setPayCycle(editing.pay_cycle || "PER_MONTH");
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setStartDate(editing.start_date || iso(new Date()));
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setEndDate(editing.end_date || "");
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setIsActive(flagToBool(editing.is_active));

      const isPreset = (ALLOWANCE_TYPES as readonly string[]).includes(
        editing.description
      );
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setFormRows([
        {
          type: (isPreset ? editing.description : "Others") as AllowanceType,
          other: isPreset ? "" : editing.description,
          amount: String(editing.amount ?? ""),
        },
      ]);
    } else {
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setFormMode(defaultMode);

      // eslint-disable-next-line react-hooks/set-state-in-effect
      setFormEmployee(null);
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setFormDate(iso(new Date()));

      // eslint-disable-next-line react-hooks/set-state-in-effect
      setPayCycle("PER_MONTH");
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setStartDate(iso(new Date()));
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setEndDate("");
      // eslint-disable-next-line react-hooks/set-state-in-effect
      setIsActive(true);

      // eslint-disable-next-line react-hooks/set-state-in-effect
      setFormRows([{ type: "Meals", other: "", amount: "" }]);
    }
  }, [open, editing, defaultMode]);

  const addFormRow = () =>
    setFormRows((s) => [...s, { type: "Meals", other: "", amount: "" }]);

  const removeFormRow = (idx: number) =>
    setFormRows((s) => s.filter((_, i) => i !== idx));

  const updateFormRow = (idx: number, patch: Partial<FormRow>) =>
    setFormRows((s) => s.map((r, i) => (i === idx ? { ...r, ...patch } : r)));

  const validateCommon = () => {
    if (!formEmployee) {
      toast.error("Select employee.");
      return false;
    }
    for (let i = 0; i < formRows.length; i++) {
      const r = formRows[i];
      if (!r.type) {
        toast.error(`Row ${i + 1}: choose description`);
        return false;
      }
      if (r.type === "Others" && !r.other?.trim()) {
        toast.error(`Row ${i + 1}: specify 'Others' description`);
        return false;
      }
      const n = Number(r.amount);
      if (!r.amount || Number.isNaN(n) || n <= 0) {
        toast.error(`Row ${i + 1}: provide valid amount`);
        return false;
      }
    }
    return true;
  };

  const handleSave = async () => {
    if (!validateCommon()) return;

    if (formMode === "one_time") {
      if (!formDate) return toast.error("Select a date for cutoff preview.");
      if (!cutoffPreview.start || !cutoffPreview.end) {
        return toast.error("Invalid cutoff date.");
      }

      const meta: AllowanceSaveMeta = {
        mode: "one_time",
        cutoff_start: cutoffPreview.start,
        cutoff_end: cutoffPreview.end,
      };

      await onSave(formRows, formEmployee!, meta);
      return;
    }

    // recurring
    if (!payCycle || payCycle === "N/A") {
      return toast.error("Select pay cycle.");
    }
    if (!startDate) return toast.error("Start date is required.");

    if (endDate && endDate < startDate) {
      return toast.error("End date must be on/after Start date.");
    }

    const meta: AllowanceSaveMeta = {
      mode: "recurring",
      pay_cycle: payCycle,
      start_date: startDate,
      end_date: endDate ? endDate : null,
      is_active: isActive,
    };

    await onSave(formRows, formEmployee!, meta);
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="w-[95vw] max-w-2xl p-0 max-h-[85vh] overflow-hidden">
        <div className="flex flex-col max-h-[85vh]">
          {/* HEADER */}
          <div className="p-6 pb-3">
            <DialogHeader>
              <DialogTitle>
                {editing ? "Edit Allowance" : "Add Allowance"}
              </DialogTitle>
              <DialogDescription>
                Fill in the details below to{" "}
                {editing ? "modify the" : "create a new"} allowance record.
              </DialogDescription>
            </DialogHeader>
          </div>

          <Separator />

          {/* SCROLLABLE BODY */}
          <div className="flex-1 overflow-y-auto px-6 py-4">
            {/* Mode Tabs */}
            <Tabs
              value={formMode}
              onValueChange={(v) => setFormMode(v as AllowanceMode)}
            >
              <TabsList className="grid w-full grid-cols-2 bg-muted/50 p-1 rounded-lg">
                <TabsTrigger value="one_time" className="rounded-md">
                  One-time Allowance
                </TabsTrigger>
                <TabsTrigger value="recurring" className="rounded-md">
                  Recurring Allowance
                </TabsTrigger>
              </TabsList>
            </Tabs>

            <div className="grid grid-cols-1 gap-5 mt-4">
              {/* Section 1: Basic Info */}
              <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                {/* Employee */}
                <div className="flex flex-col gap-2">
                  <Label>Employee</Label>
                  <Popover open={employeeOpen} onOpenChange={setEmployeeOpen}>
                    <PopoverTrigger asChild>
                      <Button
                        variant="outline"
                        role="combobox"
                        aria-expanded={employeeOpen}
                        className="w-full justify-between font-normal"
                        disabled={usersLoading}
                      >
                        {formEmployee
                          ? users.find((u) => u.user_id === formEmployee)
                            ? fullnameFromUser(
                                users.find((u) => u.user_id === formEmployee)!
                              )
                            : "Select employee..."
                          : "Select employee..."}
                        <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                      </Button>
                    </PopoverTrigger>

                    <PopoverContent className="w-[300px] p-0" align="start">
                      <Command>
                        <CommandInput placeholder="Search employee..." />
                        <CommandList>
                          <CommandEmpty>No employee found.</CommandEmpty>
                          <CommandGroup>
                            {users.map((u) => (
                              <CommandItem
                                key={u.user_id}
                                value={fullnameFromUser(u)}
                                onSelect={() => {
                                  setFormEmployee(u.user_id);
                                  setEmployeeOpen(false);
                                }}
                              >
                                <Check
                                  className={cn(
                                    "mr-2 h-4 w-4",
                                    formEmployee === u.user_id
                                      ? "opacity-100"
                                      : "opacity-0"
                                  )}
                                />
                                {fullnameFromUser(u)}
                              </CommandItem>
                            ))}
                          </CommandGroup>
                        </CommandList>
                      </Command>
                    </PopoverContent>
                  </Popover>
                </div>

                {/* Right side: mode dependent */}
                {formMode === "one_time" ? (
                  <div className="flex flex-col gap-2">
                    <Label>Date Reference</Label>
                    <Input
                      type="date"
                      value={formDate}
                      onChange={(e) => setFormDate(e.target.value)}
                    />
                    <div className="text-xs text-muted-foreground flex items-center gap-1">
                      <Info className="w-3 h-3" />
                      Cutoff:
                      <span className="font-medium text-foreground">
                        {cutoffPreview.start}
                      </span>{" "}
                      to{" "}
                      <span className="font-medium text-foreground">
                        {cutoffPreview.end}
                      </span>
                    </div>
                  </div>
                ) : (
                  <div className="flex flex-col gap-2">
                    <Label>Pay Cycle</Label>
                    <Select
                      value={payCycle}
                      onValueChange={(v) => setPayCycle(v as PayCycle)}
                    >
                      <SelectTrigger className="bg-background">
                        <SelectValue placeholder="Select pay cycle" />
                      </SelectTrigger>
                      <SelectContent>
                        <SelectItem value="PER_CUTOFF">PER_CUTOFF</SelectItem>
                        <SelectItem value="PER_MONTH">PER_MONTH</SelectItem>
                      </SelectContent>
                    </Select>

                    <div className="flex items-center justify-between pt-1">
                      <Label className="text-sm text-muted-foreground">
                        Active
                      </Label>
                      <Switch
                        checked={isActive}
                        onCheckedChange={setIsActive}
                      />
                    </div>
                  </div>
                )}
              </div>

              {/* Recurring dates */}
              {formMode === "recurring" && (
                <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                  <div className="flex flex-col gap-2">
                    <Label>Start Date</Label>
                    <Input
                      type="date"
                      value={startDate}
                      onChange={(e) => setStartDate(e.target.value)}
                    />
                  </div>
                  <div className="flex flex-col gap-2">
                    <Label>End Date (optional)</Label>
                    <Input
                      type="date"
                      value={endDate}
                      onChange={(e) => setEndDate(e.target.value)}
                    />
                  </div>
                </div>
              )}

              <Separator />

              {/* Allowance details */}
              <div>
                <Label className="text-base font-semibold">
                  Allowance Details
                </Label>

                <div className="space-y-3 mt-3">
                  {formRows.map((row, i) => (
                    <div
                      key={i}
                      className="bg-muted/30 border rounded-md p-3 grid grid-cols-12 gap-3 items-end"
                    >
                      <div className="col-span-6">
                        <Label className="text-xs text-muted-foreground mb-1 block">
                          Description
                        </Label>
                        <Select
                          value={row.type}
                          onValueChange={(v) =>
                            updateFormRow(i, {
                              type: v as AllowanceType,
                              other: "",
                            })
                          }
                        >
                          <SelectTrigger className="bg-background">
                            <SelectValue />
                          </SelectTrigger>
                          <SelectContent>
                            {ALLOWANCE_TYPES.map((t) => (
                              <SelectItem key={t} value={t}>
                                {t}
                              </SelectItem>
                            ))}
                          </SelectContent>
                        </Select>
                      </div>

                      <div className="col-span-4">
                        {row.type === "Others" ? (
                          <>
                            <Label className="text-xs text-muted-foreground mb-1 block">
                              Specify Other
                            </Label>
                            <Input
                              className="bg-background"
                              value={row.other}
                              placeholder="Specific details..."
                              onChange={(e) =>
                                updateFormRow(i, { other: e.target.value })
                              }
                            />
                          </>
                        ) : (
                          <div className="h-10" />
                        )}
                      </div>

                      <div className="col-span-2">
                        <Label className="text-xs text-muted-foreground mb-1 block">
                          Amount
                        </Label>
                        <Input
                          className="bg-background text-right"
                          value={row.amount}
                          placeholder="0.00"
                          onChange={(e) => {
                            const v = e.target.value;
                            if (/^[0-9]*\.?[0-9]{0,2}$/.test(v) || v === "")
                              updateFormRow(i, { amount: v });
                          }}
                        />
                      </div>

                      <div className="col-span-12 flex justify-between items-center">
                        <Button
                          variant="outline"
                          size="sm"
                          onClick={addFormRow}
                          className="border-dashed"
                        >
                          <Plus className="w-3.5 h-3.5 mr-2" />
                          Add Item
                        </Button>

                        {formRows.length > 1 && (
                          <Button
                            variant="ghost"
                            className="text-red-600 hover:text-red-700 hover:bg-red-50"
                            onClick={() => removeFormRow(i)}
                            size="sm"
                          >
                            <X className="h-4 w-4 mr-2" />
                            Remove
                          </Button>
                        )}
                      </div>
                    </div>
                  ))}
                </div>
              </div>

              {/* Summary (keep, but it scrolls now) */}
              <div className="bg-muted/50 rounded-lg p-4 border">
                <h4 className="text-sm font-semibold mb-3">
                  Submission Summary
                </h4>

                <div className="space-y-2 text-sm">
                  {/* Employee */}
                  <div className="flex justify-between border-b pb-2">
                    <span className="text-muted-foreground">Employee</span>
                    <span className="font-medium">
                      {formEmployee
                        ? users.find((u) => u.user_id === formEmployee)
                          ? fullnameFromUser(
                              users.find((u) => u.user_id === formEmployee)!
                            )
                          : `User ${formEmployee}`
                        : "—"}
                    </span>
                  </div>

                  {/* Mode */}
                  <div className="flex justify-between border-b pb-2">
                    <span className="text-muted-foreground">Mode</span>
                    <span className="font-medium">
                      {formMode === "one_time" ? "One-time" : "Recurring"}
                    </span>
                  </div>

                  {/* Mode-specific summary */}
                  {formMode === "one_time" ? (
                    <div className="flex justify-between border-b pb-2">
                      <span className="text-muted-foreground">Cutoff</span>
                      <span className="font-medium">
                        {cutoffPreview.start || "—"} to{" "}
                        {cutoffPreview.end || "—"}
                      </span>
                    </div>
                  ) : (
                    <>
                      <div className="flex justify-between border-b pb-2">
                        <span className="text-muted-foreground">Pay Cycle</span>
                        <span className="font-medium">{payCycle || "—"}</span>
                      </div>

                      <div className="flex justify-between border-b pb-2">
                        <span className="text-muted-foreground">
                          Start / End
                        </span>
                        <span className="font-medium">
                          {startDate || "—"} to {endDate || "—"}
                        </span>
                      </div>

                      <div className="flex justify-between border-b pb-2">
                        <span className="text-muted-foreground">Status</span>
                        <span className="font-medium">
                          {isActive ? "Active" : "Inactive"}
                        </span>
                      </div>
                    </>
                  )}

                  {/* Items */}
                  <div className="pt-1 space-y-1">
                    {formRows.length === 0 ? (
                      <div className="text-muted-foreground">No items.</div>
                    ) : (
                      formRows.map((r, i) => (
                        <div key={i} className="flex justify-between">
                          <span className="text-muted-foreground">
                            {r.type === "Others"
                              ? r.other?.trim() || "Other"
                              : r.type || "—"}
                          </span>
                          <span className="font-medium">
                            {r.amount ? formatCurrency(r.amount) : "—"}
                          </span>
                        </div>
                      ))
                    )}
                  </div>
                </div>
              </div>
            </div>
          </div>

          {/* STICKY FOOTER */}
          <div className="border-t bg-background p-4 flex items-center justify-end gap-2">
            <Button variant="ghost" onClick={() => onOpenChange(false)}>
              Cancel
            </Button>
            <Button onClick={handleSave}>
              {editing ? "Save Changes" : "Save"}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

// modules/allowance/providers/allowanceApi.ts

import useSWR from "swr";
import type {
  Allowance,
  AllowanceListParams,
  PayCycle,
  User,
} from "../types";

/** Helper interface for the API call to support ID filtering */
export interface ExtendedParams extends AllowanceListParams {
  filterUserIds?: number[] | null;
}

const API_ROUTE = "/api/allowance";

/* =========================== UTILITIES =========================== */

export function iso(date: Date) {
  return date.toISOString().split("T")[0];
}

export function formatCurrency(v: string | number) {
  const num = typeof v === "string" ? Number(v) : v;
  if (Number.isNaN(num)) return String(v);
  return new Intl.NumberFormat("en-PH", {
    style: "currency",
    currency: "PHP",
    maximumFractionDigits: 2,
  }).format(num);
}

export function fullnameFromUser(u: User) {
  if (!u) return "Unknown";
  return `${u.user_fname}${u.user_mname ? " " + u.user_mname : ""} ${u.user_lname}`;
}

/**
 * Normalizes Directus/DB-ish truthy values.
 * Supports: boolean, 0/1, "0"/"1", { type:"Buffer", data:[0|1] }
 */
export function flagToBool(v: unknown): boolean {
  if (typeof v === "boolean") return v;
  if (typeof v === "number") return v === 1;
  if (typeof v === "string") return v === "1" || v.toLowerCase() === "true";
  if (v && typeof v === "object") {
    const maybe = v as { data?: unknown };
    if (Array.isArray(maybe.data) && maybe.data.length > 0) {
      return maybe.data[0] === 1;
    }
  }
  return false;
}

export function computeCutoffFromDate(dStr: string) {
  if (!dStr) return { start: "", end: "" };
  const d = new Date(dStr);
  if (Number.isNaN(d.getTime())) return { start: "", end: "" };

  const day = d.getDate();
  const y = d.getFullYear();
  const m = d.getMonth();

  let start: Date;
  let end: Date;

  // 11–25
  if (day >= 11 && day <= 25) {
    start = new Date(y, m, 11);
    end = new Date(y, m, 25);
  } else if (day >= 26) {
    // 26–10 (cross month)
    start = new Date(y, m, 26);
    end = new Date(y, m + 1, 10);
  } else {
    // 1–10 -> previous month 26–current month 10
    start = new Date(y, m - 1, 26);
    end = new Date(y, m, 10);
  }

  return { start: iso(start), end: iso(end) };
}

/* =========================== FETCHERS & API CALLS =========================== */

const fetcher = (url: string) =>
  fetch(url).then(async (r) => {
    if (!r.ok) {
      const text = await r.text();
      try {
        const json = JSON.parse(text);
        throw new Error(json.error || r.statusText);
      } catch {
        throw new Error(text || r.statusText);
      }
    }
    return r.json();
  });

async function getUsers(): Promise<User[]> {
  const json = await fetcher(`${API_ROUTE}?mode=users`);
  return json?.data ?? json ?? [];
}

function appendInFilter(sp: URLSearchParams, key: string, values: number[]) {
  // Directus expects comma-separated list
  sp.append(key, values.join(","));
}

async function getAllowancesList(params: ExtendedParams) {
  const sp = new URLSearchParams();

  sp.append("limit", String(params.pageSize));
  sp.append("offset", String((params.page - 1) * params.pageSize));
  sp.append("meta", "filter_count");
  sp.append("sort", "-created_date");

  // Always filter by mode
  if (params.mode === "one_time") {
    sp.append("filter[is_recurring][_eq]", "0");

    if (params.status === "processed") sp.append("filter[is_processed][_eq]", "1");
    if (params.status === "unprocessed") sp.append("filter[is_processed][_eq]", "0");
  } else {
    sp.append("filter[is_recurring][_eq]", "1");

    if (params.status === "active") sp.append("filter[is_active][_eq]", "1");
    if (params.status === "inactive") sp.append("filter[is_active][_eq]", "0");

    // Pay cycle filter (recurring only)
    if (params.payCycle && params.payCycle !== "all") {
      sp.append("filter[pay_cycle][_eq]", params.payCycle);
    }
  }

  // Description filter
  if (params.searchDescription?.trim()) {
    sp.append("filter[description][_icontains]", params.searchDescription.trim());
  }

  // Employee filter by IDs (client-side match)
  if (params.filterUserIds !== undefined && params.filterUserIds !== null) {
    if (params.filterUserIds.length > 0) {
      appendInFilter(sp, "filter[user_id][_in]", params.filterUserIds);
    } else {
      // Force 0 results
      sp.append("filter[user_id][_in]", "-1");
    }
  }

  const json = await fetcher(`${API_ROUTE}?${sp.toString()}`);

  const rows: Allowance[] = json?.data ?? [];
  const total: number = json?.meta?.filter_count ?? json?.meta?.total ?? rows.length;

  return { rows, total };
}

export async function createAllowance(payload: Partial<Allowance>) {
  const res = await fetch(API_ROUTE, {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });

  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err.error || "Create failed");
  }

  return res.json();
}

export async function updateAllowance(id: number, payload: Partial<Allowance>) {
  const res = await fetch(`${API_ROUTE}?id=${id}`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify(payload),
  });

  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err.error || "Update failed");
  }

  return res.json();
}

export async function deleteAllowance(id: number) {
  const res = await fetch(`${API_ROUTE}?id=${id}`, {
    method: "DELETE",
  });

  if (!res.ok) {
    const err = await res.json().catch(() => ({}));
    throw new Error(err.error || "Delete failed");
  }

  return res;
}

/* =========================== HOOKS =========================== */

export function useUsers() {
  const { data, error } = useSWR(`${API_ROUTE}?mode=users`, getUsers, {
    revalidateOnFocus: false,
  });

  return { users: data ?? [], loading: !data && !error, error };
}

export function useAllowancesQuery(params: ExtendedParams) {
  // include filterUserIds in key so SWR refetches when IDs change
  const userIdsKey =
    params.filterUserIds === null || params.filterUserIds === undefined
      ? "all"
      : params.filterUserIds.join(",");

  const key = [
    API_ROUTE,
    params.page,
    params.pageSize,
    params.mode,
    params.status ?? "all",
    params.payCycle ?? "all",
    userIdsKey,
    params.searchDescription ?? "",
  ];

  const { data, error, isLoading, mutate } = useSWR(
    key,
    () => getAllowancesList(params),
    {
      keepPreviousData: true,
      revalidateOnFocus: false,
    }
  );

  return {
    rows: data?.rows ?? [],
    total: data?.total ?? 0,
    loading: isLoading,
    error,
    mutate,
  };
}

"use client";

import { motion } from "framer-motion";
import LoginForm from "./components/LoginForm";
import { useLogin } from "./providers/useLogin";
import Link from "next/link";
import { Shield, Zap, Lock } from "lucide-react";

export default function LoginModule() {
  const { login, loading } = useLogin();

  return (
    <div className="relative min-h-screen flex items-center justify-center px-4 overflow-hidden bg-slate-950">
      {/* Premium Background */}
      <div className="absolute inset-0 z-0">
        <img
          src="/images/bg/login-bg.png"
          alt="Login Background"
          className="w-full h-full object-cover"
          style={{ imageRendering: "crisp-edges" }}
        />
        <div className="absolute inset-0 bg-gradient-to-br from-slate-950/60 via-slate-950/40 to-slate-950/65" />
        <div className="absolute inset-0 bg-gradient-to-t from-slate-950/80 via-transparent to-slate-950/20" />
      </div>

      {/* Animated Glow Orbs */}
      <motion.div
        animate={{ opacity: [0.4, 0.7, 0.4], scale: [1, 1.1, 1] }}
        transition={{ duration: 8, repeat: Infinity, ease: "easeInOut" }}
        className="absolute top-1/4 left-1/4 w-[500px] h-[500px] bg-cyan-500/10 blur-[130px] rounded-full"
      />
      <motion.div
        animate={{ opacity: [0.3, 0.6, 0.3], scale: [1, 1.15, 1] }}
        transition={{ duration: 10, repeat: Infinity, ease: "easeInOut", delay: 3 }}
