"use client";

import * as React from "react";
import { FileDown, Search, Filter } from "lucide-react";
import { formatMoney } from "../providers/benefitApi";
import type { BenefitLogRow, BenefitCode, UserData, CutoffSetting } from "../types";
import { exportBenefitLogsPdf, type BenefitLogsPaperSize } from "../utils/benefitLogsPdf";
import { cutoffLabel, fullnameFromUser } from "../providers/benefitApi";
import { PdfPreviewModal } from "@/components/PdfPreviewModal";

import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Badge } from "@/components/ui/badge";
import { ScrollArea } from "@/components/ui/scroll-area";
import { Separator } from "@/components/ui/separator";

interface BenefitExportPreviewDialogProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  allRows: BenefitLogRow[];
  users: UserData[];
  initialCutoffRange: string;
  initialBenefit: BenefitCode | "ALL";
  initialType: "ALL" | "CONTRIBUTION" | "LOAN";
  initialPaper: BenefitLogsPaperSize;
  companyName: string;
}

export default function BenefitExportPreviewDialog({
  open,
  onOpenChange,
  allRows,
  users,
  initialCutoffRange,
  initialBenefit,
  initialType,
  initialPaper,
  companyName,
}: BenefitExportPreviewDialogProps) {
  const [cutoffRange, setCutoffRange] = React.useState<string>(initialCutoffRange);
  const [benefit, setBenefit] = React.useState<BenefitCode | "ALL">(initialBenefit);
  const [type, setType] = React.useState<"ALL" | "CONTRIBUTION" | "LOAN">(initialType);
  const [paper, setPaper] = React.useState<BenefitLogsPaperSize>(initialPaper);
  const [exporting, setExporting] = React.useState(false);
  const [previewOpen, setPreviewOpen] = React.useState(false);
  const [pdfBlob, setPdfBlob] = React.useState<Blob | null>(null);

  const filtered = React.useMemo(() => {
    return allRows.filter((r) => {
      if (cutoffRange !== "ALL") {
        if (cutoffRange === "UNKNOWN") {
          if (r.cutoff_start || r.cutoff_end) return false;
        } else {
          const key = `${r.cutoff_start}_${r.cutoff_end}`;
          if (key !== cutoffRange) return false;
        }
      }
      if (benefit !== "ALL" && r.benefit_code !== benefit) return false;
      if (type !== "ALL" && r.log_type !== type) return false;
      return true;
    });
  }, [allRows, cutoffRange, benefit, type]);

  const totals = React.useMemo(() => {
    return filtered.reduce((acc, r) => acc + (r.deducted_amount || 0), 0);
  }, [filtered]);

  const onPreview = async () => {
    setExporting(true);
    try {
      const doc = await exportBenefitLogsPdf({
        paper,
        companyName,
        title: benefit === "ALL" ? "Benefit Logs Summary" : `${benefit} Benefit Logs`,
        users,
        cutoffRange,
        benefit,
        type,
        search: "", 
        rows: filtered,
      });
      const blob = doc.output("blob");
      setPdfBlob(blob);
      setPreviewOpen(true);
    } finally {
      setExporting(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="!w-[95vw] !max-w-7xl max-h-[95vh] flex flex-col p-0 overflow-hidden dark:bg-gray-900 dark:border-gray-800">
        <DialogHeader className="px-6 py-4 border-b dark:border-gray-800">
          <DialogTitle className="flex items-center gap-2">
            <FileDown className="h-5 w-5 text-blue-600" />
            PDF Export Preview
          </DialogTitle>
        </DialogHeader>

        <div className="flex flex-col flex-1 overflow-hidden p-6 gap-6 dark:bg-gray-950/20">
          {/* Selections / Filters */}
          <div className="grid grid-cols-1 md:grid-cols-4 gap-4 items-end">
            <div className="space-y-1.5">
              <label className="text-xs font-semibold text-slate-500 dark:text-gray-400 uppercase tracking-wider">
                Cutoff
              </label>
              <Select value={cutoffRange} onValueChange={setCutoffRange}>
                <SelectTrigger className="bg-slate-50 dark:bg-gray-800 h-auto min-h-[36px] py-1 flex-wrap whitespace-normal text-left dark:border-gray-700 dark:text-gray-100">
                  <SelectValue placeholder="All" />
                </SelectTrigger>
                <SelectContent className="max-w-[400px] dark:bg-gray-900 dark:border-gray-800">
                  <SelectItem value="ALL" className="dark:text-gray-200 dark:focus:bg-gray-800">All Cutoffs</SelectItem>
                  {(() => {
                    const uniqueRanges = new Map<string, string>();
                    const fmt = (dStr: string) => {
                      const d = new Date(dStr);
                      if (Number.isNaN(d.getTime())) return dStr;
                      return d.toLocaleDateString(undefined, { year: "numeric", month: "short", day: "2-digit" });
                    };
                    
                    for (const r of allRows) {
                      if (r.cutoff_start && r.cutoff_end) {
                        const key = `${r.cutoff_start}_${r.cutoff_end}`;
                        if (!uniqueRanges.has(key)) {
                          uniqueRanges.set(key, `${fmt(r.cutoff_start)} – ${fmt(r.cutoff_end)}`);
                        }
                      } else {
                        uniqueRanges.set("UNKNOWN", "Unknown Cutoff");
                      }
                    }

                    // Sort ranges visually
                    const sortedRanges = Array.from(uniqueRanges.entries()).sort((a, b) => b[0].localeCompare(a[0]));

                    return sortedRanges.map(([key, label]) => (
                      <SelectItem key={key} value={key}>
                        {label}
                      </SelectItem>
                    ));
                  })()}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-semibold text-slate-500 dark:text-gray-400 uppercase tracking-wider">
                Benefit
              </label>
              <Select value={benefit} onValueChange={(v) => setBenefit(v as any)}>
                <SelectTrigger className="bg-slate-50 dark:bg-gray-800 h-auto min-h-[36px] dark:border-gray-700 dark:text-gray-100">
                  <SelectValue placeholder="All Benefits" />
                </SelectTrigger>
                <SelectContent className="dark:bg-gray-900 dark:border-gray-800">
                  <SelectItem value="ALL" className="dark:text-gray-200 dark:focus:bg-gray-800">All Benefits</SelectItem>
                  <SelectItem value="SSS">SSS</SelectItem>
                  <SelectItem value="PHILHEALTH">PhilHealth</SelectItem>
                  <SelectItem value="PAGIBIG">Pag-IBIG</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-semibold text-slate-500 dark:text-gray-400 uppercase tracking-wider">
                Type
              </label>
              <Select value={type} onValueChange={(v) => setType(v as any)}>
                <SelectTrigger className="bg-slate-50 dark:bg-gray-800 h-auto min-h-[36px] dark:border-gray-700 dark:text-gray-100">
                  <SelectValue placeholder="All Types" />
                </SelectTrigger>
                <SelectContent className="dark:bg-gray-900 dark:border-gray-800">
                  <SelectItem value="ALL" className="dark:text-gray-200 dark:focus:bg-gray-800">All Types</SelectItem>
                  <SelectItem value="CONTRIBUTION">Contributions</SelectItem>
                  <SelectItem value="LOAN">Loans</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-1.5">
              <label className="text-xs font-semibold text-slate-500 dark:text-gray-400 uppercase tracking-wider">
                Paper Size
              </label>
              <Select value={paper} onValueChange={(v) => setPaper(v as BenefitLogsPaperSize)}>
                <SelectTrigger className="bg-slate-50 dark:bg-gray-800 h-auto min-h-[36px] dark:border-gray-700 dark:text-gray-100">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent className="dark:bg-gray-900 dark:border-gray-800">
                  <SelectItem value="LETTER">Letter</SelectItem>
                  <SelectItem value="A4">A4</SelectItem>
                  <SelectItem value="LEGAL">Legal</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          <Separator />

          {/* Preview Table */}
          <div className="flex-1 flex flex-col overflow-hidden bg-white dark:bg-gray-900 border dark:border-gray-800 rounded-xl shadow-inner">
            <div className="bg-slate-50/80 dark:bg-gray-800/80 px-4 py-2 flex justify-between items-center border-b dark:border-gray-800">
              <span className="text-sm font-medium text-slate-600 dark:text-gray-400">
                {filtered.length} entries matching selection
              </span>
              <span className="text-sm font-bold text-slate-900 dark:text-gray-100 border-l dark:border-gray-700 pl-4">
                Total: {formatMoney(totals)}
              </span>
            </div>
            
            <ScrollArea className="flex-1">
              <Table>
                <TableHeader className="sticky top-0 bg-white dark:bg-gray-900 shadow-sm z-10">
                  <TableRow>
                    <TableHead className="w-[200px]">Employee</TableHead>
                    <TableHead>Account #</TableHead>
                    <TableHead className="text-right">Deducted</TableHead>
                    <TableHead>Type</TableHead>
                    <TableHead>Benefit</TableHead>
                  </TableRow>
                </TableHeader>
                <TableBody>
                  {filtered.length === 0 ? (
                    <TableRow>
                      <TableCell colSpan={5} className="h-32 text-center text-slate-400 italic">
                        No data available for the selected filters.
                      </TableCell>
                    </TableRow>
                  ) : (
                    filtered.map((r) => {
                      const uId = typeof r.user_id === "object" ? (r.user_id as any)?.user_id : r.user_id;
                      const u = users.find((x) => x.user_id === uId);
                      const name = r.employee_name || (u ? fullnameFromUser(u) : `User #${uId}`);
                      return (
                      <TableRow key={r.benefit_log_id} className="text-xs border-b dark:border-gray-800">
                        <TableCell className="font-medium dark:text-gray-200">{name}</TableCell>
                        <TableCell className="font-mono text-slate-500 dark:text-gray-400">{r.account_no || "—"}</TableCell>
                        <TableCell className="text-right font-semibold dark:text-gray-100">{formatMoney(r.deducted_amount)}</TableCell>
                        <TableCell>
                          <Badge variant={r.log_type === "LOAN" ? "secondary" : "outline"} className="text-[10px] scale-90 origin-left dark:bg-gray-800 dark:text-gray-300">
                            {r.log_type}
                          </Badge>
                        </TableCell>
                        <TableCell className="font-mono dark:text-gray-300">{r.benefit_code}</TableCell>
                      </TableRow>
                      );
                    })
                  )}
                </TableBody>
              </Table>
            </ScrollArea>
          </div>
        </div>

        <DialogFooter className="px-6 py-4 border-t dark:border-gray-800 bg-slate-50/50 dark:bg-gray-800/50">
          <Button variant="ghost" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
          <Button 
            className="bg-blue-600 hover:bg-blue-700 text-white min-w-[140px]" 
            disabled={exporting || filtered.length === 0}
            onClick={onPreview}
          >
            {exporting ? (
              "Processing..."
            ) : (
              <>
                <FileDown className="mr-2 h-4 w-4" />
                Preview PDF
              </>
            )}
          </Button>
        </DialogFooter>

        <PdfPreviewModal
          isOpen={previewOpen}
          onClose={() => setPreviewOpen(false)}
          title={benefit === "ALL" ? "Benefit Logs Summary" : `${benefit} Benefit Logs`}
          pdfBlob={pdfBlob}
          fileName={`benefit-logs-${new Date().toISOString().slice(0, 10)}.pdf`}
        />
      </DialogContent>
    </Dialog>
  );
}

// modules/benefit-settings/components/BenefitLogsTab.tsx
"use client";

import * as React from "react";
import { toast } from "sonner";
import { RefreshCcw, FileDown, Sigma } from "lucide-react";

import type {
  BenefitCode,
  BenefitLogRow,
  CutoffSetting,
  UserData,
} from "../types";
import {
  fetchBenefitLogs,
  fetchCutoffSettings,
  fetchCompanyConfig,
  cutoffLabel,
  formatMoney,
} from "../providers/benefitApi";
import {
  exportBenefitLogsPdf,
  type BenefitLogsPaperSize,
} from "../utils/benefitLogsPdf";
import { BenefitTableSkeleton } from "./BenefitSettingsSkeleton";
import BenefitExportPreviewDialog from "./BenefitExportPreviewDialog";

import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
  DialogFooter,
} from "@/components/ui/dialog";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";

function userName(users: UserData[], userId: number) {
  const u = users.find((x) => x.user_id === userId);
  return u ? `${u.user_fname} ${u.user_lname}`.trim() : `User #${userId}`;
}

export default function BenefitLogsTab({ users }: { users: UserData[] }) {
  const [loading, setLoading] = React.useState(true);
  const [refreshing, setRefreshing] = React.useState(false);
  const [exporting, setExporting] = React.useState(false);
  const [companyName, setCompanyName] = React.useState("MEN2 MARKETING CORPORATION");

  const [cutoffs, setCutoffs] = React.useState<CutoffSetting[]>([]);
  const cutoffMap = React.useMemo(
    () => new Map(cutoffs.map((c) => [c.id, c] as const)),
    [cutoffs]
  );

  const [rows, setRows] = React.useState<BenefitLogRow[]>([]);

  // Filters
  const [q, setQ] = React.useState("");
  const [cutoffRange, setCutoffRange] = React.useState<string>("ALL");
  const [benefit, setBenefit] = React.useState<BenefitCode | "ALL">("ALL");
  const [type, setType] = React.useState<"ALL" | "CONTRIBUTION" | "LOAN">(
    "ALL"
  );

  // Export
  const [paper, setPaper] = React.useState<BenefitLogsPaperSize>("LETTER");

  // Summary modal
  const [summaryOpen, setSummaryOpen] = React.useState(false);

  // Export Preview
  const [previewOpen, setPreviewOpen] = React.useState(false);

  const load = React.useCallback(async () => {
    setLoading(true);
    try {
      const [c, l, config] = await Promise.all([
        fetchCutoffSettings(),
        fetchBenefitLogs(),
        fetchCompanyConfig(),
      ]);
      setCutoffs(c);
      setRows(l);
      if (config?.companyName) {
        setCompanyName(config.companyName);
      }
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : "Failed to load benefit logs.";
      toast.error(msg);
    } finally {
      setLoading(false);
    }
  }, []);

  React.useEffect(() => {
    load();
  }, [load]);

  const onRefresh = React.useCallback(async () => {
    setRefreshing(true);
    try {
      const l = await fetchBenefitLogs();
      setRows(l);
      toast.success("Logs refreshed.");
    } catch (e: unknown) {
      const msg = e instanceof Error ? e.message : "Failed to refresh logs.";
      toast.error(msg);
    } finally {
      setRefreshing(false);
    }
  }, []);

  const filtered = React.useMemo(() => {
    const needle = q.trim().toLowerCase();

    return rows.filter((r) => {
      if (cutoffRange !== "ALL") {
        if (cutoffRange === "UNKNOWN") {
          if (r.cutoff_start || r.cutoff_end) return false;
        } else {
          const key = `${r.cutoff_start}_${r.cutoff_end}`;
          if (key !== cutoffRange) return false;
        }
      }
      if (benefit !== "ALL" && r.benefit_code !== benefit) return false;
      if (type !== "ALL" && r.log_type !== type) return false;

      if (!needle) return true;
      const name = (r.employee_name || userName(users, r.user_id)).toLowerCase();
      const account = (r.account_no ?? "").toLowerCase();
      const payrollId = (r.payroll_ref_no ?? "").toLowerCase();
      const note = (r.note ?? "").toLowerCase();

      return (
        name.includes(needle) ||
        account.includes(needle) ||
        payrollId.includes(needle) ||
        note.includes(needle) ||
        String(r.user_id).includes(needle)
      );
    });
  }, [rows, q, cutoffRange, benefit, type, users]);

  const totals = React.useMemo(() => {
    const sumBy: Record<string, number> = {
      SSS: 0,
      PAGIBIG: 0,
      PHILHEALTH: 0,
      ALL: 0,
    };
    for (const r of filtered) {
      sumBy[r.benefit_code] =
        (sumBy[r.benefit_code] || 0) + (r.deducted_amount || 0);
      sumBy.ALL += r.deducted_amount || 0;
    }
    return sumBy;
  }, [filtered]);

  const onOpenExportPreview = React.useCallback(() => {
    if (rows.length === 0) {
      toast.error("No data available to export.");
      return;
    }
    setPreviewOpen(true);
  }, [rows]);

  return (
    <div className="space-y-4">
      {/* Filters row (modern alignment) */}
      <div className="rounded-xl border border-slate-200 dark:border-gray-800 bg-white dark:bg-gray-900 p-4 shadow-sm">
        <div className="flex flex-col gap-3 xl:flex-row xl:items-end xl:justify-between">
          {/* Left: Filters */}
          <div className="grid w-full grid-cols-1 gap-3 sm:grid-cols-2 lg:grid-cols-4">
            <div className="space-y-1">
              <div className="text-xs font-medium text-slate-600 dark:text-gray-400">Search</div>
              <Input
                value={q}
                onChange={(e) => setQ(e.target.value)}
                placeholder="Employee or note…"
                className="h-9 dark:bg-gray-800 dark:border-gray-700 dark:text-gray-100 placeholder:text-gray-500"
              />
            </div>

            <div className="space-y-1">
              <div className="text-xs font-medium text-slate-600 dark:text-gray-400">Cutoff</div>
              <Select value={cutoffRange} onValueChange={setCutoffRange}>
                <SelectTrigger className="h-9">
                  <SelectValue placeholder="All" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="ALL">All</SelectItem>
                  {(() => {
                    const uniqueRanges = new Map<string, string>();
                    const fmt = (dStr: string) => {
                      const d = new Date(dStr);
                      if (Number.isNaN(d.getTime())) return dStr;
                      return d.toLocaleDateString(undefined, { year: "numeric", month: "short", day: "2-digit" });
                    };
                    
                    for (const r of rows) {
                      if (r.cutoff_start && r.cutoff_end) {
                        const key = `${r.cutoff_start}_${r.cutoff_end}`;
                        if (!uniqueRanges.has(key)) {
                          uniqueRanges.set(key, `${fmt(r.cutoff_start)} – ${fmt(r.cutoff_end)}`);
                        }
                      } else {
                        uniqueRanges.set("UNKNOWN", "Unknown Cutoff");
                      }
                    }

                    // Sort ranges descending by explicit date bounds
                    const sortedRanges = Array.from(uniqueRanges.entries()).sort((a, b) => b[0].localeCompare(a[0]));

                    return sortedRanges.map(([key, label]) => (
                      <SelectItem key={key} value={key}>
                        {label}
                      </SelectItem>
                    ));
                  })()}
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-1">
              <div className="text-xs font-medium text-slate-600 dark:text-gray-400">Benefit</div>
              <Select
                value={benefit}
                onValueChange={(v) => setBenefit(v as BenefitCode | "ALL")}
              >
                <SelectTrigger className="h-9">
                  <SelectValue placeholder="All" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="ALL">All</SelectItem>
                  <SelectItem value="SSS">SSS</SelectItem>
                  <SelectItem value="PAGIBIG">PAGIBIG</SelectItem>
                  <SelectItem value="PHILHEALTH">PHILHEALTH</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <div className="space-y-1">
              <div className="text-xs font-medium text-slate-600 dark:text-gray-400">Type</div>
              <Select value={type} onValueChange={(v) => setType(v as "ALL" | "CONTRIBUTION" | "LOAN")}>
                <SelectTrigger className="h-9">
                  <SelectValue placeholder="All" />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="ALL">All</SelectItem>
                  <SelectItem value="CONTRIBUTION">Contribution</SelectItem>
                  <SelectItem value="LOAN">Loan</SelectItem>
                </SelectContent>
              </Select>
            </div>
          </div>

          {/* Right: Summary + export controls */}
          <div className="flex flex-col gap-2 sm:flex-row sm:items-end sm:justify-end">
            <Button
              variant="outline"
              className="h-9"
              onClick={() => setSummaryOpen(true)}
            >
              <Sigma className="mr-2 h-4 w-4" />
              Summary totals
            </Button>

            <div className="min-w-[180px] space-y-1">
              <div className="text-xs font-medium text-slate-600 dark:text-gray-400">
                Paper size
              </div>
              <Select
                value={paper}
                onValueChange={(v) => setPaper(v as BenefitLogsPaperSize)}
              >
                <SelectTrigger className="h-9">
                  <SelectValue />
                </SelectTrigger>
                <SelectContent>
                  <SelectItem value="LETTER">Letter</SelectItem>
                  <SelectItem value="A4">A4</SelectItem>
                  <SelectItem value="LEGAL">Legal</SelectItem>
                </SelectContent>
              </Select>
            </div>

            <Button
              className="h-9"
              onClick={onOpenExportPreview}
              disabled={loading || rows.length === 0}
            >
              <FileDown className="mr-2 h-4 w-4" />
              Export PDF
            </Button>

            <Button
              variant="outline"
              className="h-9"
              onClick={onRefresh}
              disabled={refreshing}
            >
              <RefreshCcw className="mr-2 h-4 w-4" />
              Refresh
            </Button>
          </div>
        </div>
      </div>

      <Separator />

      {/* Table */}
      <div className="rounded-xl border border-slate-200 dark:border-gray-800 bg-white dark:bg-gray-900 shadow-sm">
        <Table>
          <TableHeader>
            <TableRow className="bg-slate-50 dark:bg-gray-800/50">
              <TableHead>Employee</TableHead>
              <TableHead>Account #</TableHead>
              <TableHead className="text-right">Deducted</TableHead>
              <TableHead>Payroll ID</TableHead>
              <TableHead>Type</TableHead>
              <TableHead>Posted Date</TableHead>
              <TableHead>Benefit</TableHead>
            </TableRow>
          </TableHeader>

          <TableBody>
            {loading ? (
              <BenefitTableSkeleton columns={8} />
            ) : filtered.length === 0 ? (
              <TableRow>
                <TableCell
                  colSpan={8}
                  className="py-10 text-center text-sm text-slate-500"
                >
                  No logs found. (Logs appear after payroll run posting.)
                </TableCell>
              </TableRow>
            ) : (
              filtered.map((r) => {
                const c = cutoffMap.get(r.cutoff_id);
                const postedDate = r.posted_at
                  ? new Date(r.posted_at).toLocaleDateString(undefined, {
                      year: "numeric",
                      month: "short",
                      day: "2-digit",
                    })
                  : "—";

                return (
                  <TableRow
                    key={r.benefit_log_id}
                    className="hover:bg-slate-50/60 dark:hover:bg-gray-800/40 border-b dark:border-gray-800"
                  >
                    <TableCell className="font-medium dark:text-gray-200">
                      {r.employee_name || userName(users, r.user_id)}
                    </TableCell>
                    <TableCell className="font-mono text-xs text-slate-600 dark:text-gray-400">
                      {r.account_no || "—"}
                    </TableCell>
                    <TableCell className="text-right tabular-nums font-semibold text-slate-900 dark:text-gray-100">
                      {formatMoney(r.deducted_amount)}
                    </TableCell>
                    <TableCell className="text-sm font-medium text-blue-600 dark:text-blue-400">
                      {r.payroll_ref_no || "—"}
                    </TableCell>
                    <TableCell>
                      {r.log_type === "LOAN" ? (
                        <Badge
                          variant="secondary"
                          className="bg-amber-50 dark:bg-amber-900/20 text-amber-700 dark:text-amber-400 border-amber-200 dark:border-amber-900/40"
                        >
                          Loan
                        </Badge>
                      ) : (
                        <Badge
                          variant="outline"
                          className="bg-blue-50 dark:bg-blue-900/20 text-blue-700 dark:text-blue-400 border-blue-200 dark:border-blue-900/40"
                        >
                          Contribution
                        </Badge>
                      )}
                    </TableCell>
                    <TableCell className="text-sm text-slate-500 dark:text-gray-400">
                      {postedDate}
                    </TableCell>
                    <TableCell>
                      <Badge
                        variant="outline"
                        className="font-mono text-[10px] uppercase bg-slate-50 dark:bg-gray-800 dark:border-gray-700 dark:text-gray-300"
                      >
                        {r.benefit_code}
                      </Badge>
                    </TableCell>
                  </TableRow>
                );
              })
            )}
          </TableBody>
        </Table>
      </div>

      {/* Summary Totals Modal */}
      <Dialog open={summaryOpen} onOpenChange={setSummaryOpen}>
        <DialogContent className="max-w-md dark:bg-gray-900 dark:border-gray-800">
          <DialogHeader>
            <DialogTitle>Summary totals</DialogTitle>
            <DialogDescription>
              Totals reflect the current filters and search result.
            </DialogDescription>
          </DialogHeader>

          <div className="space-y-3">
            <div className="rounded-lg border dark:border-gray-800 bg-slate-50 dark:bg-gray-800/50 p-3">
              <div className="flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <Badge variant="outline" className="font-mono text-[10px] bg-white dark:bg-gray-900 dark:border-gray-700 dark:text-gray-300">
                    SSS
                  </Badge>
                  <span className="text-sm text-slate-600 dark:text-gray-400">Deducted</span>
                </div>
                <div className="tabular-nums font-semibold">
                  {formatMoney(totals.SSS)}
                </div>
              </div>

              <div className="mt-2 flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <Badge variant="outline" className="font-mono text-[10px] bg-white dark:bg-gray-900 dark:border-gray-700 dark:text-gray-300">
                    PAGIBIG
                  </Badge>
                  <span className="text-sm text-slate-600 dark:text-gray-400">Deducted</span>
                </div>
                <div className="tabular-nums font-semibold">
                  {formatMoney(totals.PAGIBIG)}
                </div>
              </div>

              <div className="mt-2 flex items-center justify-between">
                <div className="flex items-center gap-2">
                  <Badge variant="outline" className="font-mono text-[10px] bg-white dark:bg-gray-900 dark:border-gray-700 dark:text-gray-300">
                    PH
                  </Badge>
                  <span className="text-sm text-slate-600 dark:text-gray-400">Deducted</span>
                </div>
                <div className="tabular-nums font-semibold">
                  {formatMoney(totals.PHILHEALTH)}
                </div>
              </div>

              <div className="mt-3 border-t dark:border-gray-800 pt-3 flex items-center justify-between">
                <span className="text-sm font-semibold dark:text-gray-200">Total</span>
                <span className="tabular-nums text-base font-bold dark:text-gray-100">
                  {formatMoney(totals.ALL)}
                </span>
              </div>
            </div>

            <div className="text-xs text-slate-500 dark:text-gray-400">
              Rows included:{" "}
              <span className="font-medium text-slate-700 dark:text-gray-300">
                {filtered.length}
              </span>
            </div>
          </div>

          <DialogFooter>
            <Button variant="outline" onClick={() => setSummaryOpen(false)}>
              Close
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>

      {/* Export Preview */}
      <BenefitExportPreviewDialog
        open={previewOpen}
        onOpenChange={setPreviewOpen}
        allRows={rows}
        users={users}
        initialCutoffRange={cutoffRange}
        initialBenefit={benefit}
        initialType={type}
        initialPaper={paper}
        companyName={companyName}
      />
    </div>
  );
}

// modules/benefit-settings/components/LoanScheduleDialog.tsx
"use client";

import * as React from "react";
import { CheckCircle2, Circle } from "lucide-react";

import type { BenefitLoan, CutoffSetting } from "../types";
import {
  cutoffLabel,
  computeLoanCutoffSchedule,
} from "../providers/benefitApi";

import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";
import { Separator } from "@/components/ui/separator";

export default function LoanScheduleDialog(props: {
  open: boolean;
  onOpenChange: (v: boolean) => void;
  loan: BenefitLoan | null;
  cutoffs: CutoffSetting[];
}) {
  const { open, onOpenChange, loan, cutoffs } = props;

  const sched = React.useMemo(() => {
    if (!loan) {
      return {
        all: [],
        paid: [],
        upcoming: [],
        nextDue: null,
        endDue: null,
      } as any;
    }
    return computeLoanCutoffSchedule({ loan, cutoffs });
  }, [loan, cutoffs]);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="max-w-2xl dark:bg-gray-900 dark:border-gray-800">
        <DialogHeader>
          <DialogTitle>Loan Schedule</DialogTitle>
          <DialogDescription>
            This schedule is computed from the loan’s start cutoff, deduct rule,
            terms, and paid installments.
          </DialogDescription>
        </DialogHeader>

        {!loan ? (
          <div className="text-sm text-slate-500 dark:text-gray-400">No loan selected.</div>
        ) : (
          <div className="space-y-3">
            <div className="rounded-lg border border-slate-200 dark:border-gray-800 bg-slate-50 dark:bg-gray-800/50 p-3 text-sm">
              <div className="font-medium dark:text-gray-200">
                {loan.benefit_code} — {loan.loan_name || "Loan"}
              </div>
              <div className="text-xs text-slate-600 dark:text-gray-400">
                Deduct: {loan.deduct_on} • Terms: {loan.terms_installments} •
                Paid: {loan.paid_installments}
              </div>
              {sched.nextDue ? (
                <div className="mt-2 text-xs text-slate-700 dark:text-gray-300">
                  Next Due:{" "}
                  <span className="font-medium">
                    {cutoffLabel(sched.nextDue)}
                  </span>
                </div>
              ) : (
                <div className="mt-2 text-xs text-slate-600 dark:text-gray-400">
                  No upcoming due cutoffs.
                </div>
              )}
            </div>

            <Separator />

            <div className="max-h-[360px] overflow-auto space-y-2 pr-1">
              {sched.all.length === 0 ? (
                <div className="text-sm text-slate-500">
                  No computed schedule (start cutoff not found).
                </div>
              ) : (
                sched.all.map((c: CutoffSetting, idx: number) => {
                  const isPaid = sched.paid.some((x: CutoffSetting) => x.id === c.id);
                  return (
                    <div
                      key={c.id}
                      className="flex items-start gap-1 rounded-lg border border-slate-200 dark:border-gray-800 p-3 bg-white dark:bg-gray-900 shadow-sm"
                    >
                      <div className="mt-0.5">
                        {isPaid ? (
                          <CheckCircle2 className="h-4 w-4 text-emerald-600 dark:text-emerald-500" />
                        ) : (
                          <Circle className="h-4 w-4 text-slate-400 dark:text-gray-600" />
                        )}
                      </div>
                      <div className="flex-1">
                        <div className="text-sm font-medium dark:text-gray-200">
                          #{idx + 1} — {cutoffLabel(c)}
                        </div>
                        <div className="text-xs text-slate-500 dark:text-gray-400">
                          {isPaid ? "Paid" : "Pending"}
                        </div>
                      </div>
                    </div>
                  );
                })
              )}
            </div>
          </div>
        )}
      </DialogContent>
    </Dialog>
  );
}

// modules/benefit-settings/providers/benefitApi.ts
import type {
  BenefitSetting,
  UserData,
  BenefitLoan,
  BenefitLogRow,
  CutoffSetting,
  LoanBenefitCode,
  DeductOn,
} from "../types";

const BASE_API = "/api/benefit";

export async function fetchCompanyConfig(): Promise<{ companyName: string }> {
  try {
    const res = await fetch(`${BASE_API}?path=config`);
    return res.ok ? await res.json() : { companyName: "MEN2 MARKETING CORPORATION" };
  } catch {
    return { companyName: "MEN2 MARKETING CORPORATION" };
  }
}


async function apiFetch(path: string, options?: RequestInit) {
  const res = await fetch(`${BASE_API}?path=${encodeURIComponent(path)}`, options);

  // ✅ Directus DELETE often returns 204 (no body)
  if (res.status === 204) return null;

  if (!res.ok) {
    const text = await res.text().catch(() => "");
    throw new Error(`HTTP ${res.status} ${path}${text ? ` - ${text}` : ""}`);
  }

  // ✅ If body is empty, avoid res.json() crash
  const text = await res.text().catch(() => "");
  if (!text) return null;

  try {
    return JSON.parse(text);
  } catch {
    // If server returned non-JSON text, still return something
    return { raw: text };
  }
}
// --------------------
// Shared helpers
// --------------------
export function fullnameFromUser(u: UserData) {
  return `${u.user_fname ?? ""} ${u.user_lname ?? ""}`.trim();
}

export function formatMoney(v: number) {
  if (!Number.isFinite(v)) return "0.00";
  return v.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
}

export function toNum(v: unknown): number {
  if (typeof v === "number") return Number.isFinite(v) ? v : 0;
  if (typeof v === "string") {
    const n = Number(v.replace(/,/g, ""));
    return Number.isFinite(n) ? n : 0;
  }
  return 0;
}

export function cutoffLabel(c: CutoffSetting) {
  const s = new Date(c.start_date);
  const e = new Date(c.end_date);
  const fmt = (d: Date) =>
    d.toLocaleDateString(undefined, { year: "numeric", month: "short", day: "2-digit" });
  return `${fmt(s)} – ${fmt(e)} (${c.cutoff_type})`;
}

export function computeLoanCutoffSchedule(args: {
  loan: Pick<BenefitLoan, "start_cutoff_id" | "terms_installments" | "paid_installments" | "deduct_on">;
  cutoffs: CutoffSetting[];
}) {
  const { loan, cutoffs } = args;
  const ordered = [...cutoffs].sort(
    (a, b) => new Date(a.start_date).getTime() - new Date(b.start_date).getTime()
  );

  const startIdx = ordered.findIndex((c) => c.id === loan.start_cutoff_id);
  if (startIdx < 0) {
    return {
      all: [] as CutoffSetting[],
      paid: [] as CutoffSetting[],
      upcoming: [] as CutoffSetting[],
      nextDue: null as CutoffSetting | null,
      endDue: null as CutoffSetting | null,
    };
  }

  const isEligible = (c: CutoffSetting, deductOn: DeductOn) => {
    if (deductOn === "BOTH") return true;
    return c.cutoff_type === deductOn;
  };

  const eligibleFromStart = ordered
    .slice(startIdx)
    .filter((c) => isEligible(c, loan.deduct_on));

  const all = eligibleFromStart.slice(0, Math.max(0, loan.terms_installments || 0));
  const paid = all.slice(0, Math.max(0, loan.paid_installments || 0));
  const upcoming = all.slice(paid.length);

  return {
    all,
    paid,
    upcoming,
    nextDue: upcoming.length ? upcoming[0] : null,
    endDue: all.length ? all[all.length - 1] : null,
  };
}

export function isLoanDueOnCutoff(args: {
  loan: Pick<BenefitLoan, "start_cutoff_id" | "terms_installments" | "paid_installments" | "deduct_on" | "status">;
  cutoffId: number;
  cutoffs: CutoffSetting[];
}) {
  if (args.loan.status !== "ACTIVE") return false;
  const sched = computeLoanCutoffSchedule({ loan: args.loan as any, cutoffs: args.cutoffs });
  return sched.upcoming.some((c) => c.id === args.cutoffId);
}

// --------------------
// Benefit settings (existing)
// --------------------
export async function fetchBenefitSettings(): Promise<BenefitSetting[]> {
  const json = await apiFetch("/items/benefit_cutoff_settings?limit=200");
  return json.data || [];
}

export async function fetchUsers(): Promise<UserData[]> {
  const json = await apiFetch("/items/user?limit=2000&fields=user_id,user_fname,user_lname");
  return json.data || [];
}

export async function saveBenefitSetting(setting: BenefitSetting) {
  const payload = {
    benefit_code: setting.benefit_code,
    benefit_name: setting.benefit_name,
    cutoff: setting.cutoff,
    is_active: 1,
    effective_from: setting.effective_from,
    effective_to: setting.effective_to,
    updated_by: setting.updated_by ?? null,
  };

  const method = setting.id ? "PATCH" : "POST";
  const path = setting.id
    ? `/items/benefit_cutoff_settings/${setting.id}`
    : "/items/benefit_cutoff_settings";

  return apiFetch(path, {
    method,
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ path, payload }),
  });
}

// --------------------
// Cutoff settings (for loan schedule display)
// --------------------
export async function fetchCutoffSettings(): Promise<CutoffSetting[]> {
  const json = await apiFetch(
    "/items/cutoff_settings?limit=500&sort=start_date&fields=id,cutoff_type,start_date,end_date,period_status"
  );
  return json.data || [];
}

// --------------------
// Benefit Loans (NEW) - SSS & PAGIBIG only
// --------------------
export async function fetchBenefitLoans(): Promise<BenefitLoan[]> {
  const json = await apiFetch("/items/benefit_loans?limit=2000&sort=-created_date");
  const rows = (json.data || []) as any[];
  return rows.map((r) => ({
    ...r,
    principal_amount: toNum(r.principal_amount),
    interest_amount: toNum(r.interest_amount),
    total_payable: toNum(r.total_payable),
    amortization_amount: toNum(r.amortization_amount),
    terms_installments: toNum(r.terms_installments),
    paid_installments: toNum(r.paid_installments),
    remaining_balance: toNum(r.remaining_balance),
  })) as BenefitLoan[];
}

export function buildLoanPayload(input: Partial<BenefitLoan>) {
  // Enforce: PHILHEALTH not allowed for loans at UI/API layer
  const benefit_code = input.benefit_code as LoanBenefitCode;
  if (benefit_code !== "SSS" && benefit_code !== "PAGIBIG") {
    throw new Error("Loans are only allowed for SSS and PAGIBIG.");
  }

  const principal = toNum(input.principal_amount);
  const interest = toNum(input.interest_amount);
  const totalPayable = toNum(input.total_payable) || principal + interest;

  const remaining = toNum(input.remaining_balance) || totalPayable;

  return {
    user_id: input.user_id,
    benefit_code,
    loan_name: input.loan_name ?? null,
    reference_no: input.reference_no ?? null,

    principal_amount: principal,
    interest_amount: interest,
    total_payable: totalPayable,

    amortization_amount: toNum(input.amortization_amount),
    terms_installments: Math.max(1, Math.trunc(toNum(input.terms_installments) || 1)),

    deduct_on: (input.deduct_on ?? "BOTH") as DeductOn,
    start_cutoff_id: input.start_cutoff_id,

    paid_installments: Math.max(0, Math.trunc(toNum(input.paid_installments) || 0)),
    remaining_balance: remaining,
    last_paid_cutoff_id: input.last_paid_cutoff_id ?? null,

    status: input.status ?? "ACTIVE",
    remarks: input.remarks ?? null,

    created_by: input.created_by ?? null,
    updated_by: input.updated_by ?? null,
  };
}

export async function createBenefitLoan(input: Partial<BenefitLoan>) {
  const payload = buildLoanPayload(input);
  return apiFetch("/items/benefit_loans", {
    method: "POST",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ path: "/items/benefit_loans", payload }),
  });
}

export async function updateBenefitLoan(loanId: number, input: Partial<BenefitLoan>) {
  const payload = buildLoanPayload(input);
  return apiFetch(`/items/benefit_loans/${loanId}`, {
    method: "PATCH",
    headers: { "Content-Type": "application/json" },
    body: JSON.stringify({ path: `/items/benefit_loans/${loanId}`, payload }),
  });
}


export async function deleteBenefitLoan(loanId: number) {
  // ✅ No need to send JSON body for DELETE
  return apiFetch(`/items/benefit_loans/${loanId}`, {
    method: "DELETE",
  });
}

// --------------------
// Benefit Logs (REFECTORED) - VIEW ONLY
// --------------------
export async function fetchBenefitLogs(): Promise<BenefitLogRow[]> {
  // 1. Fetch existing payroll_run_employee logs (System/Automated)
  const fields = [
    "id",
    "cutoff_id",
    "user_id.*",
    "benefit_sss",
    "benefit_philhealth",
    "benefit_pagibig",
    "benefit_loan_sss",
    "benefit_loan_pagibig",
    "cutoff_start",
    "cutoff_end",
    "cutoff_type",
    "payroll_run_id.payroll_ref_no",
    "payroll_run_id.payroll_run_id",
    "payroll_run_id.posted_at",
    "created_at"
  ].join(",");

  const pathSystem = `/items/payroll_run_employee?limit=5000&filter[payroll_run_id][status][_eq]=POSTED&sort=-created_at&fields=${fields}`;

  // 2. Fetch new benefit_logs (Manual/Adjustments)
  // We need user details to display name consistently
  const fieldsManual = [
    "*",
    "user_id.*", // Fetch related user data
    "cutoff_start",
    "cutoff_end",
    "cutoff_type",
    "payroll_run_id.cutoff_start",
    "payroll_run_id.cutoff_end",
    "payroll_run_id.cutoff_type"
  ].join(",");
  const pathManual = `/items/benefit_logs?limit=5000&sort=-created_date&fields=${fieldsManual}`;

  const [jsonSystem, jsonManual] = await Promise.all([
    apiFetch(pathSystem),
    apiFetch(pathManual),
  ]);

  const rowsSystem = (jsonSystem?.data || []) as any[];
  const rowsManual = (jsonManual?.data || []) as any[];

  // 3. Merging Logic using Map
  // Key: `${cutoff_id}|${user_id}|${benefit_code}|${log_type}|${loan_id ?? 'null'}|${payroll_run_id}`
  const logMap = new Map<string, BenefitLogRow>();

  // Helper to generate key
  const getKey = (r: BenefitLogRow) => {
    return `${r.cutoff_id}|${r.user_id}|${r.benefit_code}|${r.log_type}|${r.loan_id ?? "null"}|${r.payroll_run_id || "null"}`;
  };

  // 2.a Build a 'has loan detail' lookup from Manual logs to suppress System summaries
  // Key: `${cutoff_id}|${user_id}|${benefit_code}|${payroll_run_id}`
  const hasLoanDetail = new Set<string>();
  for (const r of rowsManual) {
    if (r.log_type === "LOAN" && r.benefit_code) {
      const uId = r.user_id?.user_id || r.user_id;
      const pId = r.payroll_run_id || "null";
      hasLoanDetail.add(`${r.cutoff_id}|${uId}|${r.benefit_code}|${pId}`);
    }
  }

  // --- PROCESS SYSTEM LOGS (payroll_run_employee) ---
  for (const r of rowsSystem) {
    const user = r.user_id || {};
    const pr = r.payroll_run_id || {};
    const uId = r.user_id?.user_id || r.user_id;

    const common = {
      cutoff_id: r.cutoff_id,
      cutoff_start: r.cutoff_start || null,
      cutoff_end: r.cutoff_end || null,
      cutoff_type: r.cutoff_type || null,
      user_id: uId,
      employee_name: fullnameFromUser(user),
      payroll_run_id: r.payroll_run_id?.payroll_run_id || r.payroll_run_id,
      payroll_ref_no: pr.payroll_ref_no || "N/A",
      posted_at: pr.posted_at || null,
      created_date: r.created_at,
      note: null,
      source_amount: 0,
    };

    const pushToMap = (item: BenefitLogRow) => {
      const key = getKey(item);
      logMap.set(key, item);
    };

    // Contributions
    if (toNum(r.benefit_sss) > 0) {
      pushToMap({
        ...common,
        benefit_log_id: `CONTRI-SSS-${r.id}`,
        benefit_code: "SSS",
        benefit_name: "SSS",
        log_type: "CONTRIBUTION",
        loan_id: null,
        deducted_amount: toNum(r.benefit_sss),
      });
    }
    if (toNum(r.benefit_philhealth) > 0) {
      pushToMap({
        ...common,
        benefit_log_id: `CONTRI-PH-${r.id}`,
        benefit_code: "PHILHEALTH",
        benefit_name: "PhilHealth",
        log_type: "CONTRIBUTION",
        loan_id: null,
        deducted_amount: toNum(r.benefit_philhealth),
      });
    }

    if (toNum(r.benefit_pagibig) > 0) {
      pushToMap({
        ...common,
        benefit_log_id: `CONTRI-HDMF-${r.id}`,
        benefit_code: "PAGIBIG",
        benefit_name: "Pag-IBIG",
        log_type: "CONTRIBUTION",
        loan_id: null,
        deducted_amount: toNum(r.benefit_pagibig),
      });
    }

    // Loans (Note: System loans have loan_id = null usually.
    // If we have detailed loan logs manually (loan_id != null), suppress these summary rows.)

    // Check SSS Loan Detail
    const hasSssLoan = hasLoanDetail.has(`${r.cutoff_id}|${uId}|SSS|${r.payroll_run_id?.payroll_run_id || r.payroll_run_id || "null"}`);
    if (!hasSssLoan && toNum(r.benefit_loan_sss) > 0) {
      pushToMap({
        ...common,
        benefit_log_id: `LOAN-SSS-${r.id}`,
        benefit_code: "SSS",
        benefit_name: "SSS",
        log_type: "LOAN",
        loan_id: null,
        deducted_amount: toNum(r.benefit_loan_sss),
      });
    }

    // Check Pagibig Loan Detail
    const hasPagibigLoan = hasLoanDetail.has(`${r.cutoff_id}|${uId}|PAGIBIG|${r.payroll_run_id?.payroll_run_id || r.payroll_run_id || "null"}`);
    if (!hasPagibigLoan && toNum(r.benefit_loan_pagibig) > 0) {
      pushToMap({
        ...common,
        benefit_log_id: `LOAN-HDMF-${r.id}`,
        benefit_code: "PAGIBIG",
        benefit_name: "Pag-IBIG",
        log_type: "LOAN",
        loan_id: null,
        deducted_amount: toNum(r.benefit_loan_pagibig),
      });
    }
  }

  // --- PROCESS MANUAL LOGS (benefit_logs) ---
  for (const r of rowsManual) {
    const user = r.user_id || {};

    // Determine Payroll Ref No display
    // Priority: payroll_detail_id > payroll_run_id
    let refNo = "Manual";
    if (r.payroll_detail_id) {
      refNo = r.payroll_detail_id;
    } else if (r.payroll_run_id && Number(r.payroll_run_id) !== 0) {
      refNo = String(r.payroll_run_id);
    }

    const manualRow: BenefitLogRow = {
      benefit_log_id: r.benefit_log_id,
      benefit_code: r.benefit_code,
      benefit_name: r.benefit_code === "PAGIBIG" ? "Pag-IBIG" : r.benefit_code === "PHILHEALTH" ? "PhilHealth" : r.benefit_code,
      cutoff_id: r.cutoff_id,
      cutoff_start: r.cutoff_start || (typeof r.payroll_run_id === "object" && r.payroll_run_id !== null ? r.payroll_run_id?.cutoff_start : null),
      cutoff_end: r.cutoff_end || (typeof r.payroll_run_id === "object" && r.payroll_run_id !== null ? r.payroll_run_id?.cutoff_end : null),
      cutoff_type: r.cutoff_type || (typeof r.payroll_run_id === "object" && r.payroll_run_id !== null ? r.payroll_run_id?.cutoff_type : null),
      user_id: r.user_id?.user_id || r.user_id,
      employee_name: fullnameFromUser(user),

      log_type: r.log_type,
      loan_id: r.loan_id,

      source_amount: r.source_amount ? toNum(r.source_amount) : 0,
      deducted_amount: toNum(r.deducted_amount),

      payroll_run_id: typeof r.payroll_run_id === "object" ? r.payroll_run_id?.id : r.payroll_run_id,
      payroll_ref_no: refNo,

      note: r.note,
      created_date: r.created_date,
      posted_at: r.created_date,

      account_no: null // Will be populated in final pass
    };

    const key = getKey(manualRow);
    const existing = logMap.get(key);

    if (existing) {
      // MERGE LOGIC (User Request: "treat same data as one not add/total them")
      // The manual log takes precedence over the system log for the same key.

      // Overwrite amounts
      existing.deducted_amount = manualRow.deducted_amount;
      existing.source_amount = manualRow.source_amount;

      // Overwrite note if manual log has one
      if (manualRow.note) {
        existing.note = manualRow.note;
      }

      // If manual log has a specific payroll ref (from payroll_detail_id), use it
      if (manualRow.payroll_ref_no !== "Manual") {
        existing.payroll_ref_no = manualRow.payroll_ref_no;
      }

      // Preserve cutoff date ranges if manual log has them
      if (manualRow.cutoff_start && manualRow.cutoff_end) {
        existing.cutoff_start = manualRow.cutoff_start;
        existing.cutoff_end = manualRow.cutoff_end;
        existing.cutoff_type = manualRow.cutoff_type;
      }

      // We keep the 'existing' object in the map, effectively updating it in-place.
    } else {
      // INSERT NEW
      logMap.set(key, manualRow);
    }
  }

  // Convert Map to Array
  const logs = Array.from(logMap.values());

  // Final pass to set correct account_no based on benefit_code
  // We need to look up ANY row from system or manual that has the user details
  const userMap = new Map<number, any>();

  // Populate user map from both sources
  rowsSystem.forEach(r => {
    const u = r.user_id;
    if (u && u.user_id) userMap.set(u.user_id, u);
  });
  rowsManual.forEach(r => {
    const u = r.user_id;
    if (u && u.user_id) userMap.set(u.user_id, u);
  });

  for (const log of logs) {
    const u = userMap.get(log.user_id) || {};

    if (log.benefit_code === "SSS") {
      log.account_no = u.user_sss || null;
    } else if (log.benefit_code === "PHILHEALTH") {
      log.account_no = u.user_philhealth || null;
    } else if (log.benefit_code === "PAGIBIG") {
      log.account_no = u.user_pagibig || null;
    }
  }

  // Sort by date descending (posted_at or created_date)
  logs.sort((a, b) => {
    const da = new Date(a.created_date || 0).getTime();
    const db = new Date(b.created_date || 0).getTime();
    return db - da; // Descending
  });

  return logs;
}

