"use client";

import type { BenefitLogRow, CutoffSetting, UserData, BenefitCode } from "../types";
import { cutoffLabel, formatMoney } from "../providers/benefitApi";

export type BenefitLogsPaperSize = "LETTER" | "A4" | "LEGAL";

function userName(users: UserData[], userId: number) {
  const u = users.find((x) => x.user_id === userId);
  return u ? `${u.user_fname} ${u.user_lname}`.trim() : `User #${userId}`;
}

function formatPosted(r: BenefitLogRow) {
  // Prefer payroll run reference if available; otherwise fallback to created_date-ish fields if present.
  const anyR = r as any;
  if (r.payroll_run_id) return `PR#${r.payroll_run_id}`;
  const raw = anyR.posted_at ?? anyR.created_date ?? anyR.updated_date ?? null;
  if (!raw) return "—";
  const d = new Date(raw);
  if (Number.isNaN(d.getTime())) return String(raw);
  return d.toLocaleString();
}

function paperToJsPdfFormat(paper: BenefitLogsPaperSize): "letter" | "a4" | "legal" {
  if (paper === "A4") return "a4";
  if (paper === "LEGAL") return "legal";
  return "letter";
}

export async function exportBenefitLogsPdf(args: {
  paper: BenefitLogsPaperSize;
  companyName?: string;
  title?: string;

  users: UserData[];
  cutoffRange: string; // "ALL" or start_end
  benefit: BenefitCode | "ALL";
  type: "ALL" | "CONTRIBUTION" | "LOAN";
  search: string;

  rows: BenefitLogRow[]; // already filtered rows
}) {
  const {
    paper,
    companyName = "",
    title = "Benefit Logs (Deduction Report)",
    users,
    cutoffRange,
    benefit,
    type,
    search,
    rows,
  } = args;

  // NOTE: requires deps in your app:
  // npm i jspdf jspdf-autotable
  const [{ jsPDF }, autoTableMod] = await Promise.all([import("jspdf"), import("jspdf-autotable")]);
  const autoTable = (autoTableMod as any).default ?? (autoTableMod as any);

  const format = paperToJsPdfFormat(paper);

  // Portrait, modern margins in points
  const doc = new jsPDF({
    orientation: "portrait",
    unit: "pt",
    format,
  });

  const pageW = doc.internal.pageSize.getWidth();
  const pageH = doc.internal.pageSize.getHeight();

  const marginX = 40;
  const headerH = 72;

  // --- Branding Colors (Premium System) ---
  const DARK_BLUE = [11, 19, 43] as [number, number, number];
  const CYAN = [0, 180, 216] as [number, number, number];
  const LIGHT_BLUE = [144, 224, 239] as [number, number, number];

  const setFill = (rgb: number[]) => doc.setFillColor(rgb[0], rgb[1], rgb[2]);
  const setText = (rgb: number[]) => doc.setTextColor(rgb[0], rgb[1], rgb[2]);

  // --- Dynamic Title based on selection ---
  const getBenefitLabel = (code: string) => {
    if (code === "SSS") return "SSS";
    if (code === "PHILHEALTH") return "PhilHealth";
    if (code === "PAGIBIG") return "Pag-IBIG";
    return code.charAt(0).toUpperCase() + code.slice(1).toLowerCase();
  };

  const actualBenefit =
    benefit === "ALL"
      ? (() => {
        const unique = Array.from(new Set(rows.map((r) => r.benefit_code)));
        return unique.length === 1 ? unique[0] : "Benefit";
      })()
      : benefit;

  const typeLabel =
    type === "ALL" ? "Logs" : type === "CONTRIBUTION" ? "Contributions" : "Loans";

  const displayTitle = `${actualBenefit === "Benefit" ? "Benefit" : getBenefitLabel(actualBenefit)} ${typeLabel}`;
  const footerH = 50;

  const renderHeader = (isFirstPage: boolean) => {
    // --- HEADER RIBBON (Top Left) ---
    setFill(DARK_BLUE);
    doc.triangle(0, 0, 180, 0, 0, 80, "F");
    setFill(CYAN);
    doc.triangle(0, 15, 120, 15, 0, 65, "F");
    setFill(LIGHT_BLUE);
    doc.triangle(0, 30, 80, 30, 0, 55, "F");
    setFill(DARK_BLUE);
    doc.rect(180, 0, pageW - 180, 15, "F");

    // --- COMPANY LOGO & NAME ---
    let headerY = 50;
    setText(DARK_BLUE);
    doc.setFont("helvetica", "bold");

    const nameStr = (companyName || "").toUpperCase().trim();
    const lastSpaceIdx = nameStr.lastIndexOf(" ");

    if (lastSpaceIdx === -1) {
      doc.setFontSize(22);
      doc.text(nameStr, pageW - marginX, headerY, { align: "right" });
    } else {
      const p1 = nameStr.substring(0, lastSpaceIdx);
      const p2 = nameStr.substring(lastSpaceIdx + 1);

      doc.setFontSize(22);
      doc.text(p1, pageW - marginX, headerY, { align: "right" });

      headerY += 18;
      setText(CYAN);
      doc.setFontSize(10);
      doc.text(p2, pageW - marginX, headerY, { align: "right" });
    }

    // Divider Line
    headerY += 15;
    doc.setDrawColor(DARK_BLUE[0], DARK_BLUE[1], DARK_BLUE[2]);
    doc.setLineWidth(1.5);
    doc.line(pageW - 250, headerY, pageW - marginX, headerY);

    // --- REPORT TITLE ---
    headerY += 60;
    setText(DARK_BLUE);
    doc.setFontSize(16);
    doc.text(displayTitle.toUpperCase(), marginX, headerY);

    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.text(`DATE: ${new Date().toLocaleDateString('en-US', { day: 'numeric', month: 'long', year: 'numeric' }).toUpperCase()}`, pageW - marginX, headerY, { align: "right" });

    // --- Summary Statistics (Only on First Page) ---
    if (isFirstPage) {
      const periodLabelText =
        cutoffRange === "ALL" || cutoffRange === "UNKNOWN"
          ? "All Records"
          : (() => {
            const [start, end] = cutoffRange.split("_");
            const format = (d: string) => new Date(d).toLocaleDateString(undefined, { year: "numeric", month: "short", day: "2-digit" });
            return `Cutoff: ${format(start)} - ${format(end)}`;
          })();

      const uniqueEmployees = new Set(rows.map((r) => r.user_id)).size;
      const grandTotal = rows.reduce((sum, r) => sum + (r.deducted_amount || 0), 0);

      const statsY = headerY + 40;
      doc.setTextColor(11, 19, 43); // Dark Blue
      doc.setFontSize(9);
      doc.setFont("helvetica", "bold");

      const headerStats = [
        `PERIOD: ${periodLabelText.toUpperCase()}`,
        `TOTAL EMPLOYEES: ${uniqueEmployees}`,
        `GRAND TOTAL: PHP ${formatMoney(grandTotal)}`
      ].join("   |   ");

      doc.text(headerStats, pageW / 2, statsY, { align: "center" });

      // Divider line
      doc.setDrawColor(226, 232, 240); // Border color
      doc.setLineWidth(0.5);
      doc.line(marginX, statsY + 10, pageW - marginX, statsY + 10);
      return statsY + 12;
    }
    return headerY + 20;
  };

  const renderFooter = (pageNumber: number, totalPages: number) => {
    const footerH = 50;
    const footerY = pageH - footerH;

    // Background Bar
    setFill(DARK_BLUE);
    doc.rect(0, footerY, pageW, footerH, "F");

    // Footer Ribbon (Bottom Right)
    setFill(CYAN);
    doc.triangle(pageW, pageH, pageW - 120, pageH, pageW, pageH - 40, "F");
    setFill(LIGHT_BLUE);
    doc.triangle(pageW, pageH, pageW - 80, pageH, pageW, pageH - 25, "F");

    // Contact Info
    setText([255, 255, 255]);
    doc.setFontSize(10);
    doc.setFont("helvetica", "bold");
    doc.text((companyName || "").toUpperCase(), marginX, footerY + 30);

    doc.setFontSize(8);
    doc.setFont("helvetica", "normal");
    doc.text(`Page ${pageNumber} of ${totalPages}`, pageW - marginX - 100, footerY + 30, { align: "right" });
  };

  let lastY = renderHeader(true);

  // Optional Breakdown ONLY for ALL
  const uniqueBenefitsTotal = new Set(rows.map((r) => r.benefit_code)).size;
  if (benefit === "ALL" && uniqueBenefitsTotal > 1) {
    const totals = rows.reduce(
      (acc, r) => {
        const b = r.benefit_code as BenefitCode;
        acc[b] = (acc[b] || 0) + (r.deducted_amount || 0);
        return acc;
      },
      { SSS: 0, PAGIBIG: 0, PHILHEALTH: 0 } as Record<string, number>
    );

    doc.setFontSize(8);
    doc.setTextColor(148, 163, 184);
    doc.text(
      `Breakdown: SSS ${formatMoney(totals.SSS)}  |  PhilHealth ${formatMoney(totals.PHILHEALTH)}  |  Pag-IBIG ${formatMoney(totals.PAGIBIG)}`,
      pageW / 2,
      lastY + 12,
      { align: "center" }
    );
    lastY += 20;
  }

  // --- Table Rendering (Grouped by Benefit & Type) ---
  const benefitOrder: BenefitCode[] =
    benefit === "ALL" ? ["SSS", "PHILHEALTH", "PAGIBIG"] : [benefit];
  const typeOrder: ("CONTRIBUTION" | "LOAN")[] = ["CONTRIBUTION", "LOAN"];

  for (const bCode of benefitOrder) {
    for (const lType of typeOrder) {
      const groupRows = rows.filter(
        (r) => r.benefit_code === bCode && r.log_type === lType
      );

      if (groupRows.length === 0) continue;

      // Group Header
      const head = [["Employee", "Account #", "Deducted", "Posted Date"]];
      const body = groupRows.map((r) => {
        const postedDate = r.posted_at
          ? new Date(r.posted_at).toLocaleDateString(undefined, {
            year: "numeric",
            month: "short",
            day: "2-digit",
          })
          : "—";

        const uId = typeof r.user_id === "object" ? (r.user_id as any)?.user_id : r.user_id;

        return [
          r.employee_name || userName(users, uId),
          r.account_no || "—",
          formatMoney(r.deducted_amount || 0),
          postedDate,
        ];
      });

      autoTable(doc, {
        startY: lastY + 10,
        head,
        body,
        theme: "striped",
        margin: { left: marginX, right: marginX, bottom: footerH + 10 },
        styles: {
          font: "helvetica",
          fontSize: 9,
          cellPadding: 8,
          textColor: [11, 19, 43], // Dark Blue
          lineColor: [230, 233, 237],
          lineWidth: 0.1,
        },
        headStyles: {
          fillColor: [11, 19, 43], // Dark Blue
          textColor: [255, 255, 255],
          fontStyle: "bold",
          halign: "left",
        },
        alternateRowStyles: {
          fillColor: [245, 247, 250],
        },
        columnStyles: {
          2: { halign: "right", fontStyle: "bold" }, // Deducted
          1: { cellWidth: 100 },  // Account #
          3: { cellWidth: 80 },   // Posted Date
        },
      });

      lastY = (doc as any).lastAutoTable.finalY + 30;

      // Avoid orphaned headers at bottom of page
      if (lastY > pageH - 120) {
        doc.addPage();
        lastY = renderHeader(false);
      }
    }
  }

  // Final Footer Rendering on all pages
  const pageCount = doc.getNumberOfPages();
  for (let i = 1; i <= pageCount; i++) {
    doc.setPage(i);
    renderFooter(i, pageCount);
  }

  return doc;
}

"use client";

import {
  Pencil,
  Trash2,
  Calendar as CalendarIcon,
  Plus,
  Search,
  Briefcase,
  Star,
  ChevronLeft,
  ChevronRight,
  ChevronsLeft,
  ChevronsRight,
  User,
} from "lucide-react";
import type React from "react";
import { useEffect, useMemo, useState } from "react";
import { toast } from "sonner";
import DashboardLayout from "@/components/layout/DashboardLayout";
import { Separator } from "@/components/ui/separator";

import type { Holiday, CalendarUser as UserType } from "./types";
import { CalendarManagementSkeleton } from "./components/CalendarManagementSkeleton";
import * as calendarApi from "./providers/calendarApi";
import { getSessionUserId } from "../cutoff-settings/providers/cutoffSettingsApi";

export function CalendarManagementModule() {
  // ---------------------- State & Logic ----------------------
  const [holidays, setHolidays] = useState<Holiday[]>([]);
  const [users, setUsers] = useState<UserType[]>([]);
  const [loading, setLoading] = useState(true);

  // Calendar Navigation State
  const [currentMonth, setCurrentMonth] = useState(new Date());
  const [selectedDate, setSelectedDate] = useState<Date | undefined>(undefined);

  // Animation State
  const [flashingDate, setFlashingDate] = useState<string | null>(null);

  // Modal States
  const [modalOpen, setModalOpen] = useState(false);

  // Form States
  const [holidayDate, setHolidayDate] = useState("");
  const [lastWorkingDay, setLastWorkingDay] = useState("");
  const [description, setDescription] = useState("");
  const [holidayType, setHolidayType] = useState("regular");
  const [isRecurring, setIsRecurring] = useState(true);
  const [isPaid, setIsPaid] = useState(true);
  const [editingHolidayId, setEditingHolidayId] = useState<number | null>(null);

  // Search & Pagination
  const [searchTerm, setSearchTerm] = useState("");
  const [currentPage, setCurrentPage] = useState(1);
  const ITEMS_PER_PAGE = 5;

  // ---------------------- API Data ----------------------
  const loadData = async () => {
    setLoading(true);
    try {
      const [hData, uData] = await Promise.all([
        calendarApi.fetchHolidays(),
        calendarApi.fetchUsers(),
      ]);
      setHolidays(hData);
      setUsers(uData);
    } catch (err: any) {
      console.error("Failed to load calendar data:", err);
      toast.error(err.message || "Failed to load data");
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    loadData();
  }, []);

  useEffect(() => {
    setCurrentPage(1);
  }, [searchTerm]);

  // ---------------------- Derived Data ----------------------

  const filteredHolidays = useMemo(() => {
    return holidays.filter(
      (h) =>
        h.description.toLowerCase().includes(searchTerm.toLowerCase()) ||
        h.holiday_date.includes(searchTerm) ||
        h.holiday_type.toLowerCase().includes(searchTerm.toLowerCase())
    );
  }, [holidays, searchTerm]);

  const totalPages = Math.ceil(filteredHolidays.length / ITEMS_PER_PAGE);
  const paginatedHolidays = useMemo(() => {
    const startIndex = (currentPage - 1) * ITEMS_PER_PAGE;
    return filteredHolidays.slice(startIndex, startIndex + ITEMS_PER_PAGE);
  }, [filteredHolidays, currentPage]);

  const getUserName = (id: number | undefined | null) => {
    if (!id && id !== 0) return "Unknown";
    const u = users.find((x) => x.user_id === id);
    return u ? `${u.user_fname} ${u.user_lname}` : `User ${id}`;
  };

  // ---------------------- Handlers ----------------------
  const resetForm = () => {
    setHolidayDate(selectedDate ? `${selectedDate.getFullYear()}-${String(selectedDate.getMonth() + 1).padStart(2, "0")}-${String(selectedDate.getDate()).padStart(2, "0")}` : "");
    setLastWorkingDay("");
    setDescription("");
    setHolidayType("regular");
    setIsRecurring(true);
    setIsPaid(true);
    setEditingHolidayId(null);
  };

  const handleEdit = (e: React.MouseEvent, h: Holiday) => {
    e.stopPropagation(); // Prevent triggering the row click
    setHolidayDate(h.holiday_date);
    setLastWorkingDay(h.last_working_day || "");
    setDescription(h.description);
    setHolidayType(h.holiday_type);
    setIsRecurring(h.is_recurring === 1 || h.is_recurring === true);
    setIsPaid(h.is_paid === 1 || h.is_paid === true);
    setEditingHolidayId(h.id);
    setModalOpen(true);
  };

  // Resolve the cutoff_setting_id for a given date by querying the cutoff-settings API.
  const getCutoffSettingId = async (dateStr: string): Promise<number | null> => {
    try {
      const d = new Date(dateStr);
      const month = String(d.getMonth() + 1);
      const year = String(d.getFullYear());
      const day = d.getDate();

      const res = await fetch(`/api/cutoff-settings?month=${month}&year=${year}`, {
        cache: "no-store",
      });
      if (!res.ok) return null;

      const json = await res.json();
      const settings: any[] = json?.data ?? [];
      if (!settings.length) return null;

      // Prefer the cutoff period whose date range contains the holiday date.
      const matched = settings.find((s) => {
        if (!s.start_date || !s.end_date) return false;
        const start = new Date(s.start_date).getDate();
        const end = new Date(s.end_date).getDate();
        return day >= start && day <= end;
      });

      return (matched ?? settings[0])?.id ?? null;
    } catch {
      return null;
    }
  };

  const handleSaveHoliday = async () => {
    if (!holidayDate || !description) {
      alert("Please fill all required fields");
      return;
    }

    const cutoffSettingId = await getCutoffSettingId(holidayDate);

    const payload: Partial<Holiday> = {
      holiday_date: holidayDate,
      last_working_day: lastWorkingDay || null,
      description,
      holiday_type: holidayType,
      is_recurring: isRecurring ? 1 : 0,
      is_paid: isPaid ? 1 : 0,
      cutoff_setting_id: cutoffSettingId,
      updated_by: Number(getSessionUserId()),
    };

    if (!editingHolidayId) {
      payload.created_by = Number(getSessionUserId());
    }

    try {
      if (editingHolidayId) {
        await calendarApi.updateHoliday(editingHolidayId, payload);
      } else {
        await calendarApi.createHoliday(payload);
      }
      setModalOpen(false);
      resetForm();
      await loadData(); // Reload from DB
      toast.success(editingHolidayId ? "Holiday updated" : "Holiday created");
    } catch (err: any) {
      console.error("Failed to save holiday:", err);
      toast.error(err.message || "Failed to save holiday");
    }
  };

  const handleDeleteHoliday = async (e: React.MouseEvent, id: number) => {
    e.stopPropagation(); // Prevent triggering the row click
    if (!confirm("Delete this holiday?")) return;
    try {
      await calendarApi.deleteHoliday(id);
      await loadData();
      toast.success("Holiday deleted");
    } catch (err: any) {
      console.error("Failed to delete holiday:", err);
      toast.error(err.message || "Failed to delete");
    }
  };

  // --- Handle Event Click from Table ---
  const handleEventClick = (dateStr: string) => {
    const targetDate = new Date(dateStr);

    // 1. Select the date
    setSelectedDate(targetDate);

    // 2. Switch calendar to that month if not already visible
    if (
      targetDate.getMonth() !== currentMonth.getMonth() ||
      targetDate.getFullYear() !== currentMonth.getFullYear()
    ) {
      setCurrentMonth(new Date(targetDate.getFullYear(), targetDate.getMonth(), 1));
    }

    // 3. Trigger Flash Animation
    setFlashingDate(dateStr);

    // 4. Remove Flash after animation completes (1s)
    setTimeout(() => {
      setFlashingDate(null);
    }, 1000);
  };

  const stats = useMemo(() => {
    const total = holidays.length;
    const special = holidays.filter((h) => h.holiday_type === "special").length;
    const paid = holidays.filter((h) => h.is_paid).length;
    return { total, special, paid };
  }, [holidays]);

  // ---------------------- Calendar Component ----------------------
  const SimpleCalendar = () => {
    const { daysInMonth, startingDayOfWeek, year, month } = useMemo(() => {
      const year = currentMonth.getFullYear();
      const month = currentMonth.getMonth();
      const firstDay = new Date(year, month, 1);
      const lastDay = new Date(year, month + 1, 0);
      return {
        daysInMonth: lastDay.getDate(),
        startingDayOfWeek: firstDay.getDay(),
        year,
        month,
      };
    }, [currentMonth]);

    const days = [];
    for (let i = 0; i < startingDayOfWeek; i++) {
      days.push(<div key={`empty-${i}`} className="h-10 w-10"></div>);
    }

    for (let day = 1; day <= daysInMonth; day++) {
      const currentDayDate = new Date(year, month, day);
      const dateStringIso = `${year}-${String(month + 1).padStart(2, "0")}-${String(day).padStart(2, "0")}`;

      const isToday = new Date().toDateString() === currentDayDate.toDateString();
      const isSelected = selectedDate?.toDateString() === currentDayDate.toDateString();
      const isFlashing = flashingDate === dateStringIso;

      const dayEvents = holidays.filter((h) => h.holiday_date === dateStringIso);
      const hasEvent = dayEvents.length > 0;

      const isSpecial = dayEvents.some((h) => h.holiday_type === "special");
      const dotColor = isSpecial ? "bg-amber-500" : "bg-blue-500";

      days.push(
        <button
          key={day}
          onClick={() => setSelectedDate(currentDayDate)}
          className={`
            relative h-10 w-10 p-0 rounded-full flex items-center justify-center transition-all duration-300 text-sm group
            ${
              isSelected
                ? "bg-blue-600 text-white shadow-md scale-105"
                : "hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-700 dark:text-gray-300"
            }
            ${isToday && !isSelected ? "text-blue-600 font-bold border border-blue-200 dark:border-blue-800" : ""}
            ${isFlashing ? "ring-4 ring-blue-300 dark:ring-blue-900 scale-125 z-10" : ""} 
          `}
        >
          <span className="z-10">{day}</span>

          {hasEvent && !isSelected && (
            <span className={`absolute bottom-1.5 h-1 w-1 rounded-full ${dotColor}`}></span>
          )}
          {hasEvent && isSelected && (
            <span className="absolute bottom-1.5 h-1 w-1 rounded-full bg-white/70"></span>
          )}
        </button>
      );
    }

    const monthNames = [
      "January",
      "February",
      "March",
      "April",
      "May",
      "June",
      "July",
      "August",
      "September",
      "October",
      "November",
      "December",
    ];

    return (
      <div className="w-full h-full flex flex-col">
        {/* Calendar Header */}
        <div className="flex items-center justify-between mb-6 px-1">
          <span className="text-lg font-bold text-gray-900 dark:text-gray-100">
            {monthNames[month]} <span className="text-gray-500 dark:text-gray-400 font-normal">{year}</span>
          </span>
          <div className="flex gap-1">
            <button
              onClick={() =>
                setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() - 1))
              }
              className="h-8 w-8 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 text-gray-600 dark:text-gray-400 hover:text-blue-600 dark:hover:text-blue-400 hover:border-blue-200 dark:hover:border-blue-800 rounded-md flex items-center justify-center transition-all shadow-sm"
            >
              <ChevronLeft className="h-4 w-4" />
            </button>
            <button
              onClick={() =>
                setCurrentMonth(new Date(currentMonth.getFullYear(), currentMonth.getMonth() + 1))
              }
              className="h-8 w-8 bg-white dark:bg-gray-800 border border-gray-200 dark:border-gray-700 text-gray-600 dark:text-gray-400 hover:text-blue-600 dark:hover:text-blue-400 hover:border-blue-200 dark:hover:border-blue-800 rounded-md flex items-center justify-center transition-all shadow-sm"
            >
              <ChevronRight className="h-4 w-4" />
            </button>
          </div>
        </div>

        {/* Days Grid */}
        <div className="w-full">
          <div className="grid grid-cols-7 gap-1 mb-2">
            {["Sun", "Mon", "Tue", "Wed", "Thu", "Fri", "Sat"].map((day) => (
              <div
                key={day}
                className="h-8 text-center text-gray-400 dark:text-gray-500 text-[11px] font-semibold uppercase tracking-wider flex items-center justify-center"
              >
                {day}
              </div>
            ))}
          </div>
          <div className="grid grid-cols-7 gap-y-2 gap-x-1 place-items-center">{days}</div>
        </div>
      </div>
    );
  };

  if (loading) {
    return (
      <DashboardLayout>
        <CalendarManagementSkeleton />
      </DashboardLayout>
    );
  }

  return (
    <DashboardLayout>
      <div className="flex flex-col gap-6 h-full p-6 bg-gray-50 dark:bg-gray-950 font-sans">
        {/* HEADER */}
        <div className="flex items-center justify-between shrink-0">
          <div>
            <h1 className="text-2xl font-bold tracking-tight text-gray-900 dark:text-gray-100">
              Calendar Management
            </h1>
            <p className="text-sm text-gray-600 dark:text-gray-400">
              Manage company holidays, non-working days, and events.
            </p>
          </div>
          <button
            onClick={() => {
              resetForm();
              setModalOpen(true);
            }}
            className="px-4 py-2 bg-blue-600 text-white rounded-md hover:bg-blue-700 flex items-center gap-2 shadow-sm transition-colors"
          >
            <Plus className="h-4 w-4" /> Add Event
          </button>
        </div>
        <Separator />

        {/* --- TOP ROW --- */}
        <div className="grid grid-cols-1 xl:grid-cols-12 gap-6 h-[500px]">
          {/* 1. CALENDAR VIEW */}
          <div className="xl:col-span-3 flex flex-col h-full overflow-hidden">
            <div className="h-full border dark:border-gray-700 rounded-lg shadow-sm flex flex-col overflow-hidden bg-white dark:bg-gray-900">
              <div className="py-3 px-5 border-b dark:border-gray-700 bg-white dark:bg-gray-900 flex items-center justify-between">
                <h3 className="text-sm font-semibold flex items-center gap-2 text-gray-800 dark:text-gray-200">
                  <CalendarIcon className="w-4 h-4 text-blue-600 dark:text-blue-400" />
                  Pick a Date
                </h3>
              </div>
              <div className="flex-1 flex flex-col p-6 overflow-y-auto">
                <SimpleCalendar />

                {/* Selected Date Context Info (UPDATED WITH DETAILS) */}
                {selectedDate && (
                  <div className="mt-auto pt-6 animate-in fade-in slide-in-from-bottom-2">
                    <div className="w-full p-4 bg-gray-50 dark:bg-gray-800 border border-gray-100 dark:border-gray-700 rounded-xl shadow-sm">
                      <div className="flex items-center gap-2 mb-3">
                        <div className="h-2 w-2 rounded-full bg-blue-500"></div>
                        <p className="text-xs font-bold text-gray-500 dark:text-gray-400 uppercase tracking-wider">
                          Selected Date
                        </p>
                      </div>
                      <p className="text-base font-bold text-gray-900 dark:text-gray-100 mb-3">
                        {selectedDate.toLocaleDateString("en-US", {
                          weekday: "long",
                          month: "long",
                          day: "numeric",
                        })}
                      </p>

                      {(() => {
                        // Find events for the selected date
                        const dayEvents = holidays.filter(
                          (h) =>
                            new Date(h.holiday_date).toDateString() ===
                            selectedDate.toDateString()
                        );

                        if (dayEvents.length > 0) {
                          return (
                            <div className="space-y-3">
                              {dayEvents.map((event) => (
                                <div
                                  key={event.id}
                                  className="bg-white dark:bg-gray-900 p-3 rounded-lg border border-gray-100 dark:border-gray-700 shadow-sm transition-all hover:shadow-md"
                                >
                                  <div className="flex items-start justify-between gap-2 mb-1">
                                    <span className="text-sm font-semibold text-gray-800 dark:text-gray-200 leading-tight">
                                      {event.description}
                                    </span>
                                    <span
                                      className={`text-[10px] px-1.5 py-0.5 rounded font-medium uppercase tracking-wide shrink-0 ${
                                        event.holiday_type === "special"
                                          ? "bg-amber-100 dark:bg-amber-900/40 text-amber-700 dark:text-amber-400"
                                          : event.holiday_type === "company"
                                          ? "bg-blue-100 dark:bg-blue-900/40 text-blue-700 dark:text-blue-400"
                                          : "bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-300"
                                      }`}
                                    >
                                      {event.holiday_type}
                                    </span>
                                  </div>
                                  <div className="flex flex-wrap gap-2 mt-2">
                                    {event.is_recurring && (
                                      <span className="inline-flex items-center gap-1 text-[10px] text-gray-500 dark:text-gray-400 bg-gray-50 dark:bg-gray-800 px-1.5 py-0.5 rounded border border-gray-100 dark:border-gray-700">
                                        <div className="w-1 h-1 rounded-full bg-purple-500"></div>{" "}
                                        Recurring
                                      </span>
                                    )}
                                    {event.is_paid ? (
                                      <span className="inline-flex items-center gap-1 text-[10px] text-emerald-600 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20 px-1.5 py-0.5 rounded border border-emerald-100 dark:border-emerald-900/40">
                                        <div className="w-1 h-1 rounded-full bg-emerald-500"></div>{" "}
                                        Paid
                                      </span>
                                    ) : (
                                      <span className="inline-flex items-center gap-1 text-[10px] text-red-600 dark:text-red-400 bg-red-50 dark:bg-red-900/20 px-1.5 py-0.5 rounded border border-red-100 dark:border-red-900/40">
                                        <div className="w-1 h-1 rounded-full bg-red-500"></div>{" "}
                                        Unpaid
                                      </span>
                                    )}
                                  </div>
                                  <div className="mt-2 text-[10px] text-gray-400 dark:text-gray-500 flex items-center gap-1.5 pt-2 border-t border-gray-50 dark:border-gray-800">
                                    <User className="w-3 h-3" />
                                    <span>Added by {getUserName(event.created_by)}</span>
                                  </div>
                                </div>
                              ))}
                            </div>
                          );
                        } else {
                          return (
                            <p className="text-xs text-gray-500 italic">
                              No events scheduled for this day.
                            </p>
                          );
                        }
                      })()}
                    </div>
                  </div>
                )}
              </div>
            </div>
          </div>

          {/* 2. EVENTS TABLE */}
          <div className="xl:col-span-9 flex flex-col h-full overflow-hidden">
            <div className="flex-1 flex flex-col border dark:border-gray-700 rounded-lg shadow-sm overflow-hidden bg-white dark:bg-gray-900">
              {/* Top Bar */}
              <div className="px-5 py-3 border-b dark:border-gray-700 flex flex-col sm:flex-row sm:items-center justify-between gap-4 bg-white dark:bg-gray-900 text-gray-900 dark:text-gray-100">
                <div>
                  <h2 className="text-sm font-semibold">Events List</h2>
                  <p className="text-xs text-gray-600 dark:text-gray-400 mt-0.5">
                    Overview of scheduled events for {new Date().getFullYear()}.
                  </p>
                </div>
                <div className="relative w-full sm:w-64">
                  <Search className="absolute left-2.5 top-1/2 -translate-y-1/2 h-3.5 w-3.5 text-gray-400 dark:text-gray-500" />
                  <input
                    placeholder="Filter events..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="pl-8 h-8 w-full text-xs bg-gray-50 dark:bg-gray-800 border border-gray-200 dark:border-gray-700 rounded-md focus:outline-none focus:ring-2 focus:ring-blue-500 dark:text-gray-200"
                  />
                </div>
              </div>

              {/* Stats Row */}
              <div className="grid grid-cols-3 divide-x dark:divide-gray-700 border-b dark:border-gray-700 bg-gray-50 dark:bg-gray-800/50">
                <div className="px-5 py-3 flex items-center justify-between hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors">
                  <div>
                    <p className="text-xs font-medium text-gray-600 dark:text-gray-400 uppercase">Total</p>
                    <div className="flex items-baseline gap-1 mt-0.5">
                      <span className="text-xl font-bold text-gray-900 dark:text-gray-100">{stats.total}</span>
                      <span className="text-xs text-gray-600 dark:text-gray-400">entries</span>
                    </div>
                  </div>
                  <CalendarIcon className="w-8 h-8 p-1.5 rounded-full bg-blue-50 dark:bg-blue-900/30 text-blue-600 dark:text-blue-400" />
                </div>
                <div className="px-5 py-3 flex items-center justify-between hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors">
                  <div>
                    <p className="text-xs font-medium text-gray-600 dark:text-gray-400 uppercase">Special</p>
                    <div className="flex items-baseline gap-1 mt-0.5">
                      <span className="text-xl font-bold text-amber-600 dark:text-amber-500">{stats.special}</span>
                      <span className="text-xs text-gray-600 dark:text-gray-400">events</span>
                    </div>
                  </div>
                  <Star className="w-8 h-8 p-1.5 rounded-full bg-amber-50 dark:bg-amber-900/30 text-amber-600 dark:text-amber-500" />
                </div>
                <div className="px-5 py-3 flex items-center justify-between hover:bg-gray-100 dark:hover:bg-gray-800 transition-colors">
                  <div>
                    <p className="text-xs font-medium text-gray-600 dark:text-gray-400 uppercase">Paid</p>
                    <div className="flex items-baseline gap-1 mt-0.5">
                      <span className="text-xl font-bold text-emerald-600 dark:text-emerald-500">{stats.paid}</span>
                      <span className="text-xs text-gray-600 dark:text-gray-400">active</span>
                    </div>
                  </div>
                  <Briefcase className="w-8 h-8 p-1.5 rounded-full bg-emerald-50 dark:bg-emerald-900/30 text-emerald-600 dark:text-emerald-500" />
                </div>
              </div>

              {/* Table */}
              <div className="flex-1 overflow-auto">
                <table className="w-full">
                  <thead className="sticky top-0 z-20 bg-white dark:bg-gray-900 shadow-sm">
                    <tr className="border-b dark:border-gray-700 text-gray-600 dark:text-gray-400">
                      <th className="text-left px-5 py-3 text-xs font-semibold uppercase">Date</th>
                      <th className="text-left px-3 py-3 text-xs font-semibold uppercase">Type</th>
                      <th className="text-left px-3 py-3 text-xs font-semibold uppercase">
                        Description
                      </th>
                      <th className="text-left px-3 py-3 text-xs font-semibold uppercase">
                        Attributes
                      </th>
                      <th className="text-left px-3 py-3 text-xs font-semibold uppercase">
                        Author
                      </th>
                      <th className="text-right px-5 py-3 text-xs font-semibold uppercase">
                        Action
                      </th>
                    </tr>
                  </thead>
                  <tbody>
                    {paginatedHolidays.length > 0 ? (
                      paginatedHolidays.map((item) => (
                        <tr
                          key={item.id}
                          onClick={() => handleEventClick(item.holiday_date)}
                          className="border-b dark:border-gray-800 hover:bg-blue-50/50 dark:hover:bg-blue-900/10 transition-colors cursor-pointer group"
                        >
                          <td className="px-5 py-3 text-xs font-medium text-gray-700 dark:text-gray-300 group-hover:text-blue-700 dark:group-hover:text-blue-400 transition-colors">
                            {new Date(item.holiday_date).toLocaleDateString("en-US", {
                              month: "short",
                              day: "numeric",
                              year: "numeric",
                            })}
                          </td>
                          <td className="px-3 py-3">
                            <span
                              className={`px-2 py-1 text-[10px] rounded-full font-medium uppercase tracking-wide ${
                                item.holiday_type === "company"
                                  ? "bg-blue-100 dark:bg-blue-900/40 text-blue-700 dark:text-blue-400"
                                  : item.holiday_type === "special"
                                  ? "bg-amber-100 dark:bg-amber-900/40 text-amber-700 dark:text-amber-400"
                                  : "bg-gray-100 dark:bg-gray-800 text-gray-700 dark:text-gray-300"
                              }`}
                            >
                              {item.holiday_type}
                            </span>
                          </td>
                          <td className="px-3 py-3 text-xs font-medium text-gray-800 dark:text-gray-200">
                            {item.description}
                          </td>
                          <td className="px-3 py-3">
                            <div className="flex gap-2 text-xs">
                              {item.is_recurring && (
                                <span className="text-gray-600 dark:text-gray-400 flex items-center gap-1 bg-gray-100 dark:bg-gray-800 px-1.5 py-0.5 rounded border border-gray-200 dark:border-gray-700">
                                  <span className="w-1.5 h-1.5 rounded-full bg-purple-500"></span>{" "}
                                  Recurring
                                </span>
                              )}
                              {item.is_paid ? (
                                <span className="text-emerald-700 dark:text-emerald-400 bg-emerald-50 dark:bg-emerald-900/20 border border-emerald-100 dark:border-emerald-900/40 px-1.5 py-0.5 rounded flex items-center gap-1">
                                  <span className="w-1.5 h-1.5 rounded-full bg-emerald-500"></span>{" "}
                                  Paid
                                </span>
                              ) : (
                                <span className="text-red-700 dark:text-red-400 bg-red-50 dark:bg-red-900/20 border border-red-100 dark:border-red-900/40 px-1.5 py-0.5 rounded flex items-center gap-1">
                                  <span className="w-1.5 h-1.5 rounded-full bg-red-500"></span>{" "}
                                  Unpaid
                                </span>
                              )}
                            </div>
                          </td>
                          <td className="px-3 py-3">
                            <div className="flex items-center gap-2">
                              <div className="w-6 h-6 rounded-full bg-gray-200 dark:bg-gray-700 flex items-center justify-center text-[10px] text-gray-600 dark:text-gray-400">
                                <User className="w-3 h-3" />
                              </div>
                              <div className="flex flex-col">
                                <span className="text-xs font-medium text-gray-700 dark:text-gray-300">{getUserName(item.created_by)}</span>
                              </div>
                            </div>
                          </td>
                          <td className="px-5 py-3 text-right">
                            <div className="flex justify-end gap-1">
                              <button
                                onClick={(e) => handleEdit(e, item)}
                                className="p-1.5 hover:bg-blue-100 rounded text-blue-600 transition-colors"
                                title="Edit"
                              >
                                <Pencil className="h-3.5 w-3.5" />
                              </button>
                              <button
                                onClick={(e) => handleDeleteHoliday(e, item.id)}
                                className="p-1.5 hover:bg-red-100 rounded text-red-600 transition-colors"
                                title="Delete"
                              >
                                <Trash2 className="h-3.5 w-3.5" />
                              </button>
                            </div>
                          </td>
                        </tr>
                      ))
                    ) : (
                      <tr>
                        <td colSpan={6} className="px-5 py-12 text-center text-sm text-gray-500">
                          <div className="flex flex-col items-center gap-2">
                            <Search className="w-8 h-8 text-gray-300" />
                            <p>No events found matching your criteria.</p>
                          </div>
                        </td>
                      </tr>
                    )}
                  </tbody>
                </table>
              </div>

              {/* Pagination */}
              <div className="border-t dark:border-gray-700 px-4 py-2 bg-gray-50 dark:bg-gray-800/50 flex items-center justify-between">
                <span className="text-xs text-gray-600 dark:text-gray-400">
                  Page {currentPage} of {totalPages || 1}
                </span>
                <div className="flex gap-1">
                  <button
                    className="h-7 w-7 border dark:border-gray-700 bg-white dark:bg-gray-800 rounded flex items-center justify-center disabled:opacity-50 hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400"
                    onClick={() => setCurrentPage(1)}
                    disabled={currentPage === 1}
                  >
                    <ChevronsLeft className="h-3.5 w-3.5" />
                  </button>
                  <button
                    className="h-7 w-7 border dark:border-gray-700 bg-white dark:bg-gray-800 rounded flex items-center justify-center disabled:opacity-50 hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400"
                    onClick={() => setCurrentPage((p) => Math.max(1, p - 1))}
                    disabled={currentPage === 1}
                  >
                    <ChevronLeft className="h-3.5 w-3.5" />
                  </button>
                  <button
                    className="h-7 w-7 border dark:border-gray-700 bg-white dark:bg-gray-800 rounded flex items-center justify-center disabled:opacity-50 hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400"
                    onClick={() => setCurrentPage((p) => Math.min(totalPages, p + 1))}
                    disabled={currentPage === totalPages || totalPages === 0}
                  >
                    <ChevronRight className="h-3.5 w-3.5" />
                  </button>
                  <button
                    className="h-7 w-7 border dark:border-gray-700 bg-white dark:bg-gray-800 rounded flex items-center justify-center disabled:opacity-50 hover:bg-gray-100 dark:hover:bg-gray-700 text-gray-600 dark:text-gray-400"
                    onClick={() => setCurrentPage(totalPages)}
                    disabled={currentPage === totalPages || totalPages === 0}
                  >
                    <ChevronsRight className="h-3.5 w-3.5" />
                  </button>
                </div>
              </div>
            </div>
          </div>
        </div>

        {/* Modal */}
        {modalOpen && (
          <div className="fixed inset-0 bg-black/60 backdrop-blur-sm flex items-center justify-center z-50 p-4 animate-in fade-in duration-200">
            <div className="bg-white dark:bg-gray-900 rounded-xl w-full max-w-md shadow-2xl overflow-hidden animate-in zoom-in-95 duration-200 border dark:border-gray-800">
              <div className="px-6 py-4 border-b dark:border-gray-800 bg-gray-50 dark:bg-gray-800/50 flex items-center justify-between">
                <h2 className="text-lg font-bold text-gray-900 dark:text-gray-100">
                  {editingHolidayId ? "Edit Holiday" : "Add Holiday"}
                </h2>
                <button onClick={() => setModalOpen(false)} className="text-gray-400 hover:text-gray-600">
                  <span className="sr-only">Close</span>
                  <svg className="h-5 w-5" fill="none" viewBox="0 0 24 24" stroke="currentColor">
                    <path
                      strokeLinecap="round"
                      strokeLinejoin="round"
                      strokeWidth={2}
                      d="M6 18L18 6M6 6l12 12"
                    />
                  </svg>
                </button>
              </div>
              <div className="p-6 space-y-4">
                <div>
                  <label className="block text-sm font-medium mb-1.5 text-gray-700 dark:text-gray-300">Date</label>
                  <input
                    type="date"
                    value={holidayDate}
                    onChange={(e) => setHolidayDate(e.target.value)}
                    className="w-full border border-gray-300 dark:border-gray-700 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium mb-1.5 text-gray-700 dark:text-gray-300">Last Working Day (Optional)</label>
                  <input
                    type="date"
                    value={lastWorkingDay}
                    onChange={(e) => setLastWorkingDay(e.target.value)}
                    className="w-full border border-gray-300 dark:border-gray-700 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium mb-1.5 text-gray-700 dark:text-gray-300">Description</label>
                  <input
                    placeholder="e.g. Christmas Day"
                    value={description}
                    onChange={(e) => setDescription(e.target.value)}
                    className="w-full border border-gray-300 dark:border-gray-700 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100 placeholder:text-gray-400 dark:placeholder:text-gray-500"
                  />
                </div>
                <div>
                  <label className="block text-sm font-medium mb-1.5 text-gray-700 dark:text-gray-300">Type</label>
                  <select
                    value={holidayType}
                    onChange={(e) => setHolidayType(e.target.value)}
                    className="w-full border border-gray-300 dark:border-gray-700 rounded-lg px-3 py-2 text-sm focus:outline-none focus:ring-2 focus:ring-blue-500 focus:border-transparent transition-all bg-white dark:bg-gray-800 text-gray-900 dark:text-gray-100"
                  >
                    <option value="regular">Regular</option>
                    <option value="special">Special</option>
                    <option value="company">Company</option>
                  </select>
                </div>
                <div className="flex gap-4 pt-2">
                  <label className="flex items-center gap-2 cursor-pointer p-2 border dark:border-gray-700 rounded-lg flex-1 hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors">
                    <input
                      type="checkbox"
                      checked={isRecurring as boolean}
                      onChange={(e) => setIsRecurring(e.target.checked)}
                      className="w-4 h-4 text-blue-600 rounded focus:ring-blue-500 border-gray-300 dark:border-gray-600 dark:bg-gray-700"
                    />
                    <span className="text-sm font-medium text-gray-700 dark:text-gray-300">Recurring</span>
                  </label>
                  <label className="flex items-center gap-2 cursor-pointer p-2 border dark:border-gray-700 rounded-lg flex-1 hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors">
                    <input
                      type="checkbox"
                      checked={isPaid as boolean}
                      onChange={(e) => setIsPaid(e.target.checked)}
                      className="w-4 h-4 text-blue-600 rounded focus:ring-blue-500 border-gray-300 dark:border-gray-600 dark:bg-gray-700"
                    />
                    <span className="text-sm font-medium text-gray-700 dark:text-gray-300">Paid Holiday</span>
                  </label>
                </div>
                <div className="flex justify-end gap-3 mt-8 pt-4 border-t dark:border-gray-800">
                  <button
                    onClick={() => setModalOpen(false)}
                    className="px-4 py-2 border border-gray-300 dark:border-gray-700 rounded-lg hover:bg-gray-50 dark:hover:bg-gray-800 text-gray-700 dark:text-gray-300 text-sm font-medium transition-colors"
                  >
                    Cancel
                  </button>
                  <button
                    onClick={handleSaveHoliday}
                    className="px-4 py-2 bg-blue-600 text-white rounded-lg hover:bg-blue-700 text-sm font-medium shadow-sm transition-colors"
                  >
                    Save Event
                  </button>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </DashboardLayout>
  );
}

"use client";

import React, { useEffect, useState, useCallback } from 'react';
import { Plus, Search, MoreHorizontal, Pencil, Trash2, RefreshCcw } from 'lucide-react';
import { toast } from "sonner";

import { 
  fetchAreas, 
  createArea, 
  patchArea, 
  deleteArea 
} from "../providers/compensation-settingsApi";
import { LogisticsArea } from "../types";
import { generateNextBinaryId } from "../utils/idGenerator";

import { 
  Table, 
  TableBody, 
  TableCell, 
  TableHead, 
  TableHeader, 
  TableRow 
} from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { 
  Dialog, 
  DialogContent, 
  DialogDescription, 
  DialogFooter, 
  DialogHeader, 
  DialogTitle 
} from "@/components/ui/dialog";
import { 
  DropdownMenu, 
  DropdownMenuContent, 
  DropdownMenuItem, 
  DropdownMenuLabel, 
  DropdownMenuTrigger 
} from "@/components/ui/dropdown-menu";
import { Label } from "@/components/ui/label";
import { Separator } from "@/components/ui/separator";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";

export default function AreaTab() {
  const [areas, setAreas] = useState<LogisticsArea[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [modalOpen, setModalOpen] = useState(false);
  const [editingArea, setEditingArea] = useState<LogisticsArea | null>(null);
  const [submitting, setSubmitting] = useState(false);

  // Form states
  const [areaId, setAreaId] = useState("");
  const [areaName, setAreaName] = useState("");
  const [maxDays, setMaxDays] = useState("");
  const [modeType, setModeType] = useState<LogisticsArea['mode_type']>(null);

  const loadAreas = useCallback(async () => {
    setLoading(true);
    try {
      const data = await fetchAreas();
      setAreas(data.data || []);
    } catch (error) {
      console.error(error);
      toast.error("Failed to load areas.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadAreas();
  }, [loadAreas]);

  const handleOpenModal = (area?: LogisticsArea) => {
    if (area) {
      setEditingArea(area);
      setAreaId(area.area_id.toString());
      setAreaName(area.area_name);
      setMaxDays(area.max_days?.toString() || "");
      setModeType(area.mode_type || null);
    } else {
      setEditingArea(null);
      const nextId = generateNextBinaryId(areas.map(a => a.area_id));
      setAreaId(nextId.toString());
      setAreaName("");
      setMaxDays("");
      setModeType(null);
    }
    setModalOpen(true);
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!areaId || !areaName) return toast.error("Please fill in required fields.");

    setSubmitting(true);
    try {
      const payload = {
        area_id: Number(areaId),
        area_name: areaName,
        max_days: maxDays ? Number(maxDays) : null,
        mode_type: modeType || null,
      };

      if (editingArea) {
        await patchArea(editingArea.id, payload);
        toast.success("Area updated successfully.");
      } else {
        await createArea(payload);
        toast.success("Area created successfully.");
      }
      setModalOpen(false);
      loadAreas();
    } catch (error) {
      console.error(error);
      toast.error("Failed to save area.");
    } finally {
      setSubmitting(false);
    }
  };

  const handleDelete = async (id: number) => {
    if (!confirm("Are you sure you want to delete this area?")) return;
    try {
      await deleteArea(id);
      toast.success("Area deleted successfully.");
      loadAreas();
    } catch (error) {
      console.error(error);
      toast.error("Failed to delete area.");
    }
  };

  const filteredAreas = areas.filter(a => 
    a.area_name.toLowerCase().includes(searchTerm.toLowerCase()) ||
    a.area_id.toString().includes(searchTerm)
  );

  return (
    <div className="w-full space-y-4">
      {/* --- Filter / Action Section --- */}
      <div className="flex flex-col md:flex-row gap-4 items-end justify-between">
        {/* Search Field */}
        <div className="flex-1 w-full md:max-w-md space-y-1">
          <label className="text-xs font-medium text-gray-500">
            Search area
          </label>
          <div className="relative">
            <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-gray-400" />
            <Input 
              placeholder="Search Area ID or Name..." 
              className="pl-9 h-10"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>

        {/* Quick Actions */}
        <div className="flex flex-wrap gap-3 w-full md:w-auto">
          <div className="space-y-1">
            <label className="text-xs font-medium text-gray-500">
              Quick Actions
            </label>
            <div className="flex gap-2">
              <Button 
                variant="outline" 
                className="h-10 px-3 gap-2 text-gray-600 border-gray-300"
                onClick={loadAreas}
              >
                <RefreshCcw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} />
                <span className="hidden lg:inline">Refresh</span>
              </Button>
              <Button 
                className="h-10 px-4 gap-2 bg-blue-600 hover:bg-blue-700 text-white"
                onClick={() => handleOpenModal()}
              >
                <Plus className="h-4 w-4" />
                Add Area
              </Button>
            </div>
          </div>
        </div>
      </div>

      <Separator className="my-4" />

      {/* --- Table Section --- */}
      <div className="border rounded-md overflow-hidden shadow-sm">
        <Table>
          <TableHeader className="bg-gray-50 dark:bg-gray-800">
            <TableRow>
              <TableHead className="font-semibold text-gray-600 px-6 py-4">Area ID</TableHead>
              <TableHead className="font-semibold text-gray-600 px-6 py-4">Area Name</TableHead>
              <TableHead className="font-semibold text-gray-600 px-6 py-4">Mode</TableHead>
              <TableHead className="font-semibold text-gray-600 px-6 py-4">Max Days</TableHead>
              <TableHead className="font-semibold text-gray-600 px-6 py-4 text-right">Actions</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              Array.from({ length: 3 }).map((_, i) => (
                <TableRow key={i}>
                  <TableCell colSpan={5} className="h-12 animate-pulse bg-slate-50/50 dark:bg-gray-800/50" />
                </TableRow>
              ))
            ) : filteredAreas.length === 0 ? (
              <TableRow>
                <TableCell colSpan={5} className="h-32 text-center text-slate-500">
                  No areas found.
                </TableCell>
              </TableRow>
            ) : (
              filteredAreas.map((area) => (
                <TableRow key={area.id} className="hover:bg-slate-50 dark:hover:bg-gray-800/50 transition-colors">
                  <TableCell className="px-6 font-medium text-slate-900 dark:text-slate-100">{area.area_id}</TableCell>
                  <TableCell className="px-6 text-slate-700 dark:text-slate-300">{area.area_name}</TableCell>
                  <TableCell className="px-6">
                    {area.mode_type ? (
                      <Badge variant="outline" className="text-[10px] font-bold uppercase tracking-wider bg-slate-50 dark:bg-slate-900">
                        {area.mode_type}
                      </Badge>
                    ) : "—"}
                  </TableCell>
                  <TableCell className="px-6 text-slate-600 dark:text-slate-400">{area.max_days || "—"}</TableCell>
                  <TableCell className="px-6 text-right">
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button variant="ghost" className="h-8 w-8 p-0 border-none">
                          <MoreHorizontal className="h-4 w-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end" className="w-40">
                        <DropdownMenuLabel>Actions</DropdownMenuLabel>
                        <Separator className="my-1" />
                        <DropdownMenuItem onClick={() => handleOpenModal(area)} className="gap-2 cursor-pointer">
                          <Pencil className="h-4 w-4" /> Edit
                        </DropdownMenuItem>
                        <DropdownMenuItem onClick={() => handleDelete(area.id)} className="gap-2 cursor-pointer text-red-600 focus:text-red-700 focus:bg-red-50 dark:focus:bg-red-950">
                          <Trash2 className="h-4 w-4" /> Delete
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>

      <Dialog open={modalOpen} onOpenChange={setModalOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>{editingArea ? "Edit Area" : "Add New Area"}</DialogTitle>
            <DialogDescription>
              Enter the details for the geographical area.
            </DialogDescription>
          </DialogHeader>
          <form onSubmit={handleSave} className="space-y-4 py-4">
            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="areaId" className="text-right">Area ID *</Label>
              <Input 
                id="areaId" 
                type="number" 
                className="col-span-3 bg-slate-50 dark:bg-gray-800" 
                value={areaId} 
                onChange={(e) => setAreaId(e.target.value)} 
                readOnly 
                required 
              />
            </div>
            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="areaName" className="text-right">Area Name *</Label>
              <Input 
                id="areaName" 
                className="col-span-3" 
                value={areaName} 
                onChange={(e) => setAreaName(e.target.value)} 
                required 
              />
            </div>
            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="modeType" className="text-right">Mode</Label>
              <div className="col-span-3">
                <Select value={modeType || "none"} onValueChange={(val) => setModeType(val === "none" ? null : val as any)}>
                  <SelectTrigger id="modeType">
                    <SelectValue placeholder="Select mode type" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">None</SelectItem>
                    <SelectItem value="DELIVERY">DELIVERY</SelectItem>
                    <SelectItem value="PICKUP ONLY">PICKUP ONLY</SelectItem>
                    <SelectItem value="PICKUP W/ MP DELIVERY">PICKUP W/ MP DELIVERY</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="maxDays" className="text-right">Max Days</Label>
              <Input 
                id="maxDays" 
                type="number" 
                className="col-span-3" 
                value={maxDays} 
                onChange={(e) => setMaxDays(e.target.value)} 
              />
            </div>
          </form>
          <DialogFooter>
            <Button variant="outline" onClick={() => setModalOpen(false)}>Cancel</Button>
            <Button onClick={handleSave} disabled={submitting} className="bg-blue-600 hover:bg-blue-700">
              {submitting ? "Saving..." : "Save Changes"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

"use client";

import React, { useEffect, useState, useCallback } from 'react';
import { Plus, Search, MoreHorizontal, Pencil, Trash2, RefreshCcw, User } from 'lucide-react';
import { toast } from "sonner";

import { 
  fetchStaffs, 
  createStaff, 
  patchStaff, 
  deleteStaff,
  fetchVehicleTypes
} from "../providers/compensation-settingsApi";
import { LogisticsStaff, LogisticsVehicleType } from "../types";
import { generateNextBinaryId } from "../utils/idGenerator";

import { 
  Table, 
  TableBody, 
  TableCell, 
  TableHead, 
  TableHeader, 
  TableRow 
} from "@/components/ui/table";
import { Button } from "@/components/ui/button";
import { Input } from "@/components/ui/input";
import { 
  Dialog, 
  DialogContent, 
  DialogDescription, 
  DialogFooter, 
  DialogHeader, 
  DialogTitle 
} from "@/components/ui/dialog";
import { 
  DropdownMenu, 
  DropdownMenuContent, 
  DropdownMenuItem, 
  DropdownMenuLabel, 
  DropdownMenuTrigger 
} from "@/components/ui/dropdown-menu";
import { Label } from "@/components/ui/label";
import { Separator } from "@/components/ui/separator";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Badge } from "@/components/ui/badge";

export default function StaffTab() {
  const [staffList, setStaffList] = useState<LogisticsStaff[]>([]);
  const [vehicleTypes, setVehicleTypes] = useState<LogisticsVehicleType[]>([]);
  const [loading, setLoading] = useState(true);
  const [searchTerm, setSearchTerm] = useState("");
  const [modalOpen, setModalOpen] = useState(false);
  const [editingStaff, setEditingStaff] = useState<LogisticsStaff | null>(null);
  const [submitting, setSubmitting] = useState(false);

  // Form states
  const [staffId, setStaffId] = useState("");
  const [role, setRole] = useState<'Driver' | 'Helper'>('Driver');
  const [employmentType, setEmploymentType] = useState<string>("");
  const [vehicleTypeId, setVehicleTypeId] = useState<string>("");

  const loadData = useCallback(async () => {
    setLoading(true);
    try {
      const [staffRes, vtRes] = await Promise.all([
        fetchStaffs(),
        fetchVehicleTypes()
      ]);
      setStaffList(staffRes.data || []);
      setVehicleTypes(vtRes.data || []);
    } catch (error) {
      console.error(error);
      toast.error("Failed to load staff or vehicle types.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadData();
  }, [loadData]);

  const handleOpenModal = (staff?: LogisticsStaff) => {
    if (staff) {
      setEditingStaff(staff);
      setStaffId(staff.staff_id.toString());
      setRole(staff.role);
      setEmploymentType(staff.employment_type || "");
      setVehicleTypeId(staff.vehicle_type_id?.toString() || "");
    } else {
      setEditingStaff(null);
      const nextId = generateNextBinaryId(staffList.map(s => s.staff_id));
      setStaffId(nextId.toString());
      setRole('Driver');
      setEmploymentType("");
      setVehicleTypeId("");
    }
    setModalOpen(true);
  };

  const handleSave = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!staffId || !role) return toast.error("Please fill in required fields.");

    setSubmitting(true);
    try {
      const payload = {
        staff_id: Number(staffId),
        role: role,
        employment_type: employmentType as any || null,
        vehicle_type_id: vehicleTypeId ? Number(vehicleTypeId) : null,
      };

      if (editingStaff) {
        await patchStaff(editingStaff.id, payload);
        toast.success("Staff updated successfully.");
      } else {
        await createStaff(payload);
        toast.success("Staff created successfully.");
      }
      setModalOpen(false);
      loadData();
    } catch (error) {
      console.error(error);
      toast.error("Failed to save staff.");
    } finally {
      setSubmitting(false);
    }
  };

  const handleDelete = async (id: number) => {
    if (!confirm("Are you sure you want to delete this staff?")) return;
    try {
      await deleteStaff(id);
      toast.success("Staff deleted successfully.");
      loadData();
    } catch (error) {
      console.error(error);
      toast.error("Failed to delete staff.");
    }
  };

  const filteredStaff = staffList.filter(s => 
    s.staff_id.toString().includes(searchTerm) ||
    s.role.toLowerCase().includes(searchTerm.toLowerCase()) ||
    s.employment_type?.toLowerCase().includes(searchTerm.toLowerCase())
  );

  const getVehicleTypeName = (id: number) => {
    return vehicleTypes.find(vt => vt.vehicle_type_id === id)?.vehicle_type || `VT ${id}`;
  };

  return (
    <div className="w-full space-y-4">
      {/* --- Filter / Action Section --- */}
      <div className="flex flex-col md:flex-row gap-4 items-end justify-between">
        {/* Search Field */}
        <div className="flex-1 w-full md:max-w-md space-y-1">
          <label className="text-xs font-medium text-gray-500">
            Search staff
          </label>
          <div className="relative">
            <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-gray-400" />
            <Input 
              placeholder="Search Staff ID, Role or Employment..." 
              className="pl-9 h-10"
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
            />
          </div>
        </div>

        {/* Quick Actions */}
        <div className="flex flex-wrap gap-3 w-full md:w-auto">
          <div className="space-y-1">
            <label className="text-xs font-medium text-gray-500">
              Quick Actions
            </label>
            <div className="flex gap-2">
              <Button 
                variant="outline" 
                className="h-10 px-3 gap-2 text-gray-600 border-gray-300"
                onClick={loadData}
              >
                <RefreshCcw className={`h-4 w-4 ${loading ? 'animate-spin' : ''}`} />
                <span className="hidden lg:inline">Refresh</span>
              </Button>
              <Button 
                className="h-10 px-4 gap-2 bg-blue-600 hover:bg-blue-700 text-white"
                onClick={() => handleOpenModal()}
              >
                <Plus className="h-4 w-4" />
                Add Staff
              </Button>
            </div>
          </div>
        </div>
      </div>

      <Separator className="my-4" />

      {/* --- Table Section --- */}
      <div className="border rounded-md overflow-hidden shadow-sm">
        <Table>
          <TableHeader className="bg-gray-50 dark:bg-gray-800">
            <TableRow>
              <TableHead className="font-semibold text-gray-600 px-6 py-4">Staff ID</TableHead>
              <TableHead className="font-semibold text-gray-600 px-6 py-4">Role</TableHead>
              <TableHead className="font-semibold text-gray-600 px-6 py-4">Employment Type</TableHead>
              <TableHead className="font-semibold text-gray-600 px-6 py-4">Assigned Vehicle</TableHead>
              <TableHead className="font-semibold text-gray-600 px-6 py-4 text-right">Actions</TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              Array.from({ length: 3 }).map((_, i) => (
                <TableRow key={i}>
                  <TableCell colSpan={5} className="h-12 animate-pulse bg-slate-50/50 dark:bg-gray-800/50" />
                </TableRow>
              ))
            ) : filteredStaff.length === 0 ? (
              <TableRow>
                <TableCell colSpan={5} className="h-32 text-center text-slate-500">
                  No staff members found.
                </TableCell>
              </TableRow>
            ) : (
              filteredStaff.map((staff) => (
                <TableRow key={staff.id} className="hover:bg-slate-50 dark:hover:bg-gray-800/50 transition-colors">
                  <TableCell className="px-6 font-medium text-slate-900 dark:text-slate-100 flex items-center gap-2">
                    <User className="h-4 w-4 text-slate-400" />
                    {staff.staff_id}
                  </TableCell>
                  <TableCell className="px-6 text-slate-700 dark:text-slate-300">
                    <Badge variant={staff.role === 'Driver' ? 'default' : 'secondary'} className="rounded-md px-2 py-0.5 text-[10px] uppercase font-bold tracking-wider">
                      {staff.role}
                    </Badge>
                  </TableCell>
                  <TableCell className="px-6 text-slate-700 dark:text-slate-300">
                    {staff.employment_type ? (
                      <span className="text-xs font-medium text-slate-600 dark:text-slate-400">
                        {staff.employment_type}
                      </span>
                    ) : "—"}
                  </TableCell>
                  <TableCell className="px-6 text-slate-600 dark:text-slate-400">
                    {staff.vehicle_type_id ? (
                      <span className="px-2 py-1 rounded-md bg-amber-50 dark:bg-amber-900/30 text-amber-700 dark:text-amber-300 text-[10px] font-bold">
                        {getVehicleTypeName(staff.vehicle_type_id)}
                      </span>
                    ) : "—"}
                  </TableCell>
                  <TableCell className="px-6 text-right">
                    <DropdownMenu>
                      <DropdownMenuTrigger asChild>
                        <Button variant="ghost" className="h-8 w-8 p-0 border-none">
                          <MoreHorizontal className="h-4 w-4" />
                        </Button>
                      </DropdownMenuTrigger>
                      <DropdownMenuContent align="end" className="w-40">
                        <DropdownMenuLabel>Actions</DropdownMenuLabel>
                        <Separator className="my-1" />
                        <DropdownMenuItem onClick={() => handleOpenModal(staff)} className="gap-2 cursor-pointer">
                          <Pencil className="h-4 w-4" /> Edit
                        </DropdownMenuItem>
                        <DropdownMenuItem onClick={() => handleDelete(staff.id)} className="gap-2 cursor-pointer text-red-600 focus:text-red-700 focus:bg-red-50 dark:focus:bg-red-950">
                          <Trash2 className="h-4 w-4" /> Delete
                        </DropdownMenuItem>
                      </DropdownMenuContent>
                    </DropdownMenu>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>

      <Dialog open={modalOpen} onOpenChange={setModalOpen}>
        <DialogContent className="sm:max-w-md">
          <DialogHeader>
            <DialogTitle>{editingStaff ? "Edit Staff" : "Add New Staff"}</DialogTitle>
            <DialogDescription>
              Enter the details for the personnel category.
            </DialogDescription>
          </DialogHeader>
          <form onSubmit={handleSave} className="space-y-4 py-4">
            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="staffId" className="text-right">Staff ID *</Label>
              <Input 
                id="staffId" 
                type="number" 
                className="col-span-3 bg-slate-50 dark:bg-gray-800" 
                value={staffId} 
                onChange={(e) => setStaffId(e.target.value)} 
                readOnly 
                required 
              />
            </div>
            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="role" className="text-right">Role *</Label>
              <div className="col-span-3">
                <Select value={role} onValueChange={(val: any) => setRole(val)} required>
                  <SelectTrigger>
                    <SelectValue placeholder="Select a role" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="Driver">Driver</SelectItem>
                    <SelectItem value="Helper">Helper</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="employmentType" className="text-right whitespace-nowrap">Employment *</Label>
              <div className="col-span-3">
                <Select value={employmentType} onValueChange={setEmploymentType} required>
                  <SelectTrigger>
                    <SelectValue placeholder="Select an employment type" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="EXTRA">EXTRA</SelectItem>
                    <SelectItem value="PROBATIONARY">PROBATIONARY</SelectItem>
                    <SelectItem value="REGULAR(<10W)">REGULAR(&lt;10W)</SelectItem>
                    <SelectItem value="REGULAR(10W/T)">REGULAR(10W/T)</SelectItem>
                  </SelectContent>
                </Select>
              </div>
            </div>
            <div className="grid grid-cols-4 items-center gap-4">
              <Label htmlFor="vehicleTypeId" className="text-right">Vehicle Type</Label>
              <div className="col-span-3">
                <Select value={vehicleTypeId} onValueChange={setVehicleTypeId}>
                  <SelectTrigger>
                    <SelectValue placeholder="Assign a vehicle type" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="none">None</SelectItem>
                    {vehicleTypes.map(vt => (
                      <SelectItem key={vt.vehicle_type_id} value={vt.vehicle_type_id.toString()}>
                        {vt.vehicle_type}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
            </div>
          </form>
          <DialogFooter>
            <Button variant="outline" onClick={() => setModalOpen(false)}>Cancel</Button>
            <Button onClick={handleSave} disabled={submitting} className="bg-blue-600 hover:bg-blue-700">
              {submitting ? "Saving..." : "Save Changes"}
            </Button>
          </DialogFooter>
        </DialogContent>
      </Dialog>
    </div>
  );
}

