"use client";

import { useState, useEffect } from "react";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { FileDown, Eye, Loader2 } from "lucide-react";
import { exportCoopPdf, CoopPaperSize } from "../../utils/coopExportPdf";
import { listItems } from "../../providers/coopApi";
import { Label } from "@/components/ui/label";
import { CutoffSetting } from "@/modules/benefit-settings/types";
import { fetchCompanyConfig } from "@/modules/benefit-settings/providers/benefitApi";

interface PrintPreviewModalProps {
  isOpen: boolean;
  onClose: () => void;
  type: "savings" | "loans";
  data: any[];
  searchTerm: string;
  statusFilter: string;
}

export function PrintPreviewModal({
  isOpen,
  onClose,
  type,
  data,
  searchTerm,
  statusFilter,
}: PrintPreviewModalProps) {
  const [paperSize, setPaperSize] = useState<CoopPaperSize>("LETTER");
  const [previewUrl, setPreviewUrl] = useState<string | null>(null);
  const [isGenerating, setIsGenerating] = useState(false);
  const [cutoffs, setCutoffs] = useState<CutoffSetting[]>([]);
  const [selectedCutoff, setSelectedCutoff] = useState<string>("all");
  const [companyName, setCompanyName] = useState<string>("MEN2 MARKETING CORPORATION");

  useEffect(() => {
    if (isOpen) {
      const fetchCutoffs = async () => {
        try {
          const [{ data: list }, config] = await Promise.all([
            listItems<CutoffSetting>("cutoff_settings", {
              limit: "100",
              sort: "-start_date",
            }),
            fetchCompanyConfig()
          ]);
          setCutoffs(list);
          if (config?.companyName) {
            setCompanyName(config.companyName);
          }
        } catch (error) {
          console.error("Failed to fetch cutoffs or config:", error);
        }
      };
      fetchCutoffs();
    }
  }, [isOpen]);

  const generatePreview = async () => {
    setIsGenerating(true);
    try {
      const doc = await exportCoopPdf({
        paper: paperSize,
        type,
        data,
        searchTerm,
        statusFilter,
        cutoffId: selectedCutoff === "all" ? undefined : Number(selectedCutoff),
        cutoffs,
        companyName,
      });

      const blob = doc.output("blob");
      if (previewUrl) URL.revokeObjectURL(previewUrl);
      const url = URL.createObjectURL(blob);
      setPreviewUrl(url);
    } catch (error) {
      console.error("Failed to generate PDF preview:", error);
    } finally {
      setIsGenerating(false);
    }
  };

  useEffect(() => {
    if (isOpen && data.length > 0) {
      generatePreview();
    }
    return () => {
      if (previewUrl) {
        URL.revokeObjectURL(previewUrl);
        setPreviewUrl(null);
      }
    };
  }, [isOpen, paperSize, type, data, selectedCutoff]);

  const handleDownload = () => {
    if (previewUrl) {
      const link = document.createElement("a");
      link.href = previewUrl;
      link.download = `Coop_${type}_${new Date().toISOString().split("T")[0]}.pdf`;
      link.click();
    }
  };

  return (
    <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
      <DialogContent className="max-w-[95vw] sm:max-w-4xl h-[90vh] flex flex-col p-0 overflow-hidden">
        <DialogHeader className="px-6 py-4 border-b bg-background">
          <div className="flex items-center justify-between gap-4">
            <div className="space-y-1">
              <DialogTitle className="text-lg">
                {type === "savings" ? "Savings Report Preview" : "Loans Report Preview"}
              </DialogTitle>
              <p className="text-xs text-muted-foreground">
                Review the generated report before downloading.
              </p>
            </div>
            <div className="flex items-center gap-3">
              <div className="flex items-center gap-2">
                <span className="text-xs font-medium text-muted-foreground">Paper Size:</span>
                <Select
                  value={paperSize}
                  onValueChange={(val) => setPaperSize(val as CoopPaperSize)}
                >
                  <SelectTrigger className="h-8 w-[100px]">
                    <SelectValue placeholder="Size" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="LETTER">Letter</SelectItem>
                    <SelectItem value="A4">A4</SelectItem>
                    <SelectItem value="LEGAL">Legal</SelectItem>
                  </SelectContent>
                </Select>
              </div>

              <div className="h-8 border-r mx-1" />

              <div className="flex items-center gap-2">
                <span className="text-xs font-medium text-muted-foreground">Cutoff:</span>
                <Select value={selectedCutoff} onValueChange={setSelectedCutoff}>
                  <SelectTrigger className="h-8 w-[180px] text-xs">
                    <SelectValue placeholder="Select Cutoff" />
                  </SelectTrigger>
                  <SelectContent>
                    <SelectItem value="all">All Dates</SelectItem>
                    {cutoffs.map((c) => (
                      <SelectItem key={`cutoff-${c.id}`} value={String(c.id)}>
                        {`${new Date(c.start_date).toLocaleDateString()} (${c.cutoff_type})`}
                      </SelectItem>
                    ))}
                  </SelectContent>
                </Select>
              </div>
              <Button
                variant="default"
                size="sm"
                onClick={handleDownload}
                disabled={!previewUrl || isGenerating}
                className="bg-blue-600 hover:bg-blue-700 text-white"
              >
                <FileDown className="mr-2 h-4 w-4" />
                Download PDF
              </Button>
            </div>
          </div>
        </DialogHeader>

        <div className="flex-1 bg-muted/20 relative w-full h-full">
          {isGenerating ? (
            <div className="absolute inset-0 flex flex-col items-center justify-center gap-3 bg-background/50 backdrop-blur-sm z-10">
              <Loader2 className="h-8 w-8 animate-spin text-blue-600" />
              <p className="text-sm font-medium text-muted-foreground">Generating preview...</p>
            </div>
          ) : previewUrl ? (
            <iframe
              title="PDF Preview"
              src={`${previewUrl}#toolbar=0&view=FitH`}
              className="w-full h-full border-0"
            />
          ) : (
            <div className="flex items-center justify-center h-full text-muted-foreground">
              <div className="text-center space-y-2">
                <Eye className="h-12 w-12 mx-auto opacity-20" />
                <p>No data to preview</p>
              </div>
            </div>
          )}
        </div>
      </DialogContent>
    </Dialog>
  );
}

export const INTERNAL_API = "/api/coop";

export type CoopCollection =
  | "employee_loan"
  | "user"
  | "employee_loan_payment"
  | "coop_savings_membership"
  | "cutoff_settings";

type JsonValue = unknown;

async function readErrorText(res: Response) {
  try {
    return await res.text();
  } catch {
    return "Request failed.";
  }
}

async function fetchJson<T = JsonValue>(
  url: string,
  init?: RequestInit,
  signal?: AbortSignal
): Promise<T> {
  const res = await fetch(url, { ...init, signal });
  if (!res.ok) {
    const msg = await readErrorText(res);
    const err = new Error(msg);
    // @ts-expect-error attach status for callers that want it
    err.status = res.status;
    throw err;
  }
  // DELETE may return 204; calling code should avoid parsing
  if (res.status === 204) return undefined as unknown as T;
  return (await res.json()) as T;
}

function buildUrl(collection: CoopCollection, params?: Record<string, string>) {
  const sp = new URLSearchParams();
  sp.set("collection", collection);
  if (params) {
    for (const [k, v] of Object.entries(params)) {
      if (v !== undefined && v !== null && String(v).length > 0) sp.set(k, v);
    }
  }
  return `${INTERNAL_API}?${sp.toString()}`;
}

export async function listItems<T>(
  collection: CoopCollection,
  params?: Record<string, string>,
  signal?: AbortSignal
): Promise<{ data: T[]; meta?: any }> {
  const url = buildUrl(collection, params);
  const json = await fetchJson<any>(url, undefined, signal);
  return {
    data: Array.isArray(json?.data) ? (json.data as T[]) : [],
    meta: json?.meta,
  };
}

export async function createItem<T>(
  collection: CoopCollection,
  body: unknown
): Promise<T> {
  const url = buildUrl(collection);
  const json = await fetchJson<any>(
    url,
    {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    },
    undefined
  );
  return (json?.data ?? json) as T;
}

export async function updateItem<T>(
  collection: CoopCollection,
  id: number,
  body: unknown
): Promise<T> {
  const url = buildUrl(collection, { id: String(id) });
  const json = await fetchJson<any>(
    url,
    {
      method: "PATCH",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(body),
    },
    undefined
  );
  return (json?.data ?? json) as T;
}

export async function deleteItem(
  collection: CoopCollection,
  id: number
): Promise<void> {
  const url = buildUrl(collection, { id: String(id) });
  await fetchJson<any>(
    url,
    {
      method: "DELETE",
    },
    undefined
  );
}

"use client";

import { formatPeso } from "../helpers";
import type { Membership, EmployeeLoan, LoanRowData, User } from "../types";
import { CutoffSetting } from "@/modules/benefit-settings/types";

export type CoopPaperSize = "LETTER" | "A4" | "LEGAL";

function paperToJsPdfFormat(paper: CoopPaperSize): "letter" | "a4" | "legal" {
  if (paper === "A4") return "a4";
  if (paper === "LEGAL") return "legal";
  return "letter";
}

export async function exportCoopPdf(args: {
  paper: CoopPaperSize;
  type: "savings" | "loans";
  data: any[];
  searchTerm?: string;
  statusFilter?: string;
  cutoffId?: number;
  cutoffs?: CutoffSetting[];
  companyName?: string;
}) {
  const { paper, type, data: rawData, searchTerm, statusFilter, cutoffId, cutoffs, companyName } = args;

  const [{ jsPDF }, autoTableMod] = await Promise.all([
    import("jspdf"),
    import("jspdf-autotable"),
  ]);
  const autoTable = (autoTableMod as any).default ?? (autoTableMod as any);

  const format = paperToJsPdfFormat(paper);
  const doc = new jsPDF({
    orientation: "portrait",
    unit: "pt",
    format,
  });

  const pageW = doc.internal.pageSize.getWidth();
  const pageH = doc.internal.pageSize.getHeight();
  const marginX = 40;

  // --- Branding Colors (Premium System) ---
  const DARK_BLUE = [11, 19, 43] as [number, number, number];
  const CYAN = [0, 180, 216] as [number, number, number];
  const LIGHT_BLUE = [144, 224, 239] as [number, number, number];

  const setFill = (rgb: number[]) => doc.setFillColor(rgb[0], rgb[1], rgb[2]);
  const setText = (rgb: number[]) => doc.setTextColor(rgb[0], rgb[1], rgb[2]);

  const displayTitle = type === "savings" ? "COOP SAVINGS REPORT" : "COOP LOANS REPORT";
  const footerH = 50;

  const renderHeader = (isFirstPage: boolean) => {
    // --- HEADER RIBBON (Top Left) ---
    setFill(DARK_BLUE);
    doc.triangle(0, 0, 180, 0, 0, 80, "F");
    setFill(CYAN);
    doc.triangle(0, 15, 120, 15, 0, 65, "F");
    setFill(LIGHT_BLUE);
    doc.triangle(0, 30, 80, 30, 0, 55, "F");
    setFill(DARK_BLUE);
    doc.rect(180, 0, pageW - 180, 15, "F");

    // --- COMPANY LOGO & NAME ---
    let headerY = 50;
    setText(DARK_BLUE);
    doc.setFont("helvetica", "bold");

    const nameStr = (companyName || "").toUpperCase().trim();
    const lastSpaceIdx = nameStr.lastIndexOf(" ");

    if (lastSpaceIdx === -1) {
      doc.setFontSize(22);
      doc.text(nameStr || "MEN2 MARKETING", pageW - marginX, headerY, { align: "right" });
    } else {
      const p1 = nameStr.substring(0, lastSpaceIdx);
      const p2 = nameStr.substring(lastSpaceIdx + 1);

      doc.setFontSize(22);
      doc.text(p1, pageW - marginX, headerY, { align: "right" });

      headerY += 18;
      setText(CYAN);
      doc.setFontSize(10);
      doc.text(p2, pageW - marginX, headerY, { align: "right" });
    }

    // Divider Line
    headerY += 15;
    doc.setDrawColor(DARK_BLUE[0], DARK_BLUE[1], DARK_BLUE[2]);
    doc.setLineWidth(1.5);
    doc.line(pageW - 250, headerY, pageW - marginX, headerY);

    // --- REPORT TITLE ---
    headerY += 60;
    setText(DARK_BLUE);
    doc.setFontSize(16);
    doc.text(displayTitle.toUpperCase(), marginX, headerY);

    doc.setFont("helvetica", "normal");
    doc.setFontSize(10);
    doc.text(
      `DATE: ${new Date()
        .toLocaleDateString("en-US", {
          day: "numeric",
          month: "long",
          year: "numeric",
        })
        .toUpperCase()}`,
      pageW - marginX,
      headerY,
      { align: "right" }
    );

    if (isFirstPage) {
      const statsY = headerY + 40;
      doc.setTextColor(11, 19, 43);
      doc.setFontSize(9);
      doc.setFont("helvetica", "bold");

      const filtersArr = [];
      if (searchTerm) filtersArr.push(`SEARCH: ${searchTerm.toUpperCase()}`);
      if (statusFilter && statusFilter !== "All") filtersArr.push(`STATUS: ${statusFilter.toUpperCase()}`);

      // Add Cutoff info
      if (cutoffId) {
        const selected = cutoffs?.find(c => c.id === cutoffId);
        if (selected) {
          const dateText = new Date(selected.start_date).toLocaleDateString();
          filtersArr.push(`CUTOFF: ${dateText} (${selected.cutoff_type})`);
        }
      }

      const filterText = filtersArr.length > 0 ? filtersArr.join("   |   ") : "ALL RECORDS";
      doc.text(filterText, pageW / 2, statsY, { align: "center" });

      doc.setDrawColor(226, 232, 240);
      doc.setLineWidth(0.5);
      doc.line(marginX, statsY + 10, pageW - marginX, statsY + 10);
      return statsY + 12;
    }
    return headerY + 20;
  };

  // --- FILTER BY CUTOFF ---
  let filteredData = rawData;
  if (cutoffId) {
    const selected = cutoffs?.find(c => c.id === cutoffId);
    if (selected) {
      const startDate = new Date(selected.start_date);
      const endDate = new Date(selected.end_date);

      filteredData = rawData.filter(r => {
        const recordStart = r.start ? new Date(r.start) : (r.loan?.start_date ? new Date(r.loan.start_date) : null);
        const recordEnd = r.end ? new Date(r.end) : (r.loan?.end_date ? new Date(r.loan.end_date) : null);

        if (recordEnd && recordEnd < startDate) return false;
        if (recordStart && recordStart > endDate) return false;

        return true;
      });
    }
  }

  const renderFooter = (pageNumber: number, totalPages: number) => {
    const footerY = pageH - footerH;

    setFill(DARK_BLUE);
    doc.rect(0, footerY, pageW, footerH, "F");

    setFill(CYAN);
    doc.triangle(pageW, pageH, pageW - 120, pageH, pageW, pageH - 40, "F");
    setFill(LIGHT_BLUE);
    doc.triangle(pageW, pageH, pageW - 80, pageH, pageW, pageH - 25, "F");

    setText([255, 255, 255]);
    doc.setFontSize(10);
    doc.setFont("helvetica", "bold");
    doc.text((companyName || "VERTEX TECHNOLOGIES CORPORATIONS").toUpperCase(), marginX, footerY + 30);

    doc.setFontSize(8);
    doc.setFont("helvetica", "normal");
    doc.text(
      `Page ${pageNumber} of ${totalPages}`,
      pageW - marginX - 100,
      footerY + 30,
      { align: "right" }
    );
  };

  const lastY = renderHeader(true);

  if (type === "savings") {
    const head = [["No.", "Membership ID", "Name", "Monthly", "Total Collection", "Months", "Status"]];
    const body = filteredData.map((r, i) => [
      i + 1,
      r.membershipId || "-",
      r.name,
      formatPeso(r.monthly),
      formatPeso(r.totalCollection),
      r.totalMonths,
      r.raw.is_active === 1 ? "Active" : "Inactive",
    ]);

    autoTable(doc, {
      startY: lastY + 10,
      head,
      body,
      theme: "striped",
      margin: { left: marginX, right: marginX, bottom: footerH + 10 },
      styles: { fontSize: 8, cellPadding: 5 },
      headStyles: { fillColor: DARK_BLUE, textColor: [255, 255, 255] },
      columnStyles: {
        3: { halign: "right" },
        4: { halign: "right" },
        5: { halign: "center" },
      },
    });
  } else {
    const head = [["No.", "Name", "Loan Amount", "Total Paid", "Balance", "Monthly", "Status"]];
    const body = filteredData.map((r, i) => [
      i + 1,
      r.name,
      formatPeso(r.loanAmount),
      formatPeso(r.totalPaid),
      formatPeso(r.balance),
      formatPeso(r.loan.monthly_payment),
      r.loan.status,
    ]);

    autoTable(doc, {
      startY: lastY + 10,
      head,
      body,
      theme: "striped",
      margin: { left: marginX, right: marginX, bottom: footerH + 10 },
      styles: { fontSize: 8, cellPadding: 5 },
      headStyles: { fillColor: DARK_BLUE, textColor: [255, 255, 255] },
      columnStyles: {
        2: { halign: "right" },
        3: { halign: "right" },
        4: { halign: "right" },
        5: { halign: "right" },
      },
    });
  }

  const totalPages = doc.getNumberOfPages();
  for (let i = 1; i <= totalPages; i++) {
    doc.setPage(i);
    renderFooter(i, totalPages);
  }

  return doc;
}

