  return (
    <>
      <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
        <DialogContent className="w-[75vw] sm:max-w-none h-[80vh] flex flex-col p-0 overflow-hidden bg-background border-none shadow-2xl">
          {/* Premium Header with Gradient */}
          <div className="relative p-8 pb-6 bg-gradient-to-br from-blue-50/50 via-background to-background dark:from-blue-950/20 dark:via-background dark:to-background border-b shadow-sm">
            <div className="flex items-center justify-between">
              <div className="space-y-1">
                <DialogTitle className="flex items-center gap-2 text-2xl font-bold tracking-tight">
                  <div className="p-2 rounded-lg bg-blue-500/10 text-blue-500">
                    <History className="h-6 w-6" />
                  </div>
                  Benefit History
                </DialogTitle>
                <p className="text-muted-foreground ml-11 text-sm font-medium">
                  Viewing records for <span className="text-foreground">{employee?.user_fname} {employee?.user_lname}</span>
                </p>
              </div>
              
              <div className="flex items-center gap-3">
                <div className="flex items-center gap-1 bg-muted/50 p-1 rounded-lg border">
                  <Button 
                    variant={reportType === "contributions" ? "default" : "ghost"}
                    size="sm"
                    className="h-8 rounded-md text-xs font-bold"
                    onClick={() => setReportType("contributions")}
                  >
                    Contributions
                  </Button>
                  <Button 
                    variant={reportType === "loans" ? "default" : "ghost"}
                    size="sm"
                    className="h-8 rounded-md text-xs font-bold"
                    onClick={() => setReportType("loans")}
                  >
                    Loans
                  </Button>
                </div>

                <div className="h-8 w-px bg-border mx-1" />

                <div className="relative w-64">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground/50" />
                  <Input
                    placeholder="Filter results..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="pl-10 h-10 bg-background/50 border-muted-foreground/10 focus-visible:ring-blue-500 rounded-lg"
                  />
                </div>
                <Select value={selectedMonth} onValueChange={setSelectedMonth}>
                  <SelectTrigger className="h-10 w-48 bg-background/50 border-muted-foreground/10 focus:ring-blue-500 rounded-lg">
                    <SelectValue placeholder="All Months" />
                  </SelectTrigger>
                  <SelectContent className="rounded-lg">
                    <SelectItem value="all">Every Month</SelectItem>
                    {uniqueMonths.map(month => (
                      <SelectItem key={month} value={month}>{month}</SelectItem>
                    ))}
                  </SelectContent>
                </Select>

                <div className="h-8 w-px bg-border mx-1" />
                
                <div className="flex items-center gap-2">
                  <Button 
                    variant="outline" 
                    className="h-10 px-4 rounded-lg shadow-sm border-muted-foreground/10 hover:bg-blue-50 hover:text-blue-600 transition-all gap-2 font-semibold"
                    onClick={() => handlePDFAction(false)}
                    disabled={isGenerating || selectedMonth === "all"}
                  >
                    <Eye className="h-4 w-4" />
                    Preview and Download
                  </Button>
                </div>
              </div>
            </div>
          </div>

          {/* Table Content with Animations */}
          <div className="flex-1 overflow-auto p-8 pt-4">
            {loading ? (
              <div className="flex flex-col items-center justify-center h-full gap-4 text-muted-foreground">
                <div className="relative">
                  <div className="absolute inset-0 rounded-full blur-xl bg-blue-500/20 animate-pulse" />
                  <Loader2 className="h-10 w-10 animate-spin text-blue-500 relative" />
                </div>
                <p className="font-medium animate-pulse">Retriving financial records...</p>
              </div>
            ) : filteredData.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center text-muted-foreground border-2 border-dashed rounded-2xl bg-muted/5 transition-colors group hover:bg-muted/10">
                <div className="p-4 rounded-full bg-muted group-hover:bg-muted/20 transition-all mb-4">
                  <Search className="h-8 w-8 opacity-20" />
                </div>
                <p className="font-medium">{searchTerm ? "No results match your filter criteria." : `No ${reportType} records found.`}</p>
                <Button 
                  variant="link" 
                  size="sm" 
                  className="mt-2 text-blue-500"
                  onClick={() => { setSearchTerm(""); setSelectedMonth("all"); }}
                >
                  Clear all filters
                </Button>
              </div>
            ) : (
              <div className="rounded-xl border bg-card shadow-sm overflow-hidden flex flex-col h-full">
                <div className="flex-1 overflow-auto">
                  <Table>
                    <TableHeader className="bg-muted/30 sticky top-0 z-10">
                      {table.getHeaderGroups().map((headerGroup) => (
                        <TableRow key={headerGroup.id} className="hover:bg-transparent border-none">
                          {headerGroup.headers.map((header) => (
                            <TableHead key={header.id} className="px-6 h-12">
                              {header.isPlaceholder
                                ? null
                                : flexRender(
                                    header.column.columnDef.header,
                                    header.getContext()
                                  )}
                            </TableHead>
                          ))}
                        </TableRow>
                      ))}
                    </TableHeader>
                    <TableBody>
                      <AnimatePresence mode="popLayout">
                        {table.getRowModel().rows.map((row, index) => (
                          <motion.tr
                            key={row.id}
                            initial={{ opacity: 0, y: 10 }}
                            animate={{ opacity: 1, y: 0 }}
                            transition={{ duration: 0.2, delay: index * 0.05 }}
                            className="group hover:bg-muted/30 h-14 border-b last:border-0"
                          >
                            {row.getVisibleCells().map((cell) => (
                              <TableCell key={cell.id} className="px-6">
                                {flexRender(
                                  cell.column.columnDef.cell,
                                  cell.getContext()
                                )}
                              </TableCell>
                            ))}
                          </motion.tr>
                        ))}
                      </AnimatePresence>
                    </TableBody>
                  </Table>
                </div>

                {/* Advanced Pagination UI */}
                <div className="flex items-center justify-between px-6 py-4 bg-muted/10 border-t">
                  <div className="text-sm text-muted-foreground font-medium">
                    Showing <span className="text-foreground">{table.getState().pagination.pageIndex * table.getState().pagination.pageSize + 1}</span> to <span className="text-foreground">{Math.min((table.getState().pagination.pageIndex + 1) * table.getState().pagination.pageSize, filteredData.length)}</span> of <span className="text-foreground font-bold">{filteredData.length}</span> records
                  </div>
                  
                  <div className="flex items-center gap-6">
                    <div className="flex items-center gap-2">
                      <p className="text-xs font-medium text-muted-foreground mr-1">Rows per page</p>
                      <Select
                        value={`${table.getState().pagination.pageSize}`}
                        onValueChange={(value) => table.setPageSize(Number(value))}
                      >
                        <SelectTrigger className="h-8 w-[70px] bg-background">
                          <SelectValue placeholder={table.getState().pagination.pageSize} />
                        </SelectTrigger>
                        <SelectContent side="top">
                          {[5, 10, 20, 30, 40, 50].map((pageSize) => (
                            <SelectItem key={pageSize} value={`${pageSize}`}>
                              {pageSize}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>

                    <div className="flex items-center gap-1.5">
                      <Button
                        variant="outline"
                        className="hidden h-8 w-8 p-0 lg:flex"
                        onClick={() => table.setPageIndex(0)}
                        disabled={!table.getCanPreviousPage()}
                      >
                        <ChevronsLeft className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="outline"
                        className="h-8 w-8 p-0"
                        onClick={() => table.previousPage()}
                        disabled={!table.getCanPreviousPage()}
                      >
                        <ChevronLeft className="h-4 w-4" />
                      </Button>
                      <div className="flex h-8 w-12 items-center justify-center text-sm font-bold bg-muted rounded-md border">
                        {table.getState().pagination.pageIndex + 1}
                      </div>
                      <Button
                        variant="outline"
                        className="h-8 w-8 p-0"
                        onClick={() => table.nextPage()}
                        disabled={!table.getCanNextPage()}
                      >
                        <ChevronRight className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="outline"
                        className="hidden h-8 w-8 p-0 lg:flex"
                        onClick={() => table.setPageIndex(table.getPageCount() - 1)}
                        disabled={!table.getCanNextPage()}
                      >
                        <ChevronsRight className="h-4 w-4" />
                      </Button>
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>
        </DialogContent>
      </Dialog>

      <PdfPreviewModal
        isOpen={previewOpen}
        onClose={() => setPreviewOpen(false)}
        title={reportType === "contributions" ? "Benefit Contributions Preview" : "Benefit Loans Preview"}
        pdfBlob={pdfBlob}
        fileName={`Benefit_${reportType}_${selectedMonth}_${employee?.user_lname}.pdf`}
      />
    </>
  );
}

"use client";

import * as React from "react";
import type { Department, Employee } from "../types";

import { toast } from "sonner";
import { CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { Label } from "@/components/ui/label";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import {
  Table,
  TableBody,
  TableCell,
  TableHeader,
  TableRow,
  TableHead,
} from "@/components/ui/table";
import SortableTableHead from "./SortableTableHead";
import PayslipHistoryModal from "./PayslipHistoryModal";
import BenefitHistoryModal from "./BenefitHistoryModal";
import { PayrollRecordsSkeleton } from "./PayrollRecordsSkeleton";

export default function EmployeesTab({
  loading,
  employees,
  departments,
  companyName,
}: {
  loading: boolean;
  employees: Employee[];
  departments: Department[];
  companyName: string;
}) {
  const [filterDept, setFilterDept] = React.useState<number | null>(null);
  const [searchTerm, setSearchTerm] = React.useState("");
  const [sortConfig, setSortConfig] = React.useState<{
    key: "id" | "fname" | "lname" | "department";
    direction: "asc" | "desc";
  }>({ key: "id", direction: "asc" });

  const [historyModalOpen, setHistoryModalOpen] = React.useState(false);
  const [benefitModalOpen, setBenefitModalOpen] = React.useState(false);
  const [selectedEmployee, setSelectedEmployee] = React.useState<Employee | null>(null);

  const handleViewBenefitsHistory = (emp: Employee) => {
    setSelectedEmployee(emp);
    setBenefitModalOpen(true);
  };

  const handleSort = (key: "id" | "fname" | "lname" | "department") => {
    setSortConfig((prev) =>
      prev.key === key && prev.direction === "asc"
        ? { key, direction: "desc" }
        : { key, direction: "asc" },
    );
  };

  // pagination
  const [currentPage, setCurrentPage] = React.useState(1);
  const [rowsPerPage, setRowsPerPage] = React.useState(5);

  const filteredEmployees = React.useMemo(() => {
    return employees
      .filter((emp) => {
        const fullName =
          `${emp.user_fname} ${emp.user_mname ?? ""} ${emp.user_lname}`.toLowerCase();
        const matchesDept = filterDept
          ? emp.user_department === filterDept
          : true;
        const matchesSearch =
          emp.user_id.toString().includes(searchTerm.toLowerCase()) ||
          fullName.includes(searchTerm.toLowerCase());
        return matchesDept && matchesSearch;
      })
      .sort((a, b) => {
        let aVal: any, bVal: any;
        switch (sortConfig.key) {
          case "id":
            aVal = a.user_id;
            bVal = b.user_id;
            break;
          case "fname":
            aVal = a.user_fname;
            bVal = b.user_fname;
            break;
          case "lname":
            aVal = a.user_lname;
            bVal = b.user_lname;
            break;
          case "department":
            aVal =
              departments.find((d) => d.department_id === a.user_department)
                ?.department_name ?? "";
            bVal =
              departments.find((d) => d.department_id === b.user_department)
                ?.department_name ?? "";
            break;
        }
        if (typeof aVal === "string") {
          const cmp = aVal.localeCompare(bVal);
          return sortConfig.direction === "asc" ? cmp : -cmp;
        }
        return sortConfig.direction === "asc" ? aVal - bVal : bVal - aVal;
      });
  }, [employees, departments, filterDept, searchTerm, sortConfig]);

  const totalPages = Math.ceil(filteredEmployees.length / rowsPerPage);
  const paginatedEmployees = filteredEmployees.slice(
    (currentPage - 1) * rowsPerPage,
    currentPage * rowsPerPage,
  );

  const handleRowsPerPageChange = (e: React.ChangeEvent<HTMLSelectElement>) => {
    setRowsPerPage(parseInt(e.target.value));
    setCurrentPage(1);
  };

  const getPageButtons = () => {
    const buttons: (number | string)[] = [];
    let start = Math.max(1, currentPage - 2);
    const end = Math.min(totalPages, start + 4);
    if (end - start < 4) start = Math.max(1, end - 4);

    if (start > 1) {
      buttons.push(1);
      if (start > 2) buttons.push("...");
    }
    for (let i = start; i <= end; i++) buttons.push(i);
    if (end < totalPages) {
      if (end < totalPages - 1) buttons.push("...");
      buttons.push(totalPages);
    }
    return buttons;
  };

  return (
    <div className="space-y-6">
      <CardHeader className="px-0">
        <CardTitle>Employee List</CardTitle>
      </CardHeader>

      {/* Filters */}
      <div className="grid grid-cols-1 md:grid-cols-3 gap-4 items-end">
        <div className="space-y-2">
          <Label className="text-sm font-medium">Department</Label>
          <select
            className="border px-2 py-1 rounded bg-white dark:bg-gray-800 w-full"
            value={filterDept ?? ""}
            onChange={(e) =>
              setFilterDept(e.target.value ? parseInt(e.target.value) : null)
            }
          >
            <option value="">All Departments</option>
            {departments.map((dept) => (
              <option key={dept.department_id} value={dept.department_id}>
                {dept.department_name}
              </option>
            ))}
          </select>
        </div>

        <div className="space-y-2">
          <Label className="text-sm font-medium">Search employee</Label>
          <input
            type="text"
            placeholder="Type name..."
            value={searchTerm}
            onChange={(e) => setSearchTerm(e.target.value)}
            className="border px-2 py-1 rounded bg-white dark:bg-gray-800 w-full"
          />
        </div>

        <div className="space-y-2">
          <Label className="text-sm font-medium">Sort by</Label>
          <Select
            value={sortConfig.key}
            onValueChange={(value: any) =>
              setSortConfig({ key: value, direction: "asc" })
            }
          >
            <SelectTrigger className="w-full">
              <SelectValue />
            </SelectTrigger>
            <SelectContent>
              <SelectItem value="id">ID</SelectItem>
              <SelectItem value="fname">First Name</SelectItem>
              <SelectItem value="lname">Last Name</SelectItem>
              <SelectItem value="department">Department</SelectItem>
            </SelectContent>
          </Select>
        </div>
      </div>

      {/* Table */}
      <div className="overflow-x-auto">
        <Table>
          <TableHeader>
            <TableRow>
              <SortableTableHead
                label="Employee ID"
                sortKey="id"
                currentSort={sortConfig}
                onSort={handleSort as any}
                className="w-1/4"
              />
              <SortableTableHead
                label="Name"
                sortKey="fname"
                currentSort={sortConfig}
                onSort={handleSort as any}
                className="w-1/4"
              />
              <SortableTableHead
                label="Department"
                sortKey="department"
                currentSort={sortConfig}
                onSort={handleSort as any}
                className="w-1/4"
              />
              <TableHead className="w-1/4">Action</TableHead>
            </TableRow>
          </TableHeader>

          <TableBody>
            {loading ? (
              <PayrollRecordsSkeleton type="employees" />
            ) : paginatedEmployees.length === 0 ? (
              <TableRow>
                <TableCell colSpan={4} className="text-center py-10 text-muted-foreground">
                  No employees found matching the filters.
                </TableCell>
              </TableRow>
            ) : (
              paginatedEmployees.map((emp) => {
                const deptName =
                  departments.find((d) => d.department_id === emp.user_department)
                    ?.department_name ?? "N/A";

                return (
                  <TableRow key={emp.user_id} className="border-b">
                    <TableCell>{emp.user_id}</TableCell>
                    <TableCell>
                      {`${emp.user_fname} ${emp.user_mname ?? ""} ${emp.user_lname}`}
                    </TableCell>
                    <TableCell>{deptName}</TableCell>
                    <TableCell className="flex gap-2 justify-end">
                      <Button
                        size="sm"
                        className="bg-blue-600 hover:bg-blue-700 text-white"
                        onClick={() => {
                          setSelectedEmployee(emp);
                          setHistoryModalOpen(true);
                        }}
                      >
                        View Payslip History
                      </Button>
                      <Button
                        size="sm"
                        className="bg-blue-600 hover:bg-blue-700 text-white"
                        onClick={() => handleViewBenefitsHistory(emp)}
                      >
                        View Benefits History
                      </Button>
                    </TableCell>
                  </TableRow>
                );
              })
            )}
          </TableBody>
        </Table>
      </div>

      <PayslipHistoryModal 
        isOpen={historyModalOpen} 
        onClose={() => {
          setHistoryModalOpen(false);
          setSelectedEmployee(null);
        }}
        employee={selectedEmployee}
        companyName={companyName}
      />

      <BenefitHistoryModal
        isOpen={benefitModalOpen}
        onClose={() => {
          setBenefitModalOpen(false);
          setSelectedEmployee(null);
        }}
        employee={selectedEmployee}
      />

      {/* Pagination */}
      <div className="flex justify-between items-center mt-4">
        <div>
          Rows per page:{" "}
          <select
            className="border px-2 py-1 rounded bg-white dark:bg-gray-800"
            value={rowsPerPage}
            onChange={handleRowsPerPageChange}
          >
            <option value={5}>5</option>
            <option value={10}>10</option>
            <option value={20}>20</option>
          </select>
        </div>

        <div className="flex gap-2 flex-wrap">
          <Button
            size="sm"
            disabled={currentPage === 1}
            onClick={() => setCurrentPage((p) => p - 1)}
            className="bg-blue-600 hover:bg-blue-700 text-white disabled:opacity-50"
          >
            Prev
          </Button>

          {getPageButtons().map((page, idx) =>
            page === "..." ? (
              <span key={idx} className="px-2 py-1">
                ...
              </span>
            ) : (
              <Button
                key={idx}
                size="sm"
                variant={currentPage === page ? "default" : "outline"}
                onClick={() => setCurrentPage(Number(page))}
                className={
                  currentPage === page
                    ? "bg-blue-600 hover:bg-blue-700 text-white"
                    : "border-blue-600 text-blue-600 hover:bg-blue-50"
                }
              >
                {page}
              </Button>
            ),
          )}

          <Button
            size="sm"
            disabled={currentPage === totalPages || totalPages === 0}
            onClick={() => setCurrentPage((p) => p + 1)}
            className="bg-blue-600 hover:bg-blue-700 text-white disabled:opacity-50"
          >
            Next
          </Button>
        </div>
      </div>
    </div>
  );
}

"use client";

import * as React from "react";
import { toast } from "sonner";
import { 
  Dialog, 
  DialogContent, 
  DialogHeader, 
  DialogTitle,
  DialogFooter
} from "@/components/ui/dialog";
import { Button } from "@/components/ui/button";
import { 
  Table, 
  TableBody, 
  TableCell, 
  TableHead, 
  TableHeader, 
  TableRow 
} from "@/components/ui/table";
import { 
  Loader2, 
  Eye, 
  FileDown, 
  History,
  Search,
  ChevronLeft,
  ChevronRight,
  ChevronsLeft,
  ChevronsRight,
  ArrowUpDown
} from "lucide-react";
import { formatPHP } from "../../payroll-run/utils/compute";
import { buildPayslipsPdf } from "../../payroll-run/utils/payslipPdf";
import {
  ColumnDef,
  flexRender,
  getCoreRowModel,
  getPaginationRowModel,
  getSortedRowModel,
  SortingState,
  useReactTable,
} from "@tanstack/react-table";
import { motion, AnimatePresence } from "framer-motion";
import { Input } from "@/components/ui/input";
import { Select, SelectContent, SelectItem, SelectTrigger, SelectValue } from "@/components/ui/select";
import { cn } from "@/lib/utils";

type PayslipHistoryModalProps = {
  isOpen: boolean;
  onClose: () => void;
  employee: {
    user_id: number;
    user_fname: string;
    user_mname: string | null;
    user_lname: string;
  } | null;
  companyName: string;
};

export default function PayslipHistoryModal({
  isOpen,
  onClose,
  employee,
  companyName: passedCompanyName,
}: PayslipHistoryModalProps) {
  const [loading, setLoading] = React.useState(false);
  const [records, setRecords] = React.useState<any[]>([]);
  const [previewOpen, setPreviewOpen] = React.useState(false);
  const [previewUrl, setPreviewUrl] = React.useState<string | null>(null);
  const [isGenerating, setIsGenerating] = React.useState(false);
  const [searchTerm, setSearchTerm] = React.useState("");
  const [sorting, setSorting] = React.useState<SortingState>([]);
  const [companyName, setCompanyName] = React.useState<string>(passedCompanyName);
  
  React.useEffect(() => {
    if (passedCompanyName) setCompanyName(passedCompanyName);
  }, [passedCompanyName]);

  React.useEffect(() => {
    if (isOpen && employee?.user_id) {
      setSearchTerm("");
      fetchHistory();
    } else {
      setRecords([]);
    }
  }, [isOpen, employee, passedCompanyName]);

  React.useEffect(() => {
    return () => {
      if (previewUrl) URL.revokeObjectURL(previewUrl);
    };
  }, [previewUrl]);

  const fetchHistory = async () => {
    if (!employee?.user_id) return;
    setLoading(true);
    try {
      const sp = new URLSearchParams();
      sp.set("resource", "payroll_run_employee");
      sp.set("fields", "*,payroll_run_id.payroll_ref_no,payroll_run_id.posted_at");
      sp.set("filter[user_id][_eq]", String(employee.user_id));
      sp.set("sort", "-cutoff_end");
      sp.set("limit", "1000");
      
      const res = await fetch(`/api/payroll-run?${sp.toString()}`);
      const json = await res.json();
      
      if (!res.ok) throw new Error(json?.error || "Failed to fetch history");
      
      setRecords(Array.isArray(json?.data) ? json.data : []);
      if (json.meta?.companyName) {
        setCompanyName(json.meta.companyName);
      }
    } catch (e: any) {
      toast.error(e.message || "Failed to load history");
    } finally {
      setLoading(false);
    }
  };

  const filteredData = React.useMemo(() => {
    if (!searchTerm.trim()) return records;
    const s = searchTerm.toLowerCase();
    return records.filter((r) => {
      const label = String(r.cutoff_label || "").toLowerCase();
      const start = String(r.cutoff_start || "").toLowerCase();
      const end = String(r.cutoff_end || "").toLowerCase();
      const ref = String(r.payroll_run_id?.payroll_ref_no || r.payroll_ref_no || "").toLowerCase();
      return label.includes(s) || start.includes(s) || end.includes(s) || ref.includes(s);
    });
  }, [records, searchTerm]);

  const handlePreview = async (record: any) => {
    setIsGenerating(true);
    try {
      const payrollRefNo = record.payroll_run_id?.payroll_ref_no || record.payroll_ref_no;
      const postedAt = record.payroll_run_id?.posted_at || record.posted_at;
      const payrollPeriodLabel = record.cutoff_label || `${record.cutoff_start} to ${record.cutoff_end}`;
      
      const doc = await buildPayslipsPdf({
        rows: [record],
        payrollPeriodLabel,
        pageSize: "LEGAL",
        payrollRefNo,
        postedAt,
        companyName: (companyName || "").toUpperCase(),
      });

      const blob = doc.output("blob");
      if (previewUrl) URL.revokeObjectURL(previewUrl);
      const url = URL.createObjectURL(blob);
      setPreviewUrl(url);
      setPreviewOpen(true);
    } catch (e: any) {
      toast.error(e.message || "Failed to generate preview");
    } finally {
      setIsGenerating(false);
    }
  };

  const columns = React.useMemo<ColumnDef<any>[]>(() => [
    {
      accessorKey: "cutoff_period",
      header: ({ column }) => (
        <Button variant="ghost" onClick={() => column.toggleSorting(column.getIsSorted() === "asc")} className="hover:bg-transparent p-0 font-bold uppercase text-xs">
          Cutoff Period
          <ArrowUpDown className="ml-2 h-3 w-3" />
        </Button>
      ),
      cell: ({ row }) => {
        const r = row.original;
        return (
          <div className="font-medium text-base text-foreground">
            {r.cutoff_label || (
              <span className="text-sm text-muted-foreground">
                {r.cutoff_start} to {r.cutoff_end}
              </span>
            )}
          </div>
        );
      },
    },
    {
      accessorKey: "cutoff_type",
      header: "Type",
      cell: ({ row }) => {
        const type = row.getValue("cutoff_type") as string;
        return (
          <span className={cn(
            "px-2.5 py-1 rounded-full text-xs font-semibold border",
            type === "FIRST" 
              ? "bg-slate-100/50 text-slate-700 border-slate-200 dark:bg-slate-900/30 dark:text-slate-400 dark:border-slate-800"
              : "bg-indigo-50 text-indigo-700 border-indigo-100 dark:bg-indigo-900/30 dark:text-indigo-400 dark:border-indigo-800"
          )}>
            {type === "FIRST" ? "First Period" : "Second Period"}
          </span>
        );
      },
    },
    {
      accessorKey: "net_pay",
      header: ({ column }) => (
        <div className="text-right">
          <Button variant="ghost" onClick={() => column.toggleSorting(column.getIsSorted() === "asc")} className="hover:bg-transparent p-0 font-bold uppercase text-xs ml-auto">
            Net Pay
            <ArrowUpDown className="ml-2 h-3 w-3" />
          </Button>
        </div>
      ),
      cell: ({ row }) => {
        const amount = Number(row.getValue("net_pay") || 0);
        return (
          <div className="text-right font-mono text-lg text-blue-600 dark:text-blue-400 font-bold">
            {formatPHP(amount)}
          </div>
        );
      },
    },
    {
      id: "actions",
      header: () => <div className="text-center font-bold uppercase text-xs">Action</div>,
      cell: ({ row }) => (
        <div className="text-center">
          <Button
            variant="outline"
            className="gap-2 h-9 px-4 text-sm font-semibold shadow-sm rounded-lg hover:bg-blue-50 hover:text-blue-600 hover:border-blue-200 transition-all"
            onClick={() => handlePreview(row.original)}
            disabled={isGenerating}
          >
            <Eye className="h-4 w-4" />
            Preview
          </Button>
        </div>
      ),
    },
  ], [isGenerating, companyName, previewUrl]);

  const table = useReactTable({
    data: filteredData,
    columns,
    state: { sorting },
    onSortingChange: setSorting,
    getCoreRowModel: getCoreRowModel(),
    getPaginationRowModel: getPaginationRowModel(),
    getSortedRowModel: getSortedRowModel(),
    initialState: {
      pagination: {
        pageSize: 7,
      },
    },
  });

  return (
    <>
      <Dialog open={isOpen} onOpenChange={(open) => !open && onClose()}>
        <DialogContent className="w-[75vw] sm:max-w-none h-[80vh] flex flex-col p-0 overflow-hidden bg-background border-none shadow-2xl">
          {/* Premium Header with Gradient */}
          <div className="relative p-8 pb-6 bg-gradient-to-br from-indigo-50/50 via-background to-background dark:from-indigo-950/20 dark:via-background dark:to-background border-b shadow-sm">
            <div className="flex items-center justify-between">
              <div className="space-y-1">
                <DialogTitle className="flex items-center gap-2 text-2xl font-bold tracking-tight text-indigo-600 dark:text-indigo-400">
                  <div className="p-2 rounded-lg bg-indigo-500/10">
                    <History className="h-6 w-6" />
                  </div>
                  Payslip History
                </DialogTitle>
                <p className="text-muted-foreground ml-11 text-sm font-medium">
                  Viewing electronic payslips for <span className="text-foreground">{(employee?.user_fname || "")} {(employee?.user_lname || "")}</span>
                </p>
              </div>
              
              <div className="flex items-center gap-3">
                <div className="relative w-80">
                  <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-muted-foreground/50" />
                  <Input
                    placeholder="Search by period, date, or reference..."
                    value={searchTerm}
                    onChange={(e) => setSearchTerm(e.target.value)}
                    className="pl-10 h-10 bg-background/50 border-muted-foreground/10 focus-visible:ring-indigo-500 rounded-lg shadow-sm"
                  />
                </div>
              </div>
            </div>
          </div>

          {/* Table Content with Animations */}
          <div className="flex-1 overflow-auto p-8 pt-4">
            {loading ? (
              <div className="flex flex-col items-center justify-center h-full gap-4 text-muted-foreground">
                <div className="relative">
                  <div className="absolute inset-0 rounded-full blur-xl bg-indigo-500/20 animate-pulse" />
                  <Loader2 className="h-10 w-10 animate-spin text-indigo-500 relative" />
                </div>
                <p className="font-medium animate-pulse">Retriving payroll summary...</p>
              </div>
            ) : filteredData.length === 0 ? (
              <div className="h-full flex flex-col items-center justify-center text-muted-foreground border-2 border-dashed rounded-2xl bg-muted/5 transition-all group hover:bg-muted/10">
                <div className="p-4 rounded-full bg-muted group-hover:scale-110 transition-transform mb-4">
                  <Eye className="h-8 w-8 opacity-20" />
                </div>
                <p className="font-medium">{searchTerm ? "No results found matching your search." : "No payslip history recorded."}</p>
                {searchTerm && (
                  <Button 
                    variant="link" 
                    className="mt-1 text-indigo-500"
                    onClick={() => setSearchTerm("")}
                  >
                    Clear search query
                  </Button>
                )}
              </div>
            ) : (
              <div className="rounded-xl border bg-card shadow-sm overflow-hidden flex flex-col h-full">
                <div className="flex-1 overflow-auto">
                  <Table>
                    <TableHeader className="bg-muted/30 sticky top-0 z-10">
                      {table.getHeaderGroups().map((headerGroup) => (
                        <TableRow key={headerGroup.id} className="hover:bg-transparent border-none">
                          {headerGroup.headers.map((header) => (
                            <TableHead key={header.id} className="px-6 h-12">
                              {header.isPlaceholder
                                ? null
                                : flexRender(
                                    header.column.columnDef.header,
                                    header.getContext()
                                  )}
                            </TableHead>
                          ))}
                        </TableRow>
                      ))}
                    </TableHeader>
                    <TableBody>
                      <AnimatePresence mode="popLayout">
                        {table.getRowModel().rows.map((row, index) => (
                          <motion.tr
                            key={row.id}
                            initial={{ opacity: 0, y: 10 }}
                            animate={{ opacity: 1, y: 0 }}
                            transition={{ duration: 0.2, delay: index * 0.05 }}
                            className="group hover:bg-muted/30 h-14 border-b last:border-0"
                          >
                            {row.getVisibleCells().map((cell) => (
                              <TableCell key={cell.id} className="px-6">
                                {flexRender(
                                  cell.column.columnDef.cell,
                                  cell.getContext()
                                )}
                              </TableCell>
                            ))}
                          </motion.tr>
                        ))}
                      </AnimatePresence>
                    </TableBody>
                  </Table>
                </div>

                {/* Advanced Pagination UI */}
                <div className="flex items-center justify-between px-6 py-4 bg-muted/10 border-t">
                  <div className="text-sm text-muted-foreground font-medium">
                    Showing <span className="text-foreground">{table.getState().pagination.pageIndex * table.getState().pagination.pageSize + 1}</span> to <span className="text-foreground">{Math.min((table.getState().pagination.pageIndex + 1) * table.getState().pagination.pageSize, filteredData.length)}</span> of <span className="text-foreground font-bold">{filteredData.length}</span> payslips
                  </div>
                  
                  <div className="flex items-center gap-6">
                    <div className="flex items-center gap-2">
                      <p className="text-xs font-medium text-muted-foreground">Rows per page</p>
                      <Select
                        value={`${table.getState().pagination.pageSize}`}
                        onValueChange={(value) => table.setPageSize(Number(value))}
                      >
                        <SelectTrigger className="h-8 w-[70px] bg-background">
                          <SelectValue placeholder={table.getState().pagination.pageSize} />
                        </SelectTrigger>
                        <SelectContent side="top">
                          {[5, 10, 20, 50].map((pageSize) => (
                            <SelectItem key={pageSize} value={`${pageSize}`}>
                              {pageSize}
                            </SelectItem>
                          ))}
                        </SelectContent>
                      </Select>
                    </div>

                    <div className="flex items-center gap-1.5">
                      <Button
                        variant="ghost"
                        className="h-8 w-8 p-0"
                        onClick={() => table.previousPage()}
                        disabled={!table.getCanPreviousPage()}
                      >
                        <ChevronLeft className="h-4 w-4" />
                      </Button>
                      <div className="flex h-8 w-10 items-center justify-center text-sm font-bold bg-background rounded-lg border shadow-sm">
                        {table.getState().pagination.pageIndex + 1}
                      </div>
                      <Button
                        variant="ghost"
                        className="h-8 w-8 p-0"
                        onClick={() => table.nextPage()}
                        disabled={!table.getCanNextPage()}
                      >
                        <ChevronRight className="h-4 w-4" />
                      </Button>
                    </div>
                  </div>
                </div>
              </div>
            )}
          </div>

        </DialogContent>
      </Dialog>

      <Dialog 
        open={previewOpen} 
        onOpenChange={(open) => {
          setPreviewOpen(open);
          if (!open && previewUrl) {
            URL.revokeObjectURL(previewUrl);
            setPreviewUrl(null);
          }
        }}
      >
        <DialogContent className="w-full max-w-[95vw] sm:max-w-7xl h-[90vh] flex flex-col p-0 overflow-hidden rounded-2xl border-none shadow-2xl">
          <DialogHeader className="pl-8 pr-12 py-6 border-b bg-background">
            <div className="flex items-center justify-between gap-4">
              <div className="space-y-1">
                <DialogTitle className="text-xl font-bold">Payslip Preview</DialogTitle>
                <div className="text-sm text-muted-foreground font-medium">
                  Reviewing electronic statement for the selected period.
                </div>
              </div>
              <div className="flex items-center gap-3">
                {previewUrl && (
                  <Button variant="default" size="default" asChild className="rounded-lg shadow-lg bg-indigo-600 hover:bg-indigo-700">
                    <a href={previewUrl} download={`Payslip-${employee?.user_fname}-${employee?.user_lname}.pdf`}>
                      <FileDown className="mr-2 h-4 w-4" />
                      Download PDF
                    </a>
                  </Button>
                )}
                <Button variant="ghost" onClick={() => setPreviewOpen(false)} className="rounded-lg">
                  Close Preview
                </Button>
              </div>
            </div>
          </DialogHeader>
          <div className="flex-1 bg-muted/40 w-full h-full relative p-4">
            <div className="w-full h-full rounded-xl overflow-hidden border shadow-inner bg-background">
              {previewUrl ? (
                <iframe
                  title="Payslip PDF Preview"
                  src={`${previewUrl}#toolbar=0&view=FitH`}
                  className="w-full h-full"
                />
              ) : (
                <div className="h-full flex flex-col items-center justify-center text-sm text-muted-foreground gap-3">
                  <Loader2 className="h-6 w-6 animate-spin text-indigo-400" />
                  Generating document preview...
                </div>
              )}
            </div>
          </div>
        </DialogContent>
      </Dialog>
    </>
  );
}

// modules/payroll-records/components/TapSheetTab.tsx
// modules/payroll-records/components/TapSheetTab.tsx
"use client";

import * as React from "react";
import { toast } from "sonner";
import { FileDown, Loader2, ArrowUpDown, Eye } from "lucide-react";

import type {
  CutoffHistoryRow,
  Department,
  Employee,
  TapSortKey,
  TapSheetRow,
} from "../types";
import { fetchTapSheet } from "../providers/payrollRecordsApi";
import {
  uniqCutoffs,
  parseCutoffValue,
  buildCutoffLabel,
} from "../utils/cutoff";
import {
  buildTapSheetRows,
  dedupeByUserKeepLatestRun,
} from "../utils/tapSheet";
import { toNumberSafe } from "../utils/money";
import { buildTapSheetPdf } from "../utils/tapSheetPdf";
import { buildPayslipsPdf } from "../../payroll-run/utils/payslipPdf";
import { buildPayrollSummaryPdf } from "../utils/payrollSummaryPdf";

import { CardHeader, CardTitle } from "@/components/ui/card";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectTrigger,
  SelectValue,
  SelectContent,
  SelectItem,
} from "@/components/ui/select";
import {
  Table,
  TableHeader,
  TableRow,
  TableHead,
  TableBody,
  TableCell,
} from "@/components/ui/table";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
} from "@/components/ui/dialog";

import { PayrollRecordsSkeleton } from "./PayrollRecordsSkeleton";

/** Handles 1/0, true/false, "1"/"0", and Directus buffer-ish { data: [1] } */
function isTruthyFlag(v: unknown): boolean {
  if (v === null || v === undefined) return false;

  if (typeof v === "object") {
    const anyV = v as any;
    const d0 = anyV?.data?.[0];
    if (d0 === 1 || d0 === "1" || d0 === true) return true;
    if (d0 === 0 || d0 === "0" || d0 === false || d0 == null) return false;
  }

  if (typeof v === "boolean") return v;
  if (typeof v === "number") return v === 1;
  if (typeof v === "string")
    return v.trim() === "1" || v.trim().toLowerCase() === "true";

  return false;
}

/** Format number ONLY (no currency symbol) */
function formatAmountOnly(v: any) {
  const n = Math.abs(toNumberSafe(v));
  try {
    return n.toLocaleString("en-PH", {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });
  } catch {
    return n.toLocaleString(undefined, {
      minimumFractionDigits: 2,
      maximumFractionDigits: 2,
    });
  }
}

/** 
 * Show whole numbers without decimals (12), 
 * but fractionals with up to 2 (12.5) 
 */
function formatSmartDecimal(v: any) {
  const n = Math.abs(toNumberSafe(v));
  if (Number.isInteger(n)) return n.toString();
  try {
    return n.toLocaleString("en-PH", {
      minimumFractionDigits: 0,
      maximumFractionDigits: 2,
    });
  } catch {
    return n.toLocaleString(undefined, {
      minimumFractionDigits: 0,
      maximumFractionDigits: 2,
    });
  }
}

/** UI Peso format: single symbol, ABS */
function peso(v: any) {
  return `₱ ${formatAmountOnly(v)}`;
}

export default function TapSheetTab({
  loading: isInitialLoading,
  employees,
  departments,
  cutoffs,
  selectedCutoff,
  setSelectedCutoff,
  deptId,
  setDeptId,
  companyName: passedCompanyName,
}: {
  loading: boolean;
  employees: Employee[];
  departments: Department[];
  cutoffs: CutoffHistoryRow[];
  selectedCutoff: string;
  setSelectedCutoff: (v: string) => void;
  deptId: number | null;
  setDeptId: (v: number | null) => void;
  companyName: string;
}) {
  const uniqueCutoffs = React.useMemo(() => uniqCutoffs(cutoffs), [cutoffs]);

  const [search, setSearch] = React.useState("");
  const [sortKey, setSortKey] = React.useState<TapSortKey>("name");
  const [sortDir, setSortDir] = React.useState<"asc" | "desc">("asc");

  const [loading, setLoading] = React.useState(false);
  const [exporting, setExporting] = React.useState(false);
  const [rowsRaw, setRowsRaw] = React.useState<any[]>([]);
  const [companyName, setCompanyName] = React.useState<string>(passedCompanyName || "");

  React.useEffect(() => {
    if (passedCompanyName) setCompanyName(passedCompanyName);
  }, [passedCompanyName]);

  const [previewOpen, setPreviewOpen] = React.useState(false);
  const [previewUrl, setPreviewUrl] = React.useState<string | null>(null);
  const [previewFilename, setPreviewFilename] = React.useState<string>("");
  const [pdfFilter, setPdfFilter] = React.useState<"ALL" | "BANK" | "CASH">("ALL");

  React.useEffect(() => {
    if (!selectedCutoff && uniqueCutoffs.length) {
      setSelectedCutoff(
        `${uniqueCutoffs[0].start_date}|${uniqueCutoffs[0].end_date}`,
      );
    }
  }, [selectedCutoff, uniqueCutoffs]);

  const departmentName = React.useMemo(() => {
    if (!deptId || deptId === -1) return "";
    return (
      departments.find((d) => d.department_id === deptId)?.department_name ?? ""
    );
  }, [deptId, departments]);

  const cutoff = React.useMemo(
    () => parseCutoffValue(selectedCutoff),
    [selectedCutoff],
  );

  React.useEffect(() => {
    const run = async () => {
      if (!cutoff?.start || !cutoff?.end) return;
      if (deptId !== -1 && !departmentName) return;

      try {
        setLoading(true);
        const res = await fetchTapSheet({
          cutoffStart: cutoff.start,
          cutoffEnd: cutoff.end,
          departmentName,
        });

        // ✅ safety-net filter (backend should already filter, but keep this)
        const filtered = res.data.filter(
          (r: any) => !isTruthyFlag(r?.on_hold),
        );
        setRowsRaw(filtered);
        if (res.meta?.companyName) {
          setCompanyName(res.meta.companyName);
        }
      } catch (e) {
        console.error(e);
        toast.error("Failed to load Top Sheet data.");
        setRowsRaw([]);
      } finally {
        setLoading(false);
      }
    };
    run();
  }, [cutoff?.start, cutoff?.end, departmentName]);

  const tapRows: TapSheetRow[] = React.useMemo(() => {
    if (!cutoff?.start || !cutoff?.end) return [];
    if (deptId !== -1 && !departmentName) return [];

    // ✅ safety-net again
    const safeRaw = (rowsRaw as any[]).filter(
      (r) => !isTruthyFlag((r as any)?.on_hold),
    );

    const deduped = dedupeByUserKeepLatestRun(safeRaw as any);

    const masters = employees.map((e) => ({
      user_id: e.user_id,
      user_fname: e.user_fname,
      user_mname: e.user_mname,
      user_lname: e.user_lname,
    }));

    const built = buildTapSheetRows(deduped as any, masters);

    const q = search.trim().toLowerCase();
    const filtered = q
      ? built.filter((r) => r.name_display.toLowerCase().includes(q))
      : built;

    const sorted = [...filtered].sort((a, b) => {
      let cmp = 0;
      switch (sortKey) {
        case "name":
          cmp = a.name_sort_key.localeCompare(b.name_sort_key);
          break;
        case "gross":
          cmp = a.gross_pay - b.gross_pay;
          break;
        case "adds":
          cmp = a.total_additions - b.total_additions;
          break;
        case "deds":
          cmp = a.total_deductions - b.total_deductions;
          break;
        case "net":
          cmp = a.net_pay - b.net_pay;
          break;
      }
      return sortDir === "asc" ? cmp : -cmp;
    });

    return sorted;
  }, [
    rowsRaw,
    employees,
    cutoff?.start,
    cutoff?.end,
    departmentName,
    search,
    sortKey,
    sortDir,
  ]);

  const totals = React.useMemo(() => {
    return tapRows.reduce(
      (acc, r) => {
        acc.gross += Math.abs(toNumberSafe(r.gross_pay));
        acc.adds += Math.abs(toNumberSafe(r.total_additions));
        acc.deds += Math.abs(toNumberSafe(r.total_deductions));
        acc.net += Math.abs(toNumberSafe(r.net_pay));
        return acc;
      },
      { gross: 0, adds: 0, deds: 0, net: 0 },
    );
  }, [tapRows]);

  React.useEffect(() => {
    return () => {
      if (previewUrl) URL.revokeObjectURL(previewUrl);
    };
  }, [previewUrl]);

  const buildSafeFilename = (filter: string) => {
    const safeDept = (deptId === -1 ? "all_depts" : departmentName || "dept").replace(/[^\w\-]+/g, "_");
    const start = cutoff?.start ?? "start";
    const end = cutoff?.end ?? "end";
    return `top-sheet_${filter}_${safeDept}_${start}_${end}.pdf`;
  };

  const generatePdfBlob = async (filter: "ALL" | "BANK" | "CASH") => {
    if (!cutoff?.start || !cutoff?.end) return null;
    if (deptId !== -1 && !departmentName) return null;

    let filteredRows = tapRows;
    if (filter === "BANK") {
      filteredRows = tapRows.filter(r => r.payment_type === "BANK");
    } else if (filter === "CASH") {
      filteredRows = tapRows.filter(r => r.payment_type === "CASH");
    }

    // Recalculate totals for PDF
    const pdfTotals = filteredRows.reduce(
      (acc, r) => {
        acc.gross += Math.abs(toNumberSafe(r.gross_pay));
        acc.adds += Math.abs(toNumberSafe(r.total_additions));
        acc.deds += Math.abs(toNumberSafe(r.total_deductions));
        acc.net += Math.abs(toNumberSafe(r.net_pay));
        return acc;
      },
      { gross: 0, adds: 0, deds: 0, net: 0 }
    );

    const doc = await buildTapSheetPdf({
      companyName,
      departmentName,
      cutoffStart: cutoff.start,
      cutoffEnd: cutoff.end,
      rows: filteredRows,
      totals: pdfTotals,
      filterType: filter, // Pass the filter type
      payrollRefNo: filteredRows.find(r => r.payroll_ref_no)?.payroll_ref_no,
      postedAt: filteredRows.find(r => r.posted_at)?.posted_at,
    });
    return doc.output("blob");
  };

  const onDownloadAllPayslips = async () => {
    if (!tapRows.length) return toast.error("No payslips to download.");
    
    setExporting(true);
    try {
      // ✅ We use all tapRows (they are already sorted by name_sort_key in useMemo)
      // Map TapSheetRows back to the shape expected by buildPayslipsPdf if needed,
      // but buildPayslipsPdf just needs 'rows' which are objects.
      // However, tapRows are already computed. If buildPayslipsPdf needs raw rows,
      // we might need to pass the raw objects.
      // Looking at payslipPdf.ts, it uses 'any[]' and deep-dives into properties.
      // tapRows has properties like net_pay, gross_pay, etc.
      
      const doc = await buildPayslipsPdf({
        rows: tapRows,
        payrollPeriodLabel: buildCutoffLabel(cutoff as any),
        pageSize: "LEGAL",
        companyName: (companyName || "").toUpperCase(),
      });
      
      doc.save(buildSafeFilename("all_payslips"));
      toast.success("Bulk payslips generated.");
    } catch (e: any) {
      console.error(e);
      toast.error("Failed to generate bulk payslips.");
    } finally {
      setExporting(false);
    }
  };

  const openPreview = async () => {
    if (!cutoff?.start || !cutoff?.end)
      return toast.error("Please select a cutoff date.");
    if (deptId !== -1 && !departmentName) return toast.error("Please select a department.");
    if (!tapRows.length) return toast.error("No Top Sheet rows to preview.");

    setPdfFilter("ALL");
    setPreviewOpen(true);
  };

  React.useEffect(() => {
    if (!previewOpen) return;
    
    let active = true;
    (async () => {
       setExporting(true);
       try {
         const blob = await generatePdfBlob(pdfFilter);
         if (!active) return;
         if (blob) {
            if (previewUrl) URL.revokeObjectURL(previewUrl);
            const url = URL.createObjectURL(blob);
            setPreviewUrl(url);
            setPreviewFilename(buildSafeFilename(pdfFilter));
         }
       } catch (e) {
         console.error(e);
         toast.error("Failed to generate PDF.");
       } finally {
         if (active) setExporting(false);
       }
    })();
    return () => { active = false; };
  // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [previewOpen, pdfFilter]);


  return (
    <div className="space-y-6">
      <CardHeader className="px-0 space-y-3">
        <div className="flex items-center justify-between gap-3 flex-wrap">
          <div className="flex flex-col gap-2">
            <h1 className="text-2xl font-bold">Payroll Records</h1>
            <p className="text-sm text-muted-foreground">
              Generate a final Top Sheet per department and cutoff.
            </p>
          </div>

          <div className="flex items-center gap-2">
            <Button
              onClick={onDownloadAllPayslips}
              disabled={loading || exporting || tapRows.length === 0}
              variant="outline"
