// modules/payroll-records/utils/payrollSummaryPdf.ts
import jsPDF from "jspdf";

type CompanySummary = {
  name: string;
  prevNet: number;
  currNet: number;
};

type DeptSummary = {
  name: string;
  bank: { prevEmp: number; currEmp: number; prevNet: number; currNet: number; add: number; rem: number };
  cash: { prevEmp: number; currEmp: number; prevNet: number; currNet: number; add: number; rem: number };
};

type RGB = { r: number; g: number; b: number };

export async function buildPayrollSummaryPdf(args: { data: any[]; meta: any }) {
  // ✅ Landscape + Legal (one page only)
  const doc = new jsPDF({ orientation: "landscape", unit: "pt", format: "legal" });
  const pageW = doc.internal.pageSize.getWidth();  // ~1008
  const pageH = doc.internal.pageSize.getHeight(); // ~612

  // Layout
  const M = 28;
  const innerW = pageW - M * 2;
  const footerH = 20;

  // Theme (blue-800)
  const BLUE_800: RGB = { r: 30, g: 64, b: 175 };
  const BLUE_900: RGB = { r: 30, g: 58, b: 138 };
  const BLUE_50: RGB = { r: 239, g: 246, b: 255 };
  const SLATE_900: RGB = { r: 15, g: 23, b: 42 };
  const SLATE_600: RGB = { r: 71, g: 85, b: 105 };
  const GRAY_200: RGB = { r: 226, g: 232, b: 240 };
  const GRAY_300: RGB = { r: 203, g: 213, b: 225 };
  const WHITE: RGB = { r: 255, g: 255, b: 255 };
  const ROW_ZEBRA: RGB = { r: 248, g: 250, b: 252 };

  const setFill = (c: RGB) => doc.setFillColor(c.r, c.g, c.b);
  const setDraw = (c: RGB) => doc.setDrawColor(c.r, c.g, c.b);
  const setText = (c: RGB) => doc.setTextColor(c.r, c.g, c.b);

  const safeStr = (v: any, fb = "") => {
    const s = String(v ?? "").trim();
    return s ? s : fb;
  };

  const fmtMoney = (n: number) =>
    (Number(n || 0) || 0).toLocaleString("en-PH", { minimumFractionDigits: 2, maximumFractionDigits: 2 });

  const fmtInt = (n: number) =>
    (Number(n || 0) || 0).toLocaleString("en-PH", { maximumFractionDigits: 0 });

  const fmtDate = (iso: string) => {
    if (!iso) return "—";
    const d = new Date(iso);
    if (isNaN(d.getTime())) return iso;
    return d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
  };

  const dashIfZero = (n: number) => (Number(n || 0) > 0 ? String(n) : "—");

  const ellipsize = (text: string, maxW: number) => {
    const raw = safeStr(text, "—");
    if (doc.getTextWidth(raw) <= maxW) return raw;
    let t = raw;
    while (t.length > 0 && doc.getTextWidth(`${t}…`) > maxW) t = t.slice(0, -1);
    return t.length ? `${t}…` : "—";
  };

  // Card helpers
  const drawCard = (x: number, y: number, w: number, h: number) => {
    setFill(WHITE);
    setDraw(GRAY_200);
    doc.setLineWidth(1);
    doc.roundedRect(x, y, w, h, 8, 8, "FD");
  };

  const drawPill = (x: number, y: number, text: string) => {
    doc.setFont("helvetica", "bold");
    doc.setFontSize(8);

    const padX = 8;
    const padY = 4;
    const tw = doc.getTextWidth(text);
    const w = tw + padX * 2;
    const h = 16;

    setFill(BLUE_50);
    setDraw(GRAY_200);
    doc.roundedRect(x, y - 12, w, h, 8, 8, "FD");

    setText(BLUE_900);
    doc.text(text, x + padX, y);
    return w;
  };

  const sectionTitle = (x: number, y: number, t: string) => {
    doc.setFont("helvetica", "bold");
    doc.setFontSize(10);
    setText(SLATE_900);
    doc.text(t, x, y);
  };

  // Simple table drawer (NO page breaks — one page only)
  type Col = { key: string; label: string; w: number; align?: "left" | "right" | "center" };

  const drawTable = (opts: {
    x: number;
    y: number;
    w: number;
    cols: Col[];
    rows: any[];
    maxRows: number;
    headerH?: number;
    rowH?: number;
    fontSize?: number;
    headerFontSize?: number;
    highlightLastRow?: boolean;
    drawDepartmentColumn?: boolean;
  }) => {
    const x = opts.x;
    let y = opts.y;
    const w = opts.w;
    const headerH = opts.headerH ?? 16;
    const rowH = opts.rowH ?? 14;
    const fontSize = opts.fontSize ?? 6.8;
    const headerFontSize = opts.headerFontSize ?? 7.2;

    // Scale columns
    const sumW = opts.cols.reduce((total, c) => total + c.w, 0);
    if (sumW !== w) {
      const ratio = w / sumW;
      let running = 0;
      for (let i = 0; i < opts.cols.length; i++) {
        const nw = i === opts.cols.length - 1 ? w - running : Math.max(18, Math.floor(opts.cols[i].w * ratio));
        opts.cols[i].w = nw;
        running += nw;
      }
    }

    // Header Background (Flat)
    setFill(BLUE_50);
    doc.rect(x + 1, y, w - 2, headerH, "F");

    // Header Text
    doc.setFont("helvetica", "bold");
    doc.setFontSize(headerFontSize);
    setText(BLUE_900);

    let cx = x;
    for (const c of opts.cols) {
      const tx =
        c.align === "right" ? cx + c.w - 4 : c.align === "center" ? cx + c.w / 2 : cx + 4;
      doc.text(c.label, tx, y + 11, {
        align: c.align === "right" ? "right" : c.align === "center" ? "center" : "left",
      });
      cx += c.w;
    }

    // Sub-header Divider
    setDraw(GRAY_200);
    doc.setLineWidth(0.5);
    doc.line(x + 1, y + headerH, x + w - 1, y + headerH);

    y += headerH;

    // rows (truncate)
    const rows = opts.rows.slice(0, Math.max(0, opts.maxRows));

    doc.setFont("helvetica", "normal");
    doc.setFontSize(fontSize);

    for (let i = 0; i < rows.length; i++) {
      // zebra
      if (i % 2 === 0) {
        setFill(ROW_ZEBRA);
        doc.rect(x + 1, y, w - 2, rowH, "F");
      }

      const isLast = opts.highlightLastRow && i === rows.length - 1;
      if (isLast) {
        setFill(BLUE_50);
        doc.rect(x + 1, y, w - 2, rowH, "F");
        doc.setFont("helvetica", "bold");
      } else {
        doc.setFont("helvetica", "normal");
      }

      cx = x;
      for (const c of opts.cols) {
        const raw = rows[i]?.[c.key] ?? "—";

        const tx =
          c.align === "right" ? cx + c.w - 4 : c.align === "center" ? cx + c.w / 2 : cx + 4;

        setText(SLATE_900);
        doc.text(raw, tx, y + 10, {
          align: c.align === "right" ? "right" : c.align === "center" ? "center" : "left",
        });

        cx += c.w;
      }

      // row line (even subtler)
      setDraw(GRAY_200);
      doc.setLineWidth(0.5);
      doc.line(x + 4, y + rowH, x + w - 4, y + rowH);

      y += rowH;
    }

    return y;
  };

  // ─────────────────────────────────────────────
  // 1) PROCESS DATA (Aggregate across ALL companies)
  // ─────────────────────────────────────────────
  const companySums: CompanySummary[] = [];
  const deptMap = new Map<string, DeptSummary>();

  let bankAdd = 0, bankRemove = 0, bankPrevNet = 0, bankCurrNet = 0, bankCurrEmp = 0, bankPrevEmp = 0;
  let cashAdd = 0, cashRemove = 0, cashPrevNet = 0, cashCurrNet = 0, cashCurrEmp = 0, cashPrevEmp = 0;

  for (const c of args.data || []) {
    const cCurrEmps = c?.currEmps || [];
    const cPrevEmps = c?.prevEmps || [];

    const calculatedCurrNet = cCurrEmps.reduce((sum: number, e: any) => sum + Number(e.net_pay || 0), 0);
    const calculatedPrevNet = cPrevEmps.reduce((sum: number, e: any) => sum + Number(e.net_pay || 0), 0);

    companySums.push({
      name: safeStr(c?.companyName, "—"),
      prevNet: calculatedPrevNet,
      currNet: calculatedCurrNet,
    });
  }

  // ─────────────────────────────────────────────
  // 1.1) PROCESS DATA FOR SUMMARIES (Main Entity Detection)
  // ─────────────────────────────────────────────
  const mainDeptMap = new Map<string, DeptSummary>();
  const mainCompany = (args.data || []).find(c => c.isMain) || (args.data || [])[0];

  if (mainCompany) {
    const mCurrEmps = mainCompany.currEmps || [];
    const mPrevEmps = mainCompany.prevEmps || [];
    const mCurrIds = new Set(mCurrEmps.map((e: any) => e.user_id));
    const mPrevIds = new Set(mPrevEmps.map((e: any) => e.user_id));

    // Aggregate BANK/CASH totals from Main Company
    mCurrEmps.forEach((e: any) => {
      const isCard = Number(e.is_card) === 1;
      if (isCard) {
        bankCurrNet += Number(e.net_pay);
        bankCurrEmp++;
        if (!mPrevIds.has(e.user_id)) bankAdd++;
      } else {
        cashCurrNet += Number(e.net_pay);
        cashCurrEmp++;
        if (!mPrevIds.has(e.user_id)) cashAdd++;
      }
    });

    mPrevEmps.forEach((e: any) => {
      const isCard = Number(e.is_card) === 1;
      if (isCard) {
        bankPrevNet += Number(e.net_pay);
        bankPrevEmp++;
        if (!mCurrIds.has(e.user_id)) bankRemove++;
      } else {
        cashPrevNet += Number(e.net_pay);
        cashPrevEmp++;
        if (!mCurrIds.has(e.user_id)) cashRemove++;
      }
    });

    // Populate Department Map
    const depts = Array.from(new Set([
      ...mCurrEmps.map((e: any) => e.department_name_snapshot || e.department_name || "Unknown"),
      ...mPrevEmps.map((e: any) => e.department_name_snapshot || e.department_name || "Unknown"),
    ]));

    depts.forEach(dName => {
      const d: DeptSummary = {
        name: dName,
        bank: { prevEmp: 0, currEmp: 0, prevNet: 0, currNet: 0, add: 0, rem: 0 },
        cash: { prevEmp: 0, currEmp: 0, prevNet: 0, currNet: 0, add: 0, rem: 0 },
      };

      const cIn = mCurrEmps.filter((e: any) => (e.department_name_snapshot || e.department_name || "Unknown") === dName);
      const pIn = mPrevEmps.filter((e: any) => (e.department_name_snapshot || e.department_name || "Unknown") === dName);

      cIn.forEach((e: any) => {
        const isCard = Number(e.is_card) === 1;
        const target = isCard ? d.bank : d.cash;
        target.currEmp++;
        target.currNet += Number(e.net_pay);
        if (!mPrevIds.has(e.user_id)) target.add++;
      });
      pIn.forEach((e: any) => {
        const isCard = Number(e.is_card) === 1;
        const target = isCard ? d.bank : d.cash;
        target.prevEmp++;
        target.prevNet += Number(e.net_pay);
        if (!mCurrIds.has(e.user_id)) target.rem++;
      });
      mainDeptMap.set(dName, d);
    });
  }

  const grandPrevNet = companySums.reduce((a, c) => a + c.prevNet, 0);
  const grandCurrNet = companySums.reduce((a, c) => a + c.currNet, 0);
  const grandCurrEmp = (args.data || []).reduce((a, c) => a + (c.currEmps?.length || 0), 0);
  const grandPrevEmp = (args.data || []).reduce((a, c) => a + (c.prevEmps?.length || 0), 0);

  // Re-calculate these from ALL employees if we want global counts
  let globalBankAdd = 0, globalBankRemove = 0, globalCashAdd = 0, globalCashRemove = 0;
  for (const c of args.data || []) {
    const mCurrEmps = c.currEmps || [];
    const mPrevEmps = c.prevEmps || [];
    const mCurrIds = new Set(mCurrEmps.map((e: any) => e.user_id));
    const mPrevIds = new Set(mPrevEmps.map((e: any) => e.user_id));

    mCurrEmps.forEach((e: any) => {
      if (!mPrevIds.has(e.user_id)) {
        if (Number(e.is_card) === 1) globalBankAdd++; else globalCashAdd++;
      }
    });
    mPrevEmps.forEach((e: any) => {
      if (!mCurrIds.has(e.user_id)) {
        if (Number(e.is_card) === 1) globalBankRemove++; else globalCashRemove++;
      }
    });
  }

  const reportCompany =
    safeStr(args?.meta?.companyName) ||
    safeStr(mainCompany?.companyName) ||
    "All Companies";

  const cutoffLabel = args?.meta?.currentCutoff
    ? `${fmtDate(args.meta.currentCutoff.start)} to ${fmtDate(args.meta.currentCutoff.end)}`
    : "All";

  const createdAt =
    args?.meta?.createdAt ||
    new Date().toLocaleString("en-PH", {
      year: "numeric",
      month: "2-digit",
      day: "2-digit",
      hour: "2-digit",
      minute: "2-digit",
    });

  // ─────────────────────────────────────────────
  // 2) DRAW (ONE PAGE ONLY)
  // ─────────────────────────────────────────────
  const HEADER_H = 55;

  // Header bar
  setFill(BLUE_800);
  doc.rect(0, 0, pageW, HEADER_H, "F");

  doc.setFont("helvetica", "bold");
  doc.setFontSize(16);
  setText(WHITE);
  doc.text("Payroll Summary Report", M, 25);

  doc.setFont("helvetica", "normal");
  doc.setFontSize(9);
  setText(WHITE);
  doc.text(`${reportCompany} • Cutoff: ${cutoffLabel}`, M, 42);
  doc.text(`Created: ${createdAt}`, pageW - M, 42, { align: "right" });

  setDraw(GRAY_300);
  doc.setLineWidth(1);
  doc.line(M, HEADER_H, pageW - M, HEADER_H);

  let y = HEADER_H + 10;

  // Ribbon
  const ribbonH = 20;
  setFill(BLUE_900);
  doc.roundedRect(M, y, innerW, ribbonH, 6, 6, "F");
  doc.setFont("helvetica", "bold");
  doc.setFontSize(9);
  setText(WHITE);
  doc.text(`Report Totals for: ${cutoffLabel}`, M + 10, y + 13);
  y += ribbonH + 8;

  // KPI row (wider in landscape)
  {
    const gap = 10;
    const cardW = (innerW - gap * 2) / 3;
    const cardH = 50;

    const drawKpi = (x: number, title: string, value: string, sub?: string) => {
      drawCard(x, y, cardW, cardH);
      doc.setFont("helvetica", "normal");
      doc.setFontSize(8);
      setText(SLATE_600);
      doc.text(title, x + 10, y + 15);

      doc.setFont("helvetica", "bold");
      doc.setFontSize(12);
      setText(SLATE_900);
      doc.text(value, x + 10, y + 32);

      if (sub) {
        doc.setFont("helvetica", "normal");
        doc.setFontSize(7.5);
        setText(SLATE_600);
        doc.text(sub, x + 10, y + 44);
      }
    };

    drawKpi(M, "Total Employees", `${fmtInt(bankCurrEmp + cashCurrEmp)} / ${fmtInt(bankPrevEmp + cashPrevEmp)}`, `Add: ${fmtInt(bankAdd + cashAdd)}  •  Remove: ${fmtInt(bankRemove + cashRemove)}`);
    drawKpi(M + cardW + gap, "Previous Cutoff • Total Net", `PHP ${fmtMoney(bankPrevNet + cashPrevNet)}`);
    drawKpi(M + (cardW + gap) * 2, "Current Cutoff • Total Net", `PHP ${fmtMoney(bankCurrNet + cashCurrNet)}`);

    y += cardH + 10;
  }

  // Two-column row: Payment + Company totals
  {
    const gap = 10;
    const colWLeft = Math.floor(innerW * 0.40);
    const colWRight = innerW - gap - colWLeft;
    const leftX = M;
    const rightX = M + colWLeft + gap;

    const cardH = 105;

    // LEFT: Payment Method Summary
    drawCard(leftX, y, colWLeft, cardH);
    sectionTitle(leftX + 10, y + 16, "Payment Method Summary");

    const tablePad = 8;
    const tX = leftX + tablePad;
    const tW = colWLeft - tablePad * 2;
    const tY = y + 24;

    const payCols: Col[] = [
      { key: "m", label: "Method", w: 45, align: "left" },
      { key: "pEmp", label: "Prev", w: 35, align: "right" },
      { key: "cEmp", label: "Curr", w: 35, align: "right" },
      { key: "add", label: "+", w: 15, align: "right" },
      { key: "rem", label: "-", w: 15, align: "right" },
      { key: "prev", label: "Previous Net", w: (tW - 145) / 2, align: "right" },
      { key: "net", label: "Current Net", w: (tW - 145) / 2, align: "right" },
    ];

    const payRows = [
      { m: "BANK", pEmp: fmtInt(bankPrevEmp), cEmp: fmtInt(bankCurrEmp), add: dashIfZero(bankAdd), rem: dashIfZero(bankRemove), prev: fmtMoney(bankPrevNet), net: fmtMoney(bankCurrNet) },
      { m: "CASH", pEmp: fmtInt(cashPrevEmp), cEmp: fmtInt(cashCurrEmp), add: dashIfZero(cashAdd), rem: dashIfZero(cashRemove), prev: fmtMoney(cashPrevNet), net: fmtMoney(cashCurrNet) },
      { m: "TOTAL", pEmp: fmtInt(bankPrevEmp + cashPrevEmp), cEmp: fmtInt(bankCurrEmp + cashCurrEmp), add: dashIfZero(bankAdd + cashAdd), rem: dashIfZero(bankRemove + cashRemove), prev: fmtMoney(bankPrevNet + cashPrevNet), net: fmtMoney(bankCurrNet + cashCurrNet) },
    ];

    drawTable({
      x: tX,
      y: tY,
      w: tW,
      cols: payCols,
      rows: payRows,
      maxRows: 3,
      highlightLastRow: true,
    });

    // RIGHT: Company Totals
    drawCard(rightX, y, colWRight, cardH);
    sectionTitle(rightX + 10, y + 16, "Company Totals");

    const ctX = rightX + tablePad;
    const ctW = colWRight - tablePad * 2;
    const ctY = y + 24;

    const compSorted = [...companySums].sort((a, b) => Math.abs(b.currNet) - Math.abs(a.currNet));
    const totalCurrAll = compSorted.reduce((a, c) => a + (c.currNet || 0), 0);

    // Split into 3 columns if more than 3 companies
    const useMultiCols = compSorted.length > 3;

    if (useMultiCols) {
      const colGap = 8;
      const subTW = (ctW - colGap * 2) / 3;

      const c1 = compSorted.slice(0, 3);
      const c2 = compSorted.slice(3, 6);
      const c3 = compSorted.slice(6, 9);

      const subCols: Col[] = [
        { key: "c", label: "Company", w: Math.floor(subTW * 0.45), align: "left" },
        { key: "net", label: "Curr. Net", w: subTW - Math.floor(subTW * 0.45), align: "right" },
      ];

      const drawSubTable = (list: CompanySummary[], sx: number) => {
        if (list.length === 0) return;
        const rows = list.map(c => ({
          c: ellipsize(c.name, subCols[0].w - 4),
          net: fmtMoney(c.currNet)
        }));
        drawTable({
          x: sx,
          y: ctY,
          w: subTW,
          cols: subCols,
          rows: rows,
          maxRows: 3,
        });
      };

      drawSubTable(c1, ctX);
      drawSubTable(c2, ctX + subTW + colGap);
      drawSubTable(c3, ctX + (subTW + colGap) * 2);

      // Grand Total Row (Shared) - Only at the bottom of the last column
      const gy = ctY + 16 + (3 * 14); // 3 rows max
      const gx = ctX + (subTW + colGap) * 2; // Position in last column
      setFill(BLUE_50);
      doc.rect(gx, gy, subTW, 14, "F");
      doc.setFont("helvetica", "bold");
      doc.setFontSize(7);
      setText(BLUE_900);
      doc.text("TOTAL", gx + 4, gy + 10);
      doc.text(`${fmtMoney(totalCurrAll)}`, gx + subTW - 4, gy + 10, { align: "right" });

    } else {
      const compCols: Col[] = [
        { key: "c", label: "Company", w: Math.floor(ctW * 0.50), align: "left" },
        { key: "prev", label: "Prev. Net", w: Math.floor(ctW * 0.25), align: "right" },
        { key: "net", label: "Curr. Net", w: ctW - Math.floor(ctW * 0.50) - Math.floor(ctW * 0.25), align: "right" },
      ];

      const compRows: Record<string, string>[] = compSorted.map((c) => ({
        c: ellipsize(c.name, compCols[0].w - 6),
        prev: fmtMoney(c.prevNet),
        net: fmtMoney(c.currNet),
      }));

      const totalPrevAll = compSorted.reduce((a, c) => a + (c.prevNet || 0), 0);
      compRows.push({ c: "TOTAL", prev: fmtMoney(totalPrevAll), net: fmtMoney(totalCurrAll) });

      drawTable({
        x: ctX,
        y: ctY,
        w: ctW,
        cols: compCols,
        rows: compRows,
        maxRows: 5,
        highlightLastRow: true,
      });
    }

    y += cardH + 10;
  }

  // 3-COLUMN DEPARTMENT BREAKDOWN
  {
    const cardH = pageH - M - footerH - y + 5;
    drawCard(M, y, innerW, cardH);

    sectionTitle(M + 12, y + 16, "Department Breakdown");

    const breakdownPill = safeStr(mainCompany?.companyName, "Company");
    const breakdownPillW = doc.getTextWidth(breakdownPill) + 16;
    drawPill(M + innerW - breakdownPillW - 10, y + 16, breakdownPill);

    const pad = 10;
    const gap = 10;
    const tW = (innerW - pad * 2 - gap * 2) / 3;
    const commonY = y + 36;

    const allDepts = Array.from(mainDeptMap.values()).sort((a, b) => a.name.localeCompare(b.name));

    const drawSection = (label: string, x: number, dataKey: "bank" | "cash" | "total") => {
      doc.setFont("helvetica", "bold");
      doc.setFontSize(8.5);
      setText(BLUE_900);
      doc.text(label, x, commonY - 5);

      const rows: any[] = allDepts.map(d => {
        let data;
        if (dataKey === "total") {
          data = {
            prevEmp: d.bank.prevEmp + d.cash.prevEmp,
            currEmp: d.bank.currEmp + d.cash.currEmp,
            prevNet: d.bank.prevNet + d.cash.prevNet,
            currNet: d.bank.currNet + d.cash.currNet,
            add: d.bank.add + d.cash.add,
            rem: d.bank.rem + d.cash.rem,
          };
        } else {
          data = d[dataKey];
        }

        return {
          d: ellipsize(d.name, 60),
          pEmp: fmtInt(data.prevEmp),
          pNet: fmtMoney(data.prevNet),
          add: dashIfZero(data.add),
          rem: dashIfZero(data.rem),
          cEmp: fmtInt(data.currEmp),
          cNet: fmtMoney(data.currNet),
        };
      });

      // Calculate totals for section
      const secTotals = allDepts.reduce((acc, d) => {
        let val;
        if (dataKey === "total") {
          val = {
            pEmp: d.bank.prevEmp + d.cash.prevEmp,
            cEmp: d.bank.currEmp + d.cash.currEmp,
            pNet: d.bank.prevNet + d.cash.prevNet,
            cNet: d.bank.currNet + d.cash.currNet,
            a: d.bank.add + d.cash.add,
            r: d.bank.rem + d.cash.rem
          };
        } else {
          const v = d[dataKey];
          val = { pEmp: v.prevEmp, cEmp: v.currEmp, pNet: v.prevNet, cNet: v.currNet, a: v.add, r: v.rem };
        }
        acc.pEmp += val.pEmp; acc.cEmp += val.cEmp; acc.pNet += val.pNet; acc.cNet += val.cNet; acc.a += val.a; acc.r += val.r;
        return acc;
      }, { pEmp: 0, cEmp: 0, pNet: 0, cNet: 0, a: 0, r: 0 });

      rows.push({
        d: "TOTAL",
        pEmp: fmtInt(secTotals.pEmp),
        pNet: fmtMoney(secTotals.pNet),
        add: dashIfZero(secTotals.a),
        rem: dashIfZero(secTotals.r),
        cEmp: fmtInt(secTotals.cEmp),
        cNet: fmtMoney(secTotals.cNet)
      });

      const cols: Col[] = [
        { key: "d", label: dataKey === "bank" ? "Dept" : "—", w: 60, align: "left" },
        { key: "pNet", label: "Prev Net", w: 60, align: "right" },
        { key: "add", label: "+", w: 15, align: "right" },
        { key: "rem", label: "-", w: 15, align: "right" },
        { key: "cNet", label: "Curr Net", w: 60, align: "right" },
      ];

      drawTable({
        x,
        y: commonY,
        w: tW,
        cols,
        rows,
        maxRows: 22,
        highlightLastRow: true,
      });
    };

    drawSection("BANK", M + pad, "bank");
    drawSection("CASH", M + pad + tW + gap, "cash");
    drawSection("TOTAL", M + pad + (tW + gap) * 2, "total");
  }

  // Footer (Page 1 of 1)
  {
    const fy = pageH - M + 8;
    setDraw(GRAY_200);
    doc.setLineWidth(1);
    doc.line(M, fy - 8, pageW - M, fy - 8);

    doc.setFont("helvetica", "normal");
    doc.setFontSize(8);
    setText(SLATE_600);
    doc.text(`${reportCompany} • Payroll Summary`, M, fy);
    doc.text("Page 1 of 1", pageW - M, fy, { align: "right" });
  }

  return doc;
}

// modules/payroll-records/utils/tapSheet.ts
import type { EmployeeMaster, PayrollRunEmployeeRow, TapSheetRow } from "../types";
import { toNumberSafe } from "./money";

/** Handles 1/0, true/false, "1"/"0", and Directus buffer-ish { data: [1] } */
function isTruthyFlag(v: unknown): boolean {
  if (v === null || v === undefined) return false;

  if (typeof v === "object") {
    const anyV = v as any;
    const d0 = anyV?.data?.[0];
    if (d0 === 1 || d0 === "1" || d0 === true) return true;
    if (d0 === 0 || d0 === "0" || d0 === false || d0 == null) return false;
  }

  if (typeof v === "boolean") return v;
  if (typeof v === "number") return v === 1;
  if (typeof v === "string") return v.trim() === "1" || v.trim().toLowerCase() === "true";

  return false;
}

function isOnHoldRow(r: PayrollRunEmployeeRow): boolean {
  return isTruthyFlag((r as any)?.on_hold);
}

export function formatEmployeeNameLFM(emp: EmployeeMaster): string {
  const last = (emp.user_lname ?? "").trim();
  const first = (emp.user_fname ?? "").trim();
  const middle = (emp.user_mname ?? "").trim();
  return middle ? `${last}, ${first} ${middle}` : `${last}, ${first}`;
}

export function buildNameSortKey(emp: EmployeeMaster): string {
  const last = (emp.user_lname ?? "").trim().toLowerCase();
  const first = (emp.user_fname ?? "").trim().toLowerCase();
  const middle = (emp.user_mname ?? "").trim().toLowerCase();
  return `${last}|${first}|${middle}`;
}

/**
 * ✅ Keep the latest payroll_run_id per user_id
 * ✅ Then EXCLUDE users whose latest row is on-hold (on_hold=1)
 */
export function dedupeByUserKeepLatestRun(rows: PayrollRunEmployeeRow[]): PayrollRunEmployeeRow[] {
  const map = new Map<number, PayrollRunEmployeeRow>();

  for (const r of rows) {
    const prev = map.get(r.user_id);

    // Robust extraction of the numeric payroll_run_id
    const rVal = r.payroll_run_id;
    let rId: number = 0;
    if (typeof rVal === "number") {
      rId = rVal;
    } else if (rVal && typeof rVal === "object") {
      // Directus sometimes nests the ID as 'id' or 'payroll_run_id' depending on the query
      rId = (rVal as any).id || (rVal as any).payroll_run_id || 0;
    }

    const prevVal = prev?.payroll_run_id;
    let prevId: number = 0;
    if (typeof prevVal === "number") {
      prevId = prevVal;
    } else if (prevVal && typeof prevVal === "object") {
      prevId = (prevVal as any).id || (prevVal as any).payroll_run_id || 0;
    }

    if (!prev || rId >= prevId) {
      map.set(r.user_id, r);
    }
  }

  return Array.from(map.values()).filter((r) => !isOnHoldRow(r));
}

export function buildTapSheetRows(
  payrollRows: PayrollRunEmployeeRow[],
  employees: EmployeeMaster[],
): TapSheetRow[] {
  const empMap = new Map<number, EmployeeMaster>();
  for (const e of employees) empMap.set(e.user_id, e);

  const safeRows = payrollRows.filter((r) => !isOnHoldRow(r));

  return safeRows.map((pr) => {
    const emp = empMap.get(pr.user_id);

    const name_display = emp ? formatEmployeeNameLFM(emp) : (pr.employee_name ?? `User #${pr.user_id}`);

    const name_sort_key = emp
      ? buildNameSortKey(emp)
      : (pr.employee_name ?? `user #${pr.user_id}`).trim().toLowerCase();

    const isCard = isTruthyFlag(pr.is_card);

    // Robust extraction of nested metadata
    let ref = pr.payroll_ref_no;
    let posted = pr.posted_at;

    if (pr.payroll_run_id && typeof pr.payroll_run_id === "object") {
      const runObj = pr.payroll_run_id as any;
      if (!ref) ref = runObj.payroll_ref_no;
      if (!posted) posted = runObj.posted_at;
    }

    const grossOrig = toNumberSafe(pr.gross_pay);
    const addsOrig = toNumberSafe(pr.total_additions);

    const basic = toNumberSafe(pr.basic_pay);
    const ot = toNumberSafe(pr.ot_amount);
    const hol = toNumberSafe(pr.holiday_pay);
    const rest = toNumberSafe(pr.rest_day_amount);
    const nd = toNumberSafe(pr.night_diff_amount);

    // New Logic: 
    // Gross = Basic + OT + Holiday + Rest Day + Night Diff
    // Additions = Original Additions - (OT + Holiday + Rest Day + Night Diff)
    const adjustedGross = basic + ot + hol + rest + nd;
    const adjustedAdds = addsOrig - (ot + hol + rest + nd);

    return {
      user_id: pr.user_id,
      name_display,
      name_sort_key,
      payment_type: isCard ? "BANK" : "CASH",
      gross_pay: adjustedGross,
      total_additions: adjustedAdds,
      total_deductions: toNumberSafe(pr.total_deductions),
      net_pay: toNumberSafe(pr.net_pay),

      // ✅ New fields
      employee_no: pr.user_id.toString().padStart(4, "0"),
      days_worked: toNumberSafe(pr.total_days_worked),
      work_hours: toNumberSafe(pr.total_work_minutes) / 60,

      payroll_ref_no: ref,
      posted_at: posted,
    };
  });
}

// modules/payroll-records/utils/tapSheetPdf.ts
import jsPDF from "jspdf";
import type { TapSheetRow } from "../types";

type Totals = { gross: number; adds: number; deds: number; net: number };

let fontInitPromise: Promise<boolean> | null = null;

function toNum(v: any): number {
  const x = typeof v === "number" ? v : Number(String(v ?? "").replace(/,/g, ""));
  return Number.isFinite(x) ? x : 0;
}

/** Format number ONLY (no currency symbol) */
function formatAmountOnly(n: number) {
  const x = Number.isFinite(n) ? n : 0;
  try {
    return x.toLocaleString("en-PH", { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  } catch {
    return x.toLocaleString(undefined, { minimumFractionDigits: 2, maximumFractionDigits: 2 });
  }
}

/** 
 * Show whole numbers without decimals (12), 
 * but fractionals with up to 2 (12.5) 
 */
function formatSmartDecimal(n: number) {
  const x = Number.isFinite(n) ? n : 0;
  if (Number.isInteger(x)) return x.toString();
  return x.toLocaleString("en-PH", { minimumFractionDigits: 0, maximumFractionDigits: 2 });
}

/** Format date to MMM D, YYYY */
function fmtDate(iso: string) {
  if (!iso || iso === "-") return "—";
  const d = new Date(iso);
  if (isNaN(d.getTime())) return iso;
  return d.toLocaleDateString("en-US", { month: "short", day: "numeric", year: "numeric" });
}

function arrayBufferToBase64(buf: ArrayBuffer) {
  const bytes = new Uint8Array(buf);
  if (typeof btoa === "function") {
    let binary = "";
    const chunk = 0x8000;
    for (let i = 0; i < bytes.length; i += chunk) {
      binary += String.fromCharCode(...bytes.subarray(i, i + chunk));
    }
    return btoa(binary);
  }
  // eslint-disable-next-line @typescript-eslint/no-explicit-any
  const B: any = (globalThis as any).Buffer;
  if (B) return B.from(bytes).toString("base64");
  throw new Error("Base64 encoder not available.");
}

/**
 * Loads a font that supports ₱ (Peso sign) so we don't get "±".
 * Put these files in:
 *   public/fonts/Inter-Regular.ttf
 *   public/fonts/Inter-Bold.ttf
 */
async function ensurePesoFont(doc: jsPDF): Promise<boolean> {
  if (fontInitPromise) return fontInitPromise;

  fontInitPromise = (async () => {
    try {
      const anyDoc = doc as any;
      if (!anyDoc.addFileToVFS || !anyDoc.addFont) return false;

      const [regRes, boldRes] = await Promise.all([
        fetch("/fonts/Inter-Regular.ttf", { cache: "no-store" }),
        fetch("/fonts/Inter-Bold.ttf", { cache: "no-store" }),
      ]);

      if (!regRes.ok || !boldRes.ok) return false;

      const [regBuf, boldBuf] = await Promise.all([regRes.arrayBuffer(), boldRes.arrayBuffer()]);

      anyDoc.addFileToVFS("Inter-Regular.ttf", arrayBufferToBase64(regBuf));
      anyDoc.addFileToVFS("Inter-Bold.ttf", arrayBufferToBase64(boldBuf));
      anyDoc.addFont("Inter-Regular.ttf", "Inter", "normal");
      anyDoc.addFont("Inter-Bold.ttf", "Inter", "bold");

      return true;
    } catch {
      return false;
    }
  })();

  return fontInitPromise;
}

function fitTextEllipsis(doc: jsPDF, text: string, maxW: number) {
  const s = (text ?? "").toString();
  if (!s) return "";
  if (doc.getTextWidth(s) <= maxW) return s;

  const ell = "…";
  let lo = 0;
  let hi = s.length;
  while (lo < hi) {
    const mid = Math.ceil((lo + hi) / 2);
    const candidate = s.slice(0, mid) + ell;
    if (doc.getTextWidth(candidate) <= maxW) lo = mid;
    else hi = mid - 1;
  }
  return s.slice(0, Math.max(0, lo)) + ell;
}

function drawRightFitted(args: {
  doc: jsPDF;
  text: string;
  xRight: number;
  y: number;
  maxW: number;
  baseSize: number;
  minSize?: number;
  fontFamily: string;
  fontStyle: "normal" | "bold";
  color?: { r: number; g: number; b: number };
}) {
  const { doc, text, xRight, y, maxW, baseSize, minSize = 6.5, fontFamily, fontStyle, color } = args;

  let size = baseSize;
  doc.setFont(fontFamily, fontStyle);
  doc.setFontSize(size);
  if (color) doc.setTextColor(color.r, color.g, color.b);

  while (doc.getTextWidth(text) > maxW && size > minSize) {
    size -= 0.5;
    doc.setFontSize(size);
  }

  doc.text(text, xRight, y, { align: "right" });
}

export async function buildTapSheetPdf(args: {
  companyName?: string;
  departmentName: string;
  cutoffStart: string;
  cutoffEnd: string;
  rows: TapSheetRow[];
  totals: Totals;
  filterType: "ALL" | "BANK" | "CASH";
  payrollRefNo?: string;
  postedAt?: string;
}) {
  // LEGAL paper
  const doc = new jsPDF({ orientation: "portrait", unit: "pt", format: "legal" });

  const pageW = doc.internal.pageSize.getWidth();
  const pageH = doc.internal.pageSize.getHeight();

  const marginX = 34;
  const marginTop = 22;
  const marginBottom = 34;

  // palette
  const ACCENT = { r: 16, g: 54, b: 98 };
  const ACCENT_SOFT = { r: 236, g: 242, b: 252 };
  const GRID = { r: 210, g: 218, b: 230 };
  const TEXT_MUTED = { r: 70, g: 75, b: 85 };

  // font
  const fontOk = await ensurePesoFont(doc);
  const fontFamily = fontOk ? "Inter" : "helvetica";
  const currencyPrefix = fontOk ? "₱" : "PHP";

  // ABS, no +/- sign
  const peso = (v: any) => `${currencyPrefix} ${formatAmountOnly(Math.abs(toNum(v)))}`;

  // Conditional Column Logic
  const showTypeCol = args.filterType === "ALL";

  // columns (avoid overflow)
  const availableW = pageW - marginX * 2;

  const colAmtW = 62;
  const colTypeW = showTypeCol ? 40 : 0;
  const colIdW = 32;
  const colDaysW = 32;
  const colHoursW = 34;
  
  const colNameW = availableW - colTypeW - colIdW - colDaysW - colHoursW - colAmtW * 4;

  const x0 = marginX;
  const xName = x0;
  const xId = xName + colNameW;
  const xDays = xId + colIdW;
  const xHours = xDays + colDaysW;
  const xType = xHours + colHoursW; // if colTypeW is 0, this is start of Gross
  const xGross = xType + colTypeW;
  const xAdds = xGross + colAmtW;
  const xDeds = xAdds + colAmtW;
  const xNet = xDeds + colAmtW;
  const xEnd = x0 + availableW;

  const headerBandH = 30;
  const tableStartY = 155;

  const rowH = 14;

  const drawFooter = (pageNo: number) => {
    doc.setFont(fontFamily, "normal");
    doc.setFontSize(9);
    doc.setTextColor(TEXT_MUTED.r, TEXT_MUTED.g, TEXT_MUTED.b);
    doc.text(`Page ${pageNo}`, pageW - marginX, pageH - 18, { align: "right" });
    doc.setTextColor(0, 0, 0);
  };

  const drawHeader = () => {
    // 1. Primary Header Band (Accent Blue)
    doc.setFillColor(ACCENT.r, ACCENT.g, ACCENT.b);
    doc.rect(0, 0, pageW, headerBandH + 10, "F");

    doc.setFont(fontFamily, "bold");
    doc.setFontSize(12);
    doc.setTextColor(255, 255, 255);
    const companyLabel = (args.companyName || "").toUpperCase();
    doc.text(companyLabel, pageW / 2, marginTop + 16, { align: "center" });

    // 2. Document Title (Subtle Ribbon)
    const titleY = headerBandH + 18;
    doc.setFillColor(ACCENT_SOFT.r, ACCENT_SOFT.g, ACCENT_SOFT.b);
    doc.setDrawColor(GRID.r, GRID.g, GRID.b);
    doc.roundedRect(pageW / 2 - 70, titleY, 140, 20, 2, 2, "FD");

    doc.setTextColor(ACCENT.r, ACCENT.g, ACCENT.b);
    doc.setFontSize(10);
    doc.setFont(fontFamily, "bold");
    doc.text("TOP SHEET REPORT", pageW / 2, titleY + 14, { align: "center" });

    // 3. Metadata Grid
    const gridY = titleY + 42;
    doc.setTextColor(0, 0, 0);

    // Left Column: Core Identity
    doc.setFont(fontFamily, "bold");
    doc.setFontSize(9);
    doc.text("DEPARTMENT:", x0, gridY);
    doc.setFont(fontFamily, "normal");
    doc.setFontSize(10);
    const deptDisplayName = (args.departmentName || "ALL DEPARTMENTS").toUpperCase();
    doc.text(deptDisplayName, x0 + 72, gridY);

    const cutoffLabel = `PERIOD: ${fmtDate(args.cutoffStart)} — ${fmtDate(args.cutoffEnd)}`;
    doc.setFont(fontFamily, "bold");
    doc.setFontSize(8.5);
    doc.setTextColor(TEXT_MUTED.r, TEXT_MUTED.g, TEXT_MUTED.b);
    doc.text(cutoffLabel, x0, gridY + 16);

    // Right Column: Summary Stats
    doc.setFont(fontFamily, "bold");
    doc.setFontSize(9);
    doc.setTextColor(0, 0, 0);
    doc.text("EMPLOYEES:", xEnd - 22, gridY, { align: "right" });
    doc.setFontSize(11);
    doc.text(String(args.rows.length), xEnd, gridY, { align: "right" });

    // Payment Filter (if single)
    if (!showTypeCol) {
      doc.setFont(fontFamily, "bold");
      doc.setFontSize(8);
      doc.setTextColor(TEXT_MUTED.r, TEXT_MUTED.g, TEXT_MUTED.b);
      doc.text(`MODE: ${args.filterType.toUpperCase()}`, xEnd, gridY + 15, { align: "right" });
    }

    // 4. Administrative Footer (Small/Muted)
    const adminY = gridY + 30;
    doc.setFont(fontFamily, "normal");
    doc.setFontSize(8);
    doc.setTextColor(TEXT_MUTED.r * 1.2, TEXT_MUTED.g * 1.2, TEXT_MUTED.b * 1.2);
    doc.text(`PAYROLL ID: ${args.payrollRefNo || "N/A"}`, x0, adminY);
    doc.text(`POSTED ON: ${fmtDate(args.postedAt || "-")}`, xEnd, adminY, { align: "right" });

    // Main separator
    doc.setDrawColor(GRID.r, GRID.g, GRID.b);
    doc.setLineWidth(1);
    doc.line(x0, adminY + 8, xEnd, adminY + 8);
  };

  const drawTableHeader = (y: number) => {
    doc.setFillColor(ACCENT_SOFT.r, ACCENT_SOFT.g, ACCENT_SOFT.b);
    doc.setDrawColor(GRID.r, GRID.g, GRID.b);
    doc.setLineWidth(0.6);
    doc.rect(x0, y, availableW, rowH, "FD");

    doc.setFont(fontFamily, "bold");
    doc.setFontSize(8);
    doc.setTextColor(ACCENT.r, ACCENT.g, ACCENT.b);

    const ty = y + 11;
    doc.text("EMPLOYEE NAME", xName + 6, ty);

    doc.text("ID", xId + 3, ty);
    doc.text("DAYS", xDays + 3, ty);
    doc.text("HOURS", xHours + 3, ty);

    if (showTypeCol) {
      doc.text("TYPE", xType + 3, ty);
    }

    doc.text("GROSS PAY", xGross + colAmtW - 6, ty, { align: "right" });
    doc.text("ADDITIONS", xAdds + colAmtW - 6, ty, { align: "right" });
    doc.text("DEDUCTIONS", xDeds + colAmtW - 6, ty, { align: "right" });
    doc.text("NET PAY", xNet + colAmtW - 6, ty, { align: "right" });

    doc.setDrawColor(GRID.r, GRID.g, GRID.b);
    doc.setLineWidth(0.6);

    doc.line(xId, y, xId, y + rowH);
    doc.line(xDays, y, xDays, y + rowH);
    doc.line(xHours, y, xHours, y + rowH);

    if (showTypeCol) {
      doc.line(xType, y, xType, y + rowH);
    }

    doc.line(xGross, y, xGross, y + rowH);
    doc.line(xAdds, y, xAdds, y + rowH);
    doc.line(xDeds, y, xDeds, y + rowH);
    doc.line(xNet, y, xNet, y + rowH);

    doc.setFont(fontFamily, "normal");
    doc.setFontSize(8);
    doc.setTextColor(0, 0, 0);

    return y + rowH;
  };

  const drawRow = (y: number, r: TapSheetRow, zebra: boolean) => {
    if (zebra) {
      doc.setFillColor(252, 253, 255);
      doc.rect(x0, y, availableW, rowH, "F");
    }

    doc.setDrawColor(GRID.r, GRID.g, GRID.b);
    doc.setLineWidth(0.4);
    doc.rect(x0, y, availableW, rowH);

    doc.line(xId, y, xId, y + rowH);
    doc.line(xDays, y, xDays, y + rowH);
    doc.line(xHours, y, xHours, y + rowH);

    if (showTypeCol) {
      doc.line(xType, y, xType, y + rowH);
    }

    doc.line(xGross, y, xGross, y + rowH);
    doc.line(xAdds, y, xAdds, y + rowH);
    doc.line(xDeds, y, xDeds, y + rowH);
    doc.line(xNet, y, xNet, y + rowH);

    const ty = y + 11;

    // name
    doc.setFont(fontFamily, "normal");
    doc.setFontSize(7.2);
    doc.setTextColor(0, 0, 0);
    const name = fitTextEllipsis(doc, r.name_display ?? "", colNameW - 10);
    doc.text(name, xName + 5, ty);

    // ID / stats
    doc.setFontSize(6.8);
    doc.text(r.employee_no, xId + 3, ty);
    doc.text(formatSmartDecimal(r.days_worked), xDays + 3, ty);
    doc.text(formatSmartDecimal(r.work_hours), xHours + 3, ty);

    // type
    if (showTypeCol) {
      doc.setFontSize(6.8);
      const type = r.payment_type === "BANK" ? "BANK" : "CASH";
      doc.text(type, xType + 3, ty);
    }

    // amounts: smaller font
    const maxAmtW = colAmtW - 10;

    drawRightFitted({
      doc,
      text: peso(r.gross_pay),
      xRight: xGross + colAmtW - 5,
      y: ty,
      maxW: maxAmtW,
      baseSize: 7,
      minSize: 6,
      fontFamily,
      fontStyle: "normal",
      color: TEXT_MUTED,
    });

    drawRightFitted({
      doc,
      text: peso(r.total_additions),
      xRight: xAdds + colAmtW - 5,
      y: ty,
      maxW: maxAmtW,
      baseSize: 7,
      minSize: 6,
      fontFamily,
      fontStyle: "normal",
      color: TEXT_MUTED,
    });

    drawRightFitted({
      doc,
      text: peso(r.total_deductions),
      xRight: xDeds + colAmtW - 5,
      y: ty,
      maxW: maxAmtW,
      baseSize: 7,
      minSize: 6,
      fontFamily,
      fontStyle: "normal",
      color: TEXT_MUTED,
    });

    // net: bold accent, still small-ish
    drawRightFitted({
      doc,
      text: peso(r.net_pay),
      xRight: xNet + colAmtW - 5,
      y: ty,
      maxW: maxAmtW,
      baseSize: 7,
      minSize: 6,
      fontFamily,
      fontStyle: "bold",
      color: ACCENT,
    });

    doc.setTextColor(0, 0, 0);
  };

  const drawTotals = (y: number) => {
    doc.setFillColor(ACCENT.r, ACCENT.g, ACCENT.b);
    doc.rect(x0, y, availableW, rowH + 2, "F");

    doc.setDrawColor(ACCENT.r, ACCENT.g, ACCENT.b);
    doc.setLineWidth(0.8);

    doc.line(xId, y, xId, y + rowH + 2);
    doc.line(xDays, y, xDays, y + rowH + 2);
    doc.line(xHours, y, xHours, y + rowH + 2);

    if (showTypeCol) {
      doc.line(xType, y, xType, y + rowH + 2);
    }

    doc.line(xGross, y, xGross, y + rowH + 2);
    doc.line(xAdds, y, xAdds, y + rowH + 2);
    doc.line(xDeds, y, xDeds, y + rowH + 2);
    doc.line(xNet, y, xNet, y + rowH + 2);

    doc.setFont(fontFamily, "bold");
    doc.setFontSize(8);
    doc.setTextColor(255, 255, 255);

    const ty = y + 12;
    doc.text("TOTAL", xName + 6, ty);
    // Removed count from footer per user request

    const maxAmtW = colAmtW - 12;

    drawRightFitted({
      doc,
      text: peso(args.totals.gross),
      xRight: xGross + colAmtW - 6,
      y: ty,
      maxW: maxAmtW,
      baseSize: 7.5,
      minSize: 6.5,
      fontFamily,
      fontStyle: "bold",
      color: { r: 255, g: 255, b: 255 },
    });

    drawRightFitted({
      doc,
      text: peso(args.totals.adds),
      xRight: xAdds + colAmtW - 6,
      y: ty,
      maxW: maxAmtW,
      baseSize: 7.5,
      minSize: 6.5,
      fontFamily,
      fontStyle: "bold",
      color: { r: 255, g: 255, b: 255 },
    });

    drawRightFitted({
      doc,
      text: peso(args.totals.deds),
      xRight: xDeds + colAmtW - 6,
      y: ty,
      maxW: maxAmtW,
      baseSize: 7.5,
      minSize: 6.5,
      fontFamily,
      fontStyle: "bold",
      color: { r: 255, g: 255, b: 255 },
    });

    drawRightFitted({
      doc,
      text: peso(args.totals.net),
      xRight: xNet + colAmtW - 6,
      y: ty,
      maxW: maxAmtW,
      baseSize: 7.5,
      minSize: 6.5,
      fontFamily,
      fontStyle: "bold",
      color: { r: 255, g: 255, b: 255 },
    });

    doc.setTextColor(0, 0, 0);
    return y + rowH + 2;
  };

  // ... rest of logic
  const ensureSpace = (y: number, needH: number, pageNoRef: { v: number }) => {
    const limit = pageH - marginBottom;
    if (y + needH <= limit) return y;

    drawFooter(pageNoRef.v);
    doc.addPage();
    pageNoRef.v += 1;

    drawHeader();
    let ny = tableStartY;
    ny = drawTableHeader(ny);
    return ny;
  };

  const pageNo = { v: 1 };
  drawHeader();

  let y = tableStartY;
  y = drawTableHeader(y);

  let zebra = false;
  for (const r of args.rows) {
    y = ensureSpace(y, rowH, pageNo);
    drawRow(y, r, zebra);
    zebra = !zebra;
    y += rowH;
  }

  y = ensureSpace(y, rowH + 6, pageNo);
  y = drawTotals(y);

  drawFooter(pageNo.v);

  return doc;
}

// modules/payroll-run/PayrollRunModule.tsx
"use client";

import React, { useCallback, useEffect, useMemo, useState } from "react";
import DashboardLayout from "@/components/layout/DashboardLayout";
import { Card } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { toast } from "sonner";
import {
  CheckCircle2,
  ClipboardCheck,
  PlayCircle,
  RefreshCcw,
} from "lucide-react";
import { Skeleton } from "@/components/ui/skeleton";

import type {
  CutoffSetting,
  Department,
  PayrollConfigState,
  PayrollRunHeader,
  PayrollStep,
  PayrollWorkspace,
} from "./types";

import { PayrollStepper } from "./components/PayrollStepper";
import { PayrollConfigStep } from "./components/PayrollConfigStep";
import { PayrollAdjustStep } from "./components/PayrollAdjustStep";
import { PayrollProcessStep } from "./components/PayrollProcessStep";
import { PayrollReviewStep } from "./components/PayrollReviewStep";
import PasswordDialog from "./components/PasswordDialog";

import * as svc from "./providers/payrollRunService";
import * as api from "./providers/payrollApi";
import { formatCutoffLabel } from "./utils/payroll";

const DEFAULT_CONFIG: PayrollConfigState = {
  cutoffId: null,
  departmentId: null, // null = ALL
};

function stepLabel(step: PayrollStep) {
  switch (step) {
    case 1:
      return "Configure";
    case 2:
      return "Adjust";
    case 3:
      return "Processing";
    case 4:
      return "Review";
    default:
      return "Payroll Run";
  }
}

function statusClasses(status?: string | null) {
  const s = String(status ?? "").toUpperCase();
  if (s === "POSTED")
    return "border-emerald-200/60 bg-emerald-50 text-emerald-700";
  if (s === "DRAFT") return "border-amber-200/60 bg-amber-50 text-amber-700";
  return "border-border bg-muted/40 text-muted-foreground";
}

export default function PayrollRunModule() {
  const [step, setStep] = useState<PayrollStep>(1);

  // master data
  const [cutoffs, setCutoffs] = useState<CutoffSetting[]>([]);
  const [departments, setDepartments] = useState<Department[]>([]);
  const [loadingMaster, setLoadingMaster] = useState(false);

  // config
  const [config, setConfig] = useState<PayrollConfigState>(DEFAULT_CONFIG);

  // run header
  const [run, setRun] = useState<PayrollRunHeader | null>(null);

  // loaded workspace inputs
  const [ws, setWs] = useState<PayrollWorkspace | null>(null);
  const [loadingWs, setLoadingWs] = useState(false);

  // hold/exclude
  const [holdMap, setHoldMap] = useState<Map<number, boolean>>(new Map());

  // posted employees (read-only in adjust step)
  const [postedMap, setPostedMap] = useState<Map<number, boolean>>(new Map());


  // password dialog
  const [passwordDialogOpen, setPasswordDialogOpen] = useState(false);

  // computed register
  const computed = useMemo(() => {
    if (!ws) return null;
    return svc.computeRegister({ ws, holdMap });
  }, [ws, holdMap]);

  const selectedCutoff = useMemo(
    () => cutoffs.find((c) => c.id === config.cutoffId) ?? null,
    [cutoffs, config.cutoffId],
  );

  const selectedDepartment = useMemo(
    () =>
      config.departmentId == null
        ? null
        : (departments.find((d) => d.id === config.departmentId) ?? null),
    [departments, config.departmentId],
  );

  useEffect(() => {
    (async () => {
      try {
        setLoadingMaster(true);
        const [c, d] = await Promise.all([
          svc.listCutoffs(),
          svc.listDepartments(),
        ]);
        setCutoffs(c);
        setDepartments(d);

        // preselect first cutoff if none
        if (c.length && config.cutoffId == null) {
          setConfig((p) => ({ ...p, cutoffId: c[0].id }));
        }
      } catch (e: any) {
        toast.error(e?.message || "Failed to load payroll masters");
      } finally {
        setLoadingMaster(false);
      }
    })();
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);

  const handleContinueClick = () => {
    if (!selectedCutoff) {
      toast.error("Please select a cutoff.");
      return;
    }
    setPasswordDialogOpen(true);
  };

  const handlePasswordSubmit = async (passwordInput: string) => {
    try {
      const session = sessionStorage.getItem("user");
      if (!session) return alert("User not logged in.");
      const logged = JSON.parse(session);

      const apiUser = await api.fetchUserById(logged.user_id);
      if (!apiUser) return alert("User record not found.");
      if (passwordInput !== apiUser.user_password)
        return alert("Incorrect password.");

      const ts = new Date().toISOString();
      const deptName = selectedDepartment ? selectedDepartment.name : "All Departments";
      const cutoffLabel = selectedCutoff ? formatCutoffLabel(selectedCutoff) : "Unknown";
      const remarks = `Accessed payroll run for ${cutoffLabel} - ${deptName} at ${ts}`;
      
      await api.logPayrollRunAccess(
        logged.user_id,
        selectedCutoff!.id,
        config.departmentId,
        remarks
      );

      setPasswordDialogOpen(false);
      await loadOrCreateRunAndWorkspace();
    } catch (e) {
      console.error(e);
      alert("Error verifying password. Try again.");
    }
  };

  async function loadOrCreateRunAndWorkspace() {
    if (!selectedCutoff) {
      toast.error("Please select a cutoff.");
      return;
    }

    try {
      setLoadingWs(true);

      // 1) Load existing draft run (if exists)
      const existing = await svc.findExistingDraftRun({
        cutoffId: selectedCutoff.id,
        departmentId: config.departmentId,
        cutoffStart: selectedCutoff.start_date,
        cutoffEnd: selectedCutoff.end_date,
      });

      let activeRun = existing;

      // 2) If none, create DRAFT run
      if (!activeRun) {
        const refNo = svc.generatePayrollRefNo({
          cutoff: selectedCutoff,
          department: selectedDepartment,
        });

        activeRun = await svc.createDraftRun({
          cutoff: selectedCutoff,
          departmentId: config.departmentId,
          createdBy: 1, // TODO: replace with logged-in user id
          payrollRefNo: refNo,
        });
      }

      setRun(activeRun);

      // 3) Load workspace inputs for computation
      const workspace = await svc.loadWorkspace({
        cutoff: selectedCutoff,
        departmentId: config.departmentId,
      });

      setWs(workspace);

      // 4) Load persisted hold and posted status if this is an existing run
      if (activeRun && activeRun.payroll_run_id) {
        const persistedHold = await svc.loadPersistedHoldMap(activeRun.payroll_run_id);
        setHoldMap(persistedHold);

        // If the run is POSTED, load posted employees (on_hold != 1) for read-only display
        if (String(activeRun.status).toUpperCase() === "POSTED") {
          const posted = await svc.loadPostedEmployeesMap(activeRun.payroll_run_id);
          setPostedMap(posted);
        } else {
          setPostedMap(new Map());
        }
      } else {
        // New run - reset both maps
        setHoldMap(new Map());
        setPostedMap(new Map());
      }

      setStep(2);

    } catch (e: any) {
      toast.error(e?.message || "Failed to load payroll workspace");
    } finally {
      setLoadingWs(false);
    }
  }

  function toggleHold(userId: number) {
    setHoldMap((prev) => {
      const next = new Map(prev);
      next.set(userId, !Boolean(next.get(userId)));
      return next;
    });
  }

  async function processAndSave() {
    if (!run || !ws || !computed) return;

    try {
      setStep(3);

      // 1) Persist computed lines to payroll_run_employee
      await svc.saveLines({
        payrollRunId: run.payroll_run_id,
        cutoff: ws.cutoff,
        lines: computed.lines,
      });

      // 2) Persist header totals
      await svc.updateRunTotals({
        payrollRunId: run.payroll_run_id,
        summary: computed.summary,
      });

      setStep(4);
      toast.success("Payroll computed and saved (DRAFT lines).");
    } catch (e: any) {
      toast.error(e?.message || "Failed to process payroll");
      setStep(2);
    }
  }

  async function postPayroll() {
    if (!run) return;

    try {
      await svc.postRun({
        payrollRunId: run.payroll_run_id,
        postedBy: 1, // TODO: auth
      });

      // Optional (recommended): stamp DR payments as posted only when payroll is posted.
      if (ws && computed) {
        const employeeIds = computed.lines
          .map((x) => Number((x as any)?.user_id))
          .filter((x) => Number.isFinite(x) && x > 0);

        await svc.postDRPaymentsToPayroll({
          cutoff: ws.cutoff,
          payrollRefNo: run.payroll_ref_no,
          employeeIds,
        });
      }

      toast.success("Payroll POSTED successfully.");
      setRun((p) => (p ? { ...p, status: "POSTED" } : p));
    } catch (e: any) {
      toast.error(e?.message || "Failed to post payroll");
    }
  }

  const startOver = useCallback(() => {
    setConfig(DEFAULT_CONFIG);
    setRun(null);
    setWs(null);
    setHoldMap(new Map());
    setPostedMap(new Map());
    setStep(1);
  }, []);


  // ✅ When PayrollAdjustStep confirms leaving (Start Over), execute reset here.
  useEffect(() => {
    const handler = () => startOver();
    window.addEventListener("payroll-run:confirm-start-over", handler as any);
    return () =>
      window.removeEventListener(
        "payroll-run:confirm-start-over",
        handler as any,
      );
  }, [startOver]);

  const busy = loadingMaster || loadingWs || step === 3;
  const canPost = Boolean(run) && run?.status !== "POSTED" && step === 4;

  if (loadingMaster) {
    return (
      <DashboardLayout>
        <div className="mx-auto w-full max-w-7xl space-y-6 px-2 pb-10 sm:px-4">
          <Card className="p-6">
            <div className="space-y-4">
              <Skeleton className="h-8 w-[200px]" />
              <Skeleton className="h-4 w-[400px]" />
              <div className="flex gap-2 pt-2">
                 <Skeleton className="h-6 w-[80px] rounded-lg" />
                 <Skeleton className="h-6 w-[120px] rounded-lg" />
              </div>
            </div>
            <div className="flex justify-end pt-4">
               <Skeleton className="h-10 w-[120px]" />
            </div>
          </Card>
          
          <Card className="p-6">
              <div className="flex justify-between items-center mb-6">
                 <div className="space-y-2">
                    <Skeleton className="h-4 w-[100px]" />
                    <Skeleton className="h-3 w-[180px]" />
                 </div>
                 <div className="flex gap-2">
                    <Skeleton className="h-6 w-[100px] rounded-full" />
                    <Skeleton className="h-6 w-[100px] rounded-full" />
                 </div>
              </div>
              <div className="flex justify-between px-10">
                 <Skeleton className="h-10 w-10 rounded-full" />
                 <Skeleton className="h-10 w-10 rounded-full" />
                 <Skeleton className="h-10 w-10 rounded-full" />
                 <Skeleton className="h-10 w-10 rounded-full" />
              </div>
          </Card>

           <Card className="h-[400px] p-6">
              <div className="space-y-6">
                 <Skeleton className="h-10 w-full" />
                 <Skeleton className="h-[200px] w-full" />
              </div>
           </Card>
        </div>
      </DashboardLayout>
    )
  }

  return (
    <DashboardLayout>
      <div className="mx-auto w-full max-w-7xl space-y-6 px-2 pb-10 sm:px-4">
        {/* Header / Hero */}
        <Card className="relative overflow-hidden rounded-2xl border bg-card shadow-sm">
          <div className="pointer-events-none absolute inset-0 bg-gradient-to-br from-muted/60 via-transparent to-muted/30" />
          <div className="relative p-5 sm:p-6">
            <div className="flex flex-col gap-4 lg:flex-row lg:items-start lg:justify-between">
              <div className="space-y-2">
                <div className="flex flex-wrap items-center gap-2">
                  <h1 className="text-2xl font-semibold tracking-tight sm:text-3xl">
                    Payroll Run
                  </h1>

                  <span className="rounded-full border bg-background/60 px-2.5 py-1 text-xs text-muted-foreground">
                    {stepLabel(step)}
                  </span>

                  {run ? (
                    <span
                      className={[
                        "rounded-full border px-2.5 py-1 text-xs font-medium",
                        statusClasses(run.status),
                      ].join(" ")}
                      title="Payroll run status"
                    >
                      {String(run.status ?? "—")}
                    </span>
                  ) : null}
                </div>

                <p className="max-w-2xl text-sm text-muted-foreground">
                  Data-driven payroll register using Attendance, Holidays,
                  Manual Entries, and Wage Profiles.
                </p>

                {run ? (
                  <div className="flex flex-wrap gap-2 pt-1 text-xs text-muted-foreground">
                    <span className="rounded-lg border bg-background/70 px-2 py-1">
                      Ref:{" "}
                      <span className="font-mono text-foreground">
                        {run.payroll_ref_no}
                      </span>
                    </span>
                    {selectedCutoff ? (
                      <span className="rounded-lg border bg-background/70 px-2 py-1">
                        Cutoff:{" "}
                        <span className="font-medium text-foreground">
                          {formatCutoffLabel(selectedCutoff)}
                        </span>
                      </span>
                    ) : null}
                    <span className="rounded-lg border bg-background/70 px-2 py-1">
                      Department:{" "}
                      <span className="font-medium text-foreground">
                        {selectedDepartment ? selectedDepartment.name : "None selected"}
                      </span>
                    </span>
                  </div>
                ) : null}
              </div>

              <div className="flex flex-wrap items-center gap-2 lg:justify-end">
                <Button
                  variant="outline"
                  onClick={() => {
                    // ✅ Trigger shadcn AlertDialog when user is in Adjust step.
                    if (step === 2) {
                      window.dispatchEvent(
                        new CustomEvent("payroll-run:request-start-over"),
                      );
                      return;
                    }
                    startOver();
                  }}
                  disabled={busy}
                  className="gap-2"
                >
                  <RefreshCcw className="h-4 w-4" />
                  Start Over
                </Button>

                {step === 4 ? (
                  <Button
                    onClick={postPayroll}
                    disabled={!canPost}
                    className="gap-2"
                  >
                    <CheckCircle2 className="h-4 w-4" />
                    Post Payroll
                  </Button>
                ) : null}
              </div>
            </div>
          </div>
        </Card>

        {/* Stepper */}
        <Card className="rounded-2xl border bg-card p-4 shadow-sm sm:p-6">
          <div className="mb-4 flex items-center justify-between gap-3">
            <div className="space-y-0.5">
              <div className="text-sm font-semibold">Workflow</div>
              <div className="text-xs text-muted-foreground">
                Configure, adjust, compute, then review and post.
              </div>
            </div>

            <div className="hidden items-center gap-2 text-xs text-muted-foreground sm:flex">
              <span className="inline-flex items-center gap-1 rounded-full border bg-muted/30 px-2 py-1">
                <ClipboardCheck className="h-3.5 w-3.5" />
                Draft-safe
              </span>
              <span className="inline-flex items-center gap-1 rounded-full border bg-muted/30 px-2 py-1">
                <PlayCircle className="h-3.5 w-3.5" />
                Data-driven
              </span>
            </div>
          </div>

          <PayrollStepper activeStep={step} />
        </Card>

        {/* Password Dialog */}
        <PasswordDialog
          open={passwordDialogOpen}
          onOpenChange={setPasswordDialogOpen}
          onSubmit={handlePasswordSubmit}
        />

        {/* Step body */}
        <div className="space-y-6">
          {step === 1 ? (
            <Card className="rounded-2xl border bg-card shadow-sm">
              <div className="p-4 sm:p-6">
                <PayrollConfigStep
                  loading={loadingMaster || loadingWs}
                  config={config}
                  cutoffs={cutoffs}
                  departments={departments}
                  onChange={(patch) => setConfig((c) => ({ ...c, ...patch }))}
                  onNext={handleContinueClick}
                />
              </div>
            </Card>
          ) : null}

          {step === 2 && ws && computed ? (
            <Card className="rounded-2xl border bg-card shadow-sm">
              <div className="p-4 sm:p-6">
                <PayrollAdjustStep
                  cutoff={ws.cutoff}
                  department={ws.department}
                  run={run}
                  lines={computed.lines}
                  summary={computed.summary}
                  holdMap={holdMap}
                  postedMap={postedMap}
                  onToggleHold={toggleHold}
                  onRecompute={async () => {
                    try {
                      const updatedWorkspace = await svc.loadWorkspace({
                        cutoff: selectedCutoff!,
                        departmentId: config.departmentId,
                      });
                      setWs(updatedWorkspace);
                      toast.success("Payroll updated with latest adjustments.");
                    } catch (e: any) {
                      toast.error(
                        e?.message || "Failed to reload payroll data",
                      );
                    }
                  }}
                  onNext={processAndSave}
                />
              </div>
            </Card>
          ) : null}

          {step === 3 ? (
            <Card className="rounded-2xl border bg-card shadow-sm">
              <div className="p-4 sm:p-6">
                <PayrollProcessStep />
              </div>
            </Card>
          ) : null}

          {step === 4 && computed ? (
            <Card className="rounded-2xl border bg-card shadow-sm">
              <div className="p-4 sm:p-6">
                <PayrollReviewStep
                  run={run}
                  rows={computed.lines}
                  summary={computed.summary}
                  onBackToAdjust={() => setStep(2)}
                  onStartOver={startOver}
                  onPost={postPayroll}
                />
              </div>
            </Card>
          ) : null}
        </div>

        {/* Notes */}
        <Card className="rounded-2xl border bg-card shadow-sm">
          <div className="p-4 sm:p-6">
            <details className="group">
              <summary className="flex cursor-pointer list-none items-center justify-between gap-3">
                <div className="space-y-0.5">
                  <div className="text-sm font-semibold">Version notes</div>
                  <div className="text-xs text-muted-foreground">
                    Implementation details and current assumptions.
                  </div>
                </div>
                <span className="rounded-full border bg-muted/30 px-2.5 py-1 text-xs text-muted-foreground group-open:hidden">
                  Show
                </span>
                <span className="hidden rounded-full border bg-muted/30 px-2.5 py-1 text-xs text-muted-foreground group-open:inline-flex">
                  Hide
                </span>
              </summary>

              <div className="mt-4 rounded-xl border bg-muted/20 p-4">
                <ul className="list-disc space-y-2 pl-5 text-sm text-muted-foreground">
                  <li>
                    Holiday/Rest Day premiums follow your finalized rules
                    (Regular: entitled/worked; Special: +30%; Sunday: +30%).
                  </li>
                  <li>
                    Night differential uses placeholder logic until{" "}
                    <code className="rounded bg-background px-1 py-0.5 text-xs text-foreground">
                      attendance_approval.night_diff_minutes
                    </code>{" "}
                    exists.
                  </li>
                  <li>
                    Government contributions are manual values split 50/50 per
                    cutoff.
                  </li>
                  <li>
                    Shortage deductions are encoded in{" "}
                    <code className="rounded bg-background px-1 py-0.5 text-xs text-foreground">
                      payroll_other_deductions
                    </code>{" "}
                    (category=SHORTAGE).
                  </li>
                </ul>
              </div>
            </details>
          </div>
        </Card>
      </div>
    </DashboardLayout>
  );
}

// modules/payroll-run/components/AddEmployeeAdjustmentsDialog.tsx
"use client";

import * as React from "react";
import { toast } from "sonner";

import {
  createDRPayment,
  createOtherAddition,
  createOtherDeduction,
  createRetroPay,
  deleteDRPayment,
  deleteOtherAddition,
  deleteOtherDeduction,
  deleteRetroPay,
  updateDRPayment,
  updateOtherAddition,
  updateOtherDeduction,
  updateRetroPay,
  type PayrollOtherDeductionType,
} from "../providers/payrollAdjustmentsService";

import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogDescription,
} from "@/components/ui/dialog";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Label } from "@/components/ui/label";
import { Input } from "@/components/ui/input";
import { Textarea } from "@/components/ui/textarea";
import { Button } from "@/components/ui/button";
import { Separator } from "@/components/ui/separator";

import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";

type Kind = "ADDITION" | "DEDUCTION";
type DeductionTab = "MANUAL" | "SHORTAGE" | "DR_PAYMENT";
type AdditionTab = "MANUAL_ADDITION" | "RETRO_PAY";

// Extended entry with metadata for identifying source and ID during edit
export type ManualEntryExt = any & {
  id?: number | string;
  __source?: "ADD" | "DED" | "DR" | "RETRO";
  [k: string]: any;
};

function num(v: string) {
  const n = Number(
    String(v ?? "")
      .replaceAll(",", "")
      .trim(),
  );
  return Number.isFinite(n) ? n : 0;
}

function todayISO() {
  const d = new Date();
  const yyyy = d.getFullYear();
  const mm = String(d.getMonth() + 1).padStart(2, "0");
  const dd = String(d.getDate()).padStart(2, "0");
  return `${yyyy}-${mm}-${dd}`;
}

export function AddEmployeeAdjustmentsDialog({
  open,
  onOpenChange,
  userId,
  cutoffStart,
  cutoffEnd,
  createdBy,
  editingEntry,
  onSaved,
}: {
  open: boolean;
  onOpenChange: (v: boolean) => void;

  userId: number;
  cutoffStart: string;
  cutoffEnd: string;

  createdBy?: number | null;

  editingEntry?: ManualEntryExt | null;
  onSaved?: () => void;
}) {
  const [saving, setSaving] = React.useState(false);

  const [kind, setKind] = React.useState<Kind>("DEDUCTION");
  const [dedTab, setDedTab] = React.useState<DeductionTab>("MANUAL");
  const [addTab, setAddTab] = React.useState<AdditionTab>("MANUAL_ADDITION");

  // common/manual fields
  const [amount, setAmount] = React.useState<string>("");
  const [description, setDescription] = React.useState<string>("");

  // DR payment fields
  const [drNo, setDrNo] = React.useState<string>("");
  const [drPaymentDate, setDrPaymentDate] = React.useState<string>(todayISO());
  const [drAmountPaid, setDrAmountPaid] = React.useState<string>("");
  const [drRemarks, setDrRemarks] = React.useState<string>("");

  React.useEffect(() => {
    if (!open) return;

    if (editingEntry) {
      const src = (editingEntry as any)?.__source as
        | "ADD"
        | "DED"
        | "DR"
        | "RETRO"
        | undefined;

      if (src === "RETRO") {
        setKind("ADDITION");
        setAddTab("RETRO_PAY");
        setAmount(String(editingEntry.amount || ""));
        setDescription(editingEntry.description || "");
      } else if (src === "ADD") {
        setKind("ADDITION");
        setAddTab("MANUAL_ADDITION");
        setAmount(String(editingEntry.amount || ""));
        setDescription(editingEntry.description || "");
      } else if (src === "DR") {
        setKind("DEDUCTION");
        setDedTab("DR_PAYMENT");
        setDrNo(editingEntry.delivery_receipt_number || "");
        setDrPaymentDate(editingEntry.payment_date || todayISO());
        setDrAmountPaid(String(editingEntry.amount_paid || ""));
        setDrRemarks(editingEntry.remarks || "");
      } else if (src === "DED") {
        setKind("DEDUCTION");
        setDedTab(editingEntry.type || "MANUAL");
        setAmount(String(editingEntry.amount || ""));
        setDescription(editingEntry.description || "");
      } else {
        setSaving(false);
        setKind("DEDUCTION");
        setDedTab("MANUAL");
        setAddTab("MANUAL_ADDITION");
        setAmount("");
        setDescription("");
        setDrNo("");
        setDrPaymentDate(todayISO());
        setDrAmountPaid("");
        setDrRemarks("");
      }
    } else {
      setSaving(false);
      setKind("DEDUCTION");
      setDedTab("MANUAL");
      setAddTab("MANUAL_ADDITION");
      setAmount("");
      setDescription("");

      setDrNo("");
      setDrPaymentDate(todayISO());
      setDrAmountPaid("");
      setDrRemarks("");
    }
  }, [open, editingEntry]);

  async function handleSave(e: React.MouseEvent) {
    e.preventDefault();
    if (saving) return;

    try {
      setSaving(true);

      const entryId = (editingEntry as any)?.id as number | undefined;
      const entrySource = (editingEntry as any)?.__source as
        | "ADD"
        | "DED"
        | "DR"
        | "RETRO"
        | undefined;

      const isEditing = Boolean(editingEntry && entryId && entrySource);

      if (kind === "ADDITION") {
        const amt = num(amount);
        if (amt <= 0) throw new Error("Amount must be greater than 0.");

        // ✅ Retro Pay goes to retro_pay table
        if (addTab === "RETRO_PAY") {
          if (isEditing && entrySource === "RETRO") {
            await updateRetroPay(entryId!, {
              amount: amt,
              description: description.trim() || null,
              created_by: createdBy ?? null,
            });
            toast.success("Retro Pay updated.");
          } else {
            await createRetroPay({
              user_id: userId,
              amount: amt,
              description: description.trim() || null,
              cutoff_start: cutoffStart,
              cutoff_end: cutoffEnd,
              created_by: createdBy ?? null,
            });
            toast.success("Retro Pay saved.");
          }

          onSaved?.();
          onOpenChange(false);
          return;
        }

        // ✅ Normal manual addition goes to payroll_other_additions
        if (isEditing && entrySource === "ADD") {
          await updateOtherAddition(entryId!, {
            amount: amt,
            description: description.trim() || null,
            created_by: createdBy ?? null,
          });
          toast.success("Addition updated.");
        } else {
          await createOtherAddition({
            user_id: userId,
            amount: amt,
            description: description.trim() || null,
            cutoff_start: cutoffStart,
            cutoff_end: cutoffEnd,
            created_by: createdBy ?? null,
          });
          toast.success("Addition saved.");
        }

        onSaved?.();
        onOpenChange(false);
        return;
      }

      // kind === DEDUCTION
      if (dedTab === "DR_PAYMENT") {
        const paid = num(drAmountPaid);
        if (!drNo.trim()) throw new Error("Delivery Receipt No. is required.");
        if (!drPaymentDate.trim()) throw new Error("Payment Date is required.");
        if (paid <= 0) throw new Error("Amount Paid must be greater than 0.");

        if (isEditing && entrySource === "DR") {
          await updateDRPayment(entryId!, {
            delivery_receipt_number: drNo.trim(),
            payment_date: drPaymentDate,
            amount_paid: paid,
            remarks: drRemarks.trim() || null,
            created_by: createdBy ?? null,
          });
          toast.success("Stock purchase (DR Payment) updated.");
        } else {
          await createDRPayment({
            employee_id: userId,
            cutoff_from: cutoffStart,
            cutoff_to: cutoffEnd,
            delivery_receipt_number: drNo.trim(),
            payment_date: drPaymentDate,
            amount_paid: paid,
            payment_method: "PAYROLL_DEDUCTION",
            remarks: drRemarks.trim() || null,
            created_by: createdBy ?? null,
          });
          toast.success("Stock purchase (DR Payment) saved.");
        }

        onSaved?.();
        onOpenChange(false);
        return;
      }

      // Manual / Shortage -> payroll_other_deductions
      const amt = num(amount);
      if (amt <= 0) throw new Error("Amount must be greater than 0.");

      const t: PayrollOtherDeductionType = dedTab;

      if (isEditing && entrySource === "DED") {
        await updateOtherDeduction(entryId!, {
          amount: amt,
          type: t,
          description: description.trim() || null,
          created_by: createdBy ?? null,
        });
        toast.success("Deduction updated.");
      } else {
        await createOtherDeduction({
          user_id: userId,
          amount: amt,
          type: t,
          description: description.trim() || null,
          cutoff_start: cutoffStart,
          cutoff_end: cutoffEnd,
          created_by: createdBy ?? null,
        });
        toast.success("Deduction saved.");
      }

      onSaved?.();
      onOpenChange(false);
    } catch (err: any) {
      toast.error(err?.message || "Failed to save adjustment.");
    } finally {
      setSaving(false);
    }
  }

  return (
    <Dialog modal={false} open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[640px]">
        <DialogHeader>
          <DialogTitle>
            {editingEntry ? "Edit Adjustment" : "Add Adjustment"}
          </DialogTitle>
          <DialogDescription>
            Saved to the database for the selected employee and cutoff.
          </DialogDescription>
        </DialogHeader>

        <div className="space-y-5">
          {/* KIND */}
          <div className="space-y-2">
            <Label>Kind</Label>
            <Select value={kind} onValueChange={(v) => setKind(v as Kind)}>
              <SelectTrigger>
                <SelectValue placeholder="Select kind" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="DEDUCTION">Deduction</SelectItem>
                <SelectItem value="ADDITION">Addition</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {kind === "ADDITION" ? (
            <>
              <div className="space-y-2">
                <Label>Addition Category</Label>

                <Tabs
                  value={addTab}
                  onValueChange={(v) => setAddTab(v as AdditionTab)}
                >
                  <TabsList className="grid w-full grid-cols-2">
                    <TabsTrigger value="MANUAL_ADDITION">
                      Manual Addition
                    </TabsTrigger>
                    <TabsTrigger value="RETRO_PAY">Retro Pay</TabsTrigger>
                  </TabsList>

                  <TabsContent
                    value="MANUAL_ADDITION"
                    className="mt-4 space-y-4"
                  >
                    <div className="space-y-2">
                      <Label>Amount</Label>
                      <Input
                        inputMode="decimal"
                        placeholder="0.00"
                        value={amount}
                        onChange={(e) => setAmount(e.target.value)}
                      />
                    </div>

                    <div className="space-y-2">
                      <Label>Description</Label>
                      <Textarea
                        placeholder="Optional notes / reference"
                        value={description}
                        onChange={(e) => setDescription(e.target.value)}
                      />
                    </div>
                  </TabsContent>

                  <TabsContent value="RETRO_PAY" className="mt-4 space-y-4">
                    <div className="rounded-lg border bg-muted/20 p-3 text-xs text-muted-foreground">
                      This will create a row in <code>retro_pay</code> and will
                      be included in payroll computation for this cutoff.
                    </div>

                    <div className="space-y-2">
                      <Label>Retro Amount</Label>
                      <Input
                        inputMode="decimal"
                        placeholder="0.00"
                        value={amount}
                        onChange={(e) => setAmount(e.target.value)}
                      />
                    </div>

                    <div className="space-y-2">
                      <Label>Description</Label>
                      <Textarea
                        placeholder="Optional notes / reference"
                        value={description}
                        onChange={(e) => setDescription(e.target.value)}
                      />
                    </div>
                  </TabsContent>
                </Tabs>
              </div>
            </>
          ) : (
            <>
              {/* DEDUCTION TABS */}
              <div className="space-y-2">
                <Label>Deduction Category</Label>

                <Tabs
                  value={dedTab}
                  onValueChange={(v) => setDedTab(v as DeductionTab)}
                >
                  <TabsList className="grid w-full grid-cols-3">
                    <TabsTrigger value="MANUAL">Manual</TabsTrigger>
                    <TabsTrigger value="SHORTAGE">Shortage</TabsTrigger>
                    <TabsTrigger value="DR_PAYMENT">Stock Purchase</TabsTrigger>
                  </TabsList>

                  <TabsContent value="MANUAL" className="mt-4 space-y-4">
                    <div className="space-y-2">
                      <Label>Amount</Label>
                      <Input
                        inputMode="decimal"
                        placeholder="0.00"
                        value={amount}
                        onChange={(e) => setAmount(e.target.value)}
                      />
                    </div>

                    <div className="space-y-2">
                      <Label>Description</Label>
                      <Textarea
                        placeholder="Optional notes / reference"
                        value={description}
                        onChange={(e) => setDescription(e.target.value)}
                      />
                    </div>
                  </TabsContent>

                  <TabsContent value="SHORTAGE" className="mt-4 space-y-4">
                    <div className="space-y-2">
                      <Label>Amount</Label>
                      <Input
                        inputMode="decimal"
                        placeholder="0.00"
                        value={amount}
                        onChange={(e) => setAmount(e.target.value)}
                      />
                    </div>

                    <div className="space-y-2">
                      <Label>Description</Label>
                      <Textarea
                        placeholder="Optional notes / reference"
                        value={description}
                        onChange={(e) => setDescription(e.target.value)}
                      />
                    </div>
                  </TabsContent>

                  {/* DR PAYMENT FIELDS */}
                  <TabsContent value="DR_PAYMENT" className="mt-4 space-y-4">
                    <div className="rounded-lg border bg-muted/20 p-3 text-xs text-muted-foreground">
                      This will create a row in <code>dr_payment</code> with
                      payment_method set to <code>PAYROLL_DEDUCTION</code>, and
                      will be included in payroll computation for this cutoff.
                    </div>

                    <div className="grid grid-cols-1 gap-4 sm:grid-cols-2">
                      <div className="space-y-2">
                        <Label>Delivery Receipt No.</Label>
                        <Input
                          placeholder="e.g. DAW12312"
                          value={drNo}
                          onChange={(e) => setDrNo(e.target.value)}
                        />
                      </div>

                      <div className="space-y-2">
                        <Label>Payment Date</Label>
                        <Input
                          type="date"
                          value={drPaymentDate}
                          onChange={(e) => setDrPaymentDate(e.target.value)}
                        />
                      </div>

                      <div className="space-y-2">
                        <Label>Amount Paid</Label>
                        <Input
                          inputMode="decimal"
                          placeholder="0.00"
                          value={drAmountPaid}
                          onChange={(e) => setDrAmountPaid(e.target.value)}
                        />
                      </div>

                      <div className="space-y-2">
                        <Label>Payment Method</Label>
                        <Input value="PAYROLL_DEDUCTION" disabled />
                      </div>
                    </div>

                    <div className="space-y-2">
                      <Label>Remarks</Label>
                      <Textarea
                        placeholder="Optional remarks"
                        value={drRemarks}
                        onChange={(e) => setDrRemarks(e.target.value)}
                      />
                    </div>
                  </TabsContent>
                </Tabs>
              </div>
            </>
          )}

          <Separator />

          <div className="flex items-center justify-end gap-2">
            <Button
              variant="outline"
              onClick={(e) => {
                e.preventDefault();
                onOpenChange(false);
              }}
              disabled={saving}
            >
              Cancel
            </Button>

            <Button onClick={handleSave} disabled={saving}>
              {saving ? "Saving..." : editingEntry ? "Update" : "Save"}
            </Button>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

