                      </div>

                      <div className="px-4">
                        {allDeductionEntries.length === 0 ? (
                          <div className="py-3 text-sm text-muted-foreground">
                            No deductions.
                          </div>
                        ) : (
                          <div>
                            {allDeductionEntries.map((e) => (
                              <MinimalAdjustmentRow
                                key={`ded-flat-${safeId(e)}-${entryDesc(e as any)}`}
                                entry={e}
                                onEdit={onEditEntry}
                                onDelete={onDeleteEntry}
                              />
                            ))}
                          </div>
                        )}
                      </div>

                      <div className="flex items-center justify-between border-t px-4 py-2">
                        <span className="text-xs font-semibold uppercase tracking-wide text-muted-foreground">
                          Total Deductions
                        </span>
                        <span className="font-mono text-sm font-bold text-destructive">
                          {formatPHP(deductionsAdjTotal)}
                        </span>
                      </div>
                    </div>
                  </div>
                </TabsContent>
              </Tabs>
            </div>
          </div>

          {/* Footer */}
          <div className="border-t bg-background px-6 py-4">
            <div className="flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
              <div className="text-sm text-muted-foreground">
                Totals:{" "}
                <span className="font-mono font-semibold">
                  Gross {totalsGross}
                </span>{" "}
                •{" "}
                <span className="font-mono font-semibold text-destructive">
                  Deductions {totalsDed}
                </span>{" "}
                •{" "}
                <span className="font-mono font-semibold">Net {totalsNet}</span>
              </div>

              <div className="flex items-center justify-end gap-2">
                <Button variant="outline" onClick={() => onOpenChange(false)}>
                  Close
                </Button>
                <Button
                  variant="secondary"
                  onClick={(e) => {
                    e.preventDefault();
                    e.stopPropagation();
                    openAdjust();
                  }}
                  disabled={!line}
                >
                  <Plus className="mr-2 h-4 w-4" />
                  Add Adjustment
                </Button>
              </div>
            </div>
          </div>
        </div>
      </DialogContent>
    </Dialog>
  );
}

export default EmployeeDetailsSheet;

