import { useState, useMemo, useEffect } from "react";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogHeader,
  DialogTitle,
  DialogFooter,
  DialogDescription,
} from "@/components/ui/dialog";
import {
  Popover,
  PopoverContent,
  PopoverTrigger,
} from "@/components/ui/popover";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { Check, ChevronsUpDown } from "lucide-react";
import { cn } from "@/lib/utils";
import { Employee, RetroFormState } from "../types";

interface RetroModalProps {
  open: boolean;
  onOpenChange: (open: boolean) => void;
  isEditing: boolean;
  initialData?: RetroFormState;
  employees: Employee[];
  onSubmit: (data: RetroFormState) => void;
}

export default function RetroModal({
  open,
  onOpenChange,
  isEditing,
  initialData,
  employees,
  onSubmit,
}: RetroModalProps) {
  const [form, setForm] = useState<RetroFormState>({
    user_id: "",
    amount: "",
    description: "",
    cutoff_start: "",
    cutoff_end: "",
  });

  const [employeeDropdownOpen, setEmployeeDropdownOpen] = useState(false);
  const [employeeSearchTerm, setEmployeeSearchTerm] = useState("");

  // Reset or populate form when dialog opens/closes
  useEffect(() => {
    if (open && initialData) {
      setForm(initialData);
    } else if (!open) {
      setForm({
        user_id: "",
        amount: "",
        description: "",
        cutoff_start: "",
        cutoff_end: "",
      });
      setEmployeeSearchTerm("");
    }
  }, [open, initialData]);

  // Helper to format employee name
  const getEmployeeName = (id: string) => {
    const emp = employees.find((e) => String(e.user_id) === id);
    if (!emp) return "Select Employee";
    return `${emp.user_fname} ${emp.user_mname ? emp.user_mname + " " : ""}${
      emp.user_lname
    }`;
  };

  // Filter employees for dropdown
  const filteredEmployees = useMemo(() => {
    const q = employeeSearchTerm.trim().toLowerCase();
    if (!q) return employees;
    return employees.filter((emp) => {
      const name = `${emp.user_fname} ${
        emp.user_mname ? emp.user_mname + " " : ""
      }${emp.user_lname}`.toLowerCase();
      return (
        String(emp.user_id).includes(q) ||
        name.includes(q) ||
        (emp.user_email || "").toLowerCase().includes(q)
      );
    });
  }, [employees, employeeSearchTerm]);

  return (
    <Dialog open={open} onOpenChange={onOpenChange}>
      <DialogContent className="sm:max-w-[500px]">
        <DialogHeader>
          <DialogTitle>
            {isEditing ? "Edit Retro Pay" : "Add New Retro Pay"}
          </DialogTitle>
          <DialogDescription>
            {isEditing
              ? "Modify the details of this retroactive payment."
              : "Create a new retroactive payment record for an employee."}
          </DialogDescription>
        </DialogHeader>

        <div className="grid gap-6 py-4">
          {/* Employee Selector */}
          <div className="grid gap-2">
            <Label>Employee</Label>
            <Popover
              open={employeeDropdownOpen}
              onOpenChange={setEmployeeDropdownOpen}
            >
              <PopoverTrigger asChild>
                <Button
                  variant="outline"
                  role="combobox"
                  className={cn(
                    "w-full justify-between",
                    !form.user_id && "text-muted-foreground"
                  )}
                >
                  {form.user_id
                    ? getEmployeeName(form.user_id)
                    : "Select employee..."}
                  <ChevronsUpDown className="ml-2 h-4 w-4 shrink-0 opacity-50" />
                </Button>
              </PopoverTrigger>
              <PopoverContent className="w-[460px] p-0" align="start">
                <div className="p-2 border-b">
                  <Input
                    placeholder="Search by name or ID..."
                    value={employeeSearchTerm}
                    onChange={(e) => setEmployeeSearchTerm(e.target.value)}
                    className="h-8"
                  />
                </div>
                <div className="max-h-[300px] overflow-y-auto p-1">
                  {filteredEmployees.length === 0 ? (
                    <div className="py-6 text-center text-sm text-muted-foreground">
                      No employees found.
                    </div>
                  ) : (
                    filteredEmployees.map((emp) => (
                      <div
                        key={emp.user_id}
                        className={cn(
                          "relative flex cursor-default select-none items-center rounded-sm px-2 py-2 text-sm outline-none hover:bg-accent hover:text-accent-foreground",
                          String(emp.user_id) === form.user_id && "bg-accent"
                        )}
                        onClick={() => {
                          setForm((prev) => ({
                            ...prev,
                            user_id: String(emp.user_id),
                          }));
                          setEmployeeDropdownOpen(false);
                          setEmployeeSearchTerm("");
                        }}
                      >
                        <div className="flex flex-col">
                          <span className="font-medium">
                            {emp.user_fname} {emp.user_mname} {emp.user_lname}
                          </span>
                          <span className="text-xs text-muted-foreground">
                            ID: {emp.user_id} • {emp.user_email}
                          </span>
                        </div>
                        {String(emp.user_id) === form.user_id && (
                          <Check className="ml-auto h-4 w-4 opacity-100" />
                        )}
                      </div>
                    ))
                  )}
                </div>
              </PopoverContent>
            </Popover>
          </div>

          <div className="grid grid-cols-2 gap-4">
            {/* Amount */}
            <div className="grid gap-2">
              <Label htmlFor="amount">Amount</Label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-muted-foreground font-medium">
                  ₱
                </span>
                <Input
                  id="amount"
                  type="number"
                  step="0.01"
                  placeholder="0.00"
                  value={form.amount}
                  onChange={(e) =>
                    setForm((p) => ({ ...p, amount: e.target.value }))
                  }
                  className="pl-7 font-mono"
                />
              </div>
            </div>
            {/* Description */}
            <div className="grid gap-2">
              <Label htmlFor="description">Description (Optional)</Label>
              <Input
                id="description"
                placeholder="e.g. Adjustment for March"
                value={form.description}
                onChange={(e) =>
                  setForm((p) => ({ ...p, description: e.target.value }))
                }
              />
            </div>
          </div>

          {/* Dates */}
          <div className="grid grid-cols-2 gap-4">
            <div className="grid gap-2">
              <Label htmlFor="cutoff_start">Cutoff Start</Label>
              <Input
                id="cutoff_start"
                type="date"
                className="w-full block"
                value={form.cutoff_start}
                onChange={(e) =>
                  setForm((p) => ({ ...p, cutoff_start: e.target.value }))
                }
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="cutoff_end">Cutoff End</Label>
              <Input
                id="cutoff_end"
                type="date"
                className="w-full block"
                value={form.cutoff_end}
                onChange={(e) =>
                  setForm((p) => ({ ...p, cutoff_end: e.target.value }))
                }
              />
            </div>
          </div>
        </div>

        <DialogFooter className="gap-2 sm:gap-0">
          <Button variant="outline" onClick={() => onOpenChange(false)}>
            Cancel
          </Button>
          <Button onClick={() => onSubmit(form)}>
            {isEditing ? "Save Changes" : "Create Record"}
          </Button>
        </DialogFooter>
      </DialogContent>
    </Dialog>
  );
}

import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import {
  AlertDialog,
  AlertDialogAction,
  AlertDialogCancel,
  AlertDialogContent,
  AlertDialogDescription,
  AlertDialogFooter,
  AlertDialogHeader,
  AlertDialogTitle,
} from "@/components/ui/alert-dialog";
import { Button } from "@/components/ui/button";
import {
  ChevronLeft,
  ChevronRight,
  ArrowUpDown,
  Pencil,
  Trash2,
} from "lucide-react";
import { Employee, RetroPayFromApi, SortConfig } from "../types";
import { useState } from "react";
import { RetroTableSkeleton } from "./RetroTableSkeleton";

interface RetroTableProps {
  data: RetroPayFromApi[];
  loading: boolean;
  refreshing: boolean;
  employees: Employee[];
  pagination: {
    currentPage: number;
    totalPages: number;
    rowsPerPage: number;
    onPageChange: (page: number) => void;
    onRowsPerPageChange: (rows: number) => void;
    getPageButtons: () => (number | string)[];
  };
  sorting: {
    sortConfig: SortConfig;
    onSort: (key: string) => void;
  };
  onEdit: (retro: RetroPayFromApi) => void;
  onDelete: (retro: RetroPayFromApi) => void;
}

export default function RetroTable({
  data,
  loading,
  refreshing,
  employees,
  pagination,
  sorting,
  onEdit,
  onDelete,
}: RetroTableProps) {
  const [deleteId, setDeleteId] = useState<number | null>(null);
  const [retroToDelete, setRetroToDelete] = useState<RetroPayFromApi | null>(
    null
  );

  const formatEmployeeName = (maybeUser: number | Employee | undefined) => {
    if (!maybeUser && maybeUser !== 0) return "Unknown";
    if (typeof maybeUser === "number") {
      const emp = employees.find((e) => e.user_id === maybeUser);
      if (!emp) return `ID ${maybeUser}`;
      return `${emp.user_fname} ${emp.user_mname ? emp.user_mname + " " : ""}${
        emp.user_lname
      }`;
    } else {
      return `${maybeUser.user_fname} ${
        maybeUser.user_mname ? maybeUser.user_mname + " " : ""
      }${maybeUser.user_lname}`;
    }
  };

  const formatCurrency = (val?: string) => {
    const num = parseFloat(val || "0");
    return Number.isNaN(num)
      ? "₱0.00"
      : `₱${num.toLocaleString("en-US", { minimumFractionDigits: 2 })}`;
  };

  const formatDate = (dateStr?: string) => {
    if (!dateStr) return "-";
    const d = new Date(dateStr);
    return isNaN(d.getTime())
      ? dateStr
      : d.toLocaleDateString("en-US", {
          year: "numeric",
          month: "short",
          day: "numeric",
        });
  };

  const { sortConfig, onSort } = sorting;

  const confirmDelete = (retro: RetroPayFromApi) => {
    setDeleteId(retro.retro_id);
    setRetroToDelete(retro);
  };

  const executeDelete = () => {
    if (retroToDelete) {
      onDelete(retroToDelete);
      setDeleteId(null);
      setRetroToDelete(null);
    }
  };

  return (
    <div className="w-full">
      <div className="border rounded-md overflow-hidden">
        <Table>
          <TableHeader className="bg-gray-50 dark:bg-gray-800">
            <TableRow>
              <TableHead className="w-[60px] font-semibold text-gray-700">
                No.
              </TableHead>
              <TableHead
                className="cursor-pointer"
                onClick={() => onSort("name")}
              >
                <div className="flex items-center gap-2 font-semibold text-gray-700">
                  Name
                  <ArrowUpDown className="h-3 w-3" />
                </div>
              </TableHead>
              <TableHead
                className="cursor-pointer"
                onClick={() => onSort("amount")}
              >
                <div className="flex items-center gap-2 font-semibold text-gray-700">
                  Amount
                  <ArrowUpDown className="h-3 w-3" />
                </div>
              </TableHead>
              <TableHead className="font-semibold text-gray-700">
                Description
              </TableHead>
              <TableHead
                className="cursor-pointer"
                onClick={() => onSort("cutoff_start")}
              >
                <div className="flex items-center gap-2 font-semibold text-gray-700">
                  Cut Off
                  <ArrowUpDown className="h-3 w-3" />
                </div>
              </TableHead>
              <TableHead className="font-semibold text-gray-700">
                Action
              </TableHead>
            </TableRow>
          </TableHeader>

          <TableBody>
            {loading ? (
              <RetroTableSkeleton />
            ) : data.length === 0 ? (
              <TableRow>
                <TableCell
                  colSpan={6}
                  className="h-24 text-center text-muted-foreground"
                >
                  No records found
                </TableCell>
              </TableRow>
            ) : (
              data.map((retro, idx) => (
                <TableRow key={retro.retro_id} className="hover:bg-gray-50/50">
                  <TableCell className="font-medium text-gray-600">
                    {(pagination.currentPage - 1) * pagination.rowsPerPage +
                      idx +
                      1}
                  </TableCell>
                  <TableCell className="font-medium text-gray-900">
                    {formatEmployeeName(retro.user_id)}
                  </TableCell>
                  <TableCell className="font-medium text-gray-700">
                    {formatCurrency(retro.amount)}
                  </TableCell>
                  <TableCell className="text-gray-600">
                    {retro.description || "-"}
                  </TableCell>
                  <TableCell className="text-gray-600 text-sm">
                    {formatDate(retro.cutoff_start)} -{" "}
                    {formatDate(retro.cutoff_end)}
                  </TableCell>
                  <TableCell>
                    <div className="flex items-center gap-2">
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-8 w-8 text-blue-600 hover:text-blue-700 hover:bg-blue-50"
                        onClick={() => onEdit(retro)}
                      >
                        <Pencil className="h-4 w-4" />
                      </Button>
                      <Button
                        variant="ghost"
                        size="icon"
                        className="h-8 w-8 text-red-600 hover:text-red-700 hover:bg-red-50"
                        onClick={() => confirmDelete(retro)}
                      >
                        <Trash2 className="h-4 w-4" />
                      </Button>
                    </div>
                  </TableCell>
                </TableRow>
              ))
            )}
          </TableBody>
        </Table>
      </div>

      {/* Pagination Footer - Left Text / Right Buttons */}
      <div className="flex items-center justify-between py-4">
        <div className="text-sm text-muted-foreground">
          Showing {(pagination.currentPage - 1) * pagination.rowsPerPage + 1} to{" "}
          {Math.min(
            pagination.currentPage * pagination.rowsPerPage,
            pagination.totalPages * pagination.rowsPerPage
          )}{" "}
          of {pagination.totalPages * pagination.rowsPerPage} entries
          {/* Note: Ideally we want totalRecords count from API, here approximated via pages for UI */}
        </div>

        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => pagination.onPageChange(pagination.currentPage - 1)}
            disabled={pagination.currentPage === 1}
          >
            Prev
          </Button>
          <div className="text-sm font-medium px-2">
            Page {pagination.currentPage} / {pagination.totalPages}
          </div>
          <Button
            variant="outline"
            size="sm"
            onClick={() => pagination.onPageChange(pagination.currentPage + 1)}
            disabled={pagination.currentPage === pagination.totalPages}
          >
            Next
          </Button>
        </div>
      </div>

      {/* Alert Dialog */}
      <AlertDialog
        open={!!deleteId}
        onOpenChange={(open) => !open && setDeleteId(null)}
      >
        <AlertDialogContent>
          <AlertDialogHeader>
            <AlertDialogTitle>Are you sure?</AlertDialogTitle>
            <AlertDialogDescription>
              This will permanently delete this retro pay record.
            </AlertDialogDescription>
          </AlertDialogHeader>
          <AlertDialogFooter>
            <AlertDialogCancel onClick={() => setDeleteId(null)}>
              Cancel
            </AlertDialogCancel>
            <AlertDialogAction
              className="bg-red-600 hover:bg-red-700 text-white"
              onClick={executeDelete}
            >
              Delete
            </AlertDialogAction>
          </AlertDialogFooter>
        </AlertDialogContent>
      </AlertDialog>
    </div>
  );
}

"use client";

import React, { useEffect, useState, useCallback, useMemo } from 'react';
import DashboardLayout from '@/components/layout/DashboardLayout';
import { 
  fetchWageMatrixData, 
  upsertWageMatrix,
  patchWageMatrixBulk 
} from './providers/wage-matrixApi';
import { 
  LogisticsArea, 
  LogisticsStaff, 
  LogisticsVehicleType, 
  SalaryMatrix, 
  WageMatrixData 
} from './types';
import { toast } from "sonner";
import { 
  Save, 
  RefreshCcw, 
  Search, 
  Truck, 
  UserCircle, 
  ShieldCheck, 
  AlertCircle,
  Clock,
  ChevronDown,
  LayoutGrid
} from 'lucide-react';

import { 
  Table, 
  TableBody, 
  TableCell, 
  TableHead, 
  TableHeader, 
  TableRow 
} from "@/components/ui/table";
import { Button } from "@/components/ui/button";
