import { Badge } from "@/components/ui/badge";
import { Separator } from "@/components/ui/separator";
import { Skeleton } from "@/components/ui/skeleton";
import { 
  Card, 
  CardContent, 
  CardDescription, 
  CardHeader, 
  CardTitle 
} from "@/components/ui/card";

// Mapping Configuration
const COLUMN_MAP = [
  { key: 'driver_below_10w', label: 'Below 10W', group: 'Fleet Operator', role: 'Driver', vehicleType: 'BELOW 10 WHEELER' },
  { key: 'driver_10_wheeler', label: '10 Wheeler', group: 'Fleet Operator', role: 'Driver', vehicleType: '10 WHEELER' },
  { key: 'driver_trailer', label: 'Trailer', group: 'Fleet Operator', role: 'Driver', vehicleType: 'TRAILER' },
  { key: 'helper_extra', label: 'Extra', group: 'Helper', role: 'Helper', employmentType: 'EXTRA' },
  { key: 'helper_probationary', label: 'Probationary', group: 'Helper', role: 'Helper', employmentType: 'PROBATIONARY' },
  { key: 'logistics_regular_lt_10w', label: 'Regular (<10W)', group: 'Logistics Crew', role: 'Helper', employmentType: 'REGULAR(<10W)' },
  { key: 'logistics_regular_10w_t', label: 'Regular (10W/T)', group: 'Logistics Crew', role: 'Helper', employmentType: 'REGULAR(10W/T)' },
];

const LOCAL_STORAGE_KEY = 'wage_matrix_draft_v2';

export default function WageMatrixModule() {
  const [data, setData] = useState<WageMatrixData | null>(null);
  const [loading, setLoading] = useState(true);
  const [saving, setSaving] = useState(false);
  const [searchTerm, setSearchTerm] = useState("");
  const [draft, setDraft] = useState<Record<string, string>>({}); // Key: areaId_colKey
  const [lastUpdated, setLastUpdated] = useState<string | null>(null);

  const loadData = useCallback(async () => {
    setLoading(true);
    try {
      const res = await fetchWageMatrixData();
      setData(res);

      // Initialize draft from matrix data
      const initialDraft: Record<string, string> = {};
      res.matrix.forEach(item => {
        // Find which column this item belongs to
        const staff = res.staff.find(s => s.staff_id === item.staff_id);
        const vt = res.vehicleTypes.find(v => v.vehicle_type_id === item.vehicle_type_id);

        const col = COLUMN_MAP.find(c => {
          const matchesStaff = staff?.role === c.role && (c.employmentType ? staff?.employment_type === c.employmentType : true);
          // For drivers, we match vehicle type. For others, we expect 'N/A' or nothing.
          const matchesVT = c.vehicleType ? vt?.vehicle_type === c.vehicleType : (vt?.vehicle_type === 'N/A' || !vt);
          return matchesStaff && matchesVT;
        });

        if (col) {
          const key = `${item.area_id}_${col.key}`;
          initialDraft[key] = item.wage_amount.toString();
        }
      });

      // Merge with localStorage if exists
      const savedDraft = localStorage.getItem(LOCAL_STORAGE_KEY);
      if (savedDraft) {
        try {
          const parsed = JSON.parse(savedDraft);
          Object.assign(initialDraft, parsed);
          toast.info("Unsaved changes restored from cache.");
        } catch (e) {
          console.error("Failed to parse local storage", e);
        }
      }

      setDraft(initialDraft);

      // Check for 'N/A' vehicle type
      const hasNA = res.vehicleTypes.some(vt => vt.vehicle_type === 'N/A');
      if (!hasNA) {
        toast.warning("Vehicle Type 'N/A' is missing. Please add it in Compensation Settings to avoid save errors.");
      }
    } catch (error) {
      console.error(error);
      toast.error("Failed to load wage matrix data.");
    } finally {
      setLoading(false);
    }
  }, []);

  useEffect(() => {
    loadData();
  }, [loadData]);

  // Auto-save draft to localStorage
  useEffect(() => {
    if (Object.keys(draft).length > 0) {
      localStorage.setItem(LOCAL_STORAGE_KEY, JSON.stringify(draft));
    }
  }, [draft]);

  const handleInputChange = (areaId: number, colKey: string, value: string) => {
    const key = `${areaId}_${colKey}`;
    setDraft(prev => ({ ...prev, [key]: value }));
  };

  const handleSave = async () => {
    if (!data) return;
    setSaving(true);
    try {
      const updates: SalaryMatrix[] = [];
      const creates: SalaryMatrix[] = [];

      // Construct payload from draft
      Object.entries(draft).forEach(([key, value]) => {
        const [areaIdStr, colKey] = key.split('_');
        const areaId = Number(areaIdStr);
        const amount = parseFloat(value);
        if (isNaN(amount)) return;

        const colConfig = COLUMN_MAP.find(c => c.key === colKey);
        const staff = staffByColumn[colKey];
        if (!staff || !colConfig) return;

        const vtId = getVehicleTypeId(colConfig.vehicleType);

        const existing = data.matrix.find(m => 
          m.area_id === areaId && 
          m.staff_id === staff.staff_id && 
          m.vehicle_type_id === vtId
        );

        const record = {
          area_id: areaId,
          staff_id: staff.staff_id,
          vehicle_type_id: vtId,
          wage_amount: amount
        };

        if (existing?.id) {
          if (existing.wage_amount !== amount) {
            updates.push({ ...record, id: existing.id });
          }
        } else {
          creates.push(record);
        }
      });

      // Execute promises in parallel
      const promises = [];
      if (updates.length > 0) promises.push(patchWageMatrixBulk(updates));
      if (creates.length > 0) promises.push(upsertWageMatrix(creates));

      if (promises.length > 0) {
        await Promise.all(promises);
        toast.success(`Matrix saved: ${updates.length} updated, ${creates.length} created.`);
      } else {
        toast.info("No changes to save.");
      }

      localStorage.removeItem(LOCAL_STORAGE_KEY);
      setLastUpdated(new Date().toLocaleTimeString());
      loadData();
    } catch (error) {
      console.error(error);
      toast.error("Failed to save wage matrix.");
    } finally {
      setSaving(false);
    }
  };


  const areasByMode = useMemo(() => {
    if (!data) return {};
    const grouped: Record<string, LogisticsArea[]> = {
      'DELIVERY': [],
      'PICKUP ONLY': [],
      'PICKUP W/ MP DELIVERY': []
    };
    data.areas.forEach(area => {
      if (grouped[area.mode_type]) {
        grouped[area.mode_type].push(area);
      }
    });
    return grouped;
  }, [data]);

  const staffByColumn = useMemo(() => {
    if (!data) return {};
    const mapping: Record<string, LogisticsStaff | undefined> = {};

    COLUMN_MAP.forEach(col => {
      const found = data.staff.find(s => {
        const matchesRole = s.role === col.role;
        const matchesType = col.employmentType ? s.employment_type === col.employmentType : true;

        // For Drivers, we also need to match vehicle type (if applicable)
        // Wait, the DDL says staff has vehicle_type_id.
        // Let's find staff of role Driver. 
        // In the wireframe, "Below 10W", "10 Wheeler", "Trailer" are columns.
        // These are distinct categories. If there's only one "Driver" staff record,
        // then we use that staff_id and vary the vehicle_type_id in the matrix.

        // Actually, Staff doesn't necessarily have a 1-to-1 mapping with Vehicle Type here.
        // If Role is Driver, we use those 3 columns.
        // If Role is Helper, we use those 4 columns.

        if (col.role === 'Driver') {
           // We just need a representative staff record for 'Driver' role?
           // Or does the project have specific staff records for "Driver Below 10W"?
           // Based on StaffTab, recruitment is by Role & Employment Type.
           // Let's find the FIRST staff record matching the role/employment.
           return matchesRole && matchesType;
        }

        return matchesRole && matchesType;
      });
      mapping[col.key] = found;
    });

    return mapping;
  }, [data]);

  const getVehicleTypeId = (vtName: string | undefined): number => {
    if (!data) return 0;
    // If vtName is provided, find that specific type
    if (vtName) {
      const found = data.vehicleTypes.find(vt => vt.vehicle_type === vtName);
      if (found) return found.vehicle_type_id;
    }

    // Default to 'N/A' type ID if no specific type is requested or found
    const naType = data.vehicleTypes.find(vt => vt.vehicle_type === 'N/A');
    return naType?.vehicle_type_id || 0;
  };

  const getCellValue = (areaId: number, colKey: string): string => {
    const key = `${areaId}_${colKey}`;
    return draft[key] || "";
  };

  const filteredAreas = (modeType: string) => {
    const areas = areasByMode[modeType] || [];
    if (!searchTerm) return areas;
    return areas.filter(a => a.area_name.toLowerCase().includes(searchTerm.toLowerCase()));
  };

  if (loading && !data) {
    return (
      <DashboardLayout>
        <div className="p-8 space-y-8 animate-in fade-in duration-500">
          <div className="flex items-center justify-between">
            <div className="space-y-2">
              <Skeleton className="h-10 w-48" />
              <Skeleton className="h-4 w-64" />
            </div>
          </div>
          <div className="space-y-4">
            <Skeleton className="h-12 w-full" />
            <Skeleton className="h-64 w-full" />
          </div>
        </div>
      </DashboardLayout>
    );
  }

  return (
    <DashboardLayout>
      <div className="max-w-7xl mx-auto w-full px-4 sm:px-6 py-6 space-y-8 bg-slate-50/30 dark:bg-slate-950/30 min-h-screen">
        {/* Header */}
        <div className="flex flex-col lg:flex-row lg:items-center justify-between gap-6">
          <div className="space-y-1">
            <div className="flex items-center gap-2">
              <div className="p-2 bg-blue-600 rounded-lg shadow-lg shadow-blue-500/20 flex-shrink-0">
                <LayoutGrid className="h-6 w-6 text-white" />
              </div>
              <h1 className="text-2xl md:text-3xl font-extrabold tracking-tight text-slate-900 dark:text-white truncate">
                Rate & Payout Matrix
              </h1>
            </div>
            <div className="flex flex-wrap items-center gap-2 text-slate-500 dark:text-slate-400">
              <span className="text-sm">Manage logistics pricing and payout configurations</span>
              {lastUpdated && (
                <Badge variant="outline" className="text-[10px] font-medium border-slate-200 bg-white/50 backdrop-blur-sm">
                  <Clock className="h-3 w-3 mr-1 text-slate-400" />
                  Last updated: {lastUpdated}
                </Badge>
              )}
            </div>
          </div>

          <div className="flex flex-col sm:flex-row items-stretch sm:items-center gap-3">
            <div className="relative group w-full sm:w-auto">
              <Search className="absolute left-3 top-1/2 -translate-y-1/2 h-4 w-4 text-slate-400 group-focus-within:text-blue-500 transition-colors" />
              <Input 
                placeholder="Search areas..." 
                className="pl-10 w-full sm:w-64 bg-white/80 dark:bg-slate-900/80 border-slate-200 dark:border-slate-800 focus:ring-2 focus:ring-blue-500/20 transition-all rounded-xl"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
            <div className="flex items-center gap-3">
              <Button variant="outline" onClick={loadData} className="flex-1 sm:flex-initial rounded-xl border-slate-300 bg-white/50 backdrop-blur-sm hover:bg-slate-100 transition-all shadow-md">
                <RefreshCcw className="h-4 w-4" />
              </Button>
              <Button 
                  onClick={handleSave} 
                  disabled={saving}
                  className="flex-[2] sm:flex-initial bg-blue-600 hover:bg-blue-700 text-white shadow-lg shadow-blue-500/20 rounded-xl px-6 gap-2 transition-all active:scale-95"
              >
                {saving ? <RefreshCcw className="h-4 w-4 animate-spin" /> : <Save className="h-4 w-4" />}
                <span className="whitespace-nowrap">Save Matrix</span>
              </Button>
            </div>
          </div>
        </div>

        <Separator className="bg-slate-200/60 dark:bg-slate-800/60" />

        {/* Matrix Tables */}
        {Object.keys(areasByMode).map((mode) => {
          const areas = filteredAreas(mode);
          if (areas.length === 0 && searchTerm) return null;

          return (
            <div key={mode} className="space-y-4 animate-in slide-in-from-bottom-4 duration-500">
               <div className="flex items-center gap-3 px-2">
                 <div className={`h-8 w-1.5 rounded-full ${
                   mode === 'DELIVERY' ? 'bg-blue-500' : 
                   mode === 'PICKUP ONLY' ? 'bg-emerald-500' : 'bg-purple-500'
                 }`} />
                 <h2 className="text-xl font-bold text-slate-800 dark:text-slate-100 uppercase tracking-wider">
                   {mode}
                 </h2>
                 <Badge variant="secondary" className="rounded-full bg-slate-100 dark:bg-slate-800 text-slate-600 dark:text-slate-400 font-bold border-none">
                   {areas.length} Areas
                 </Badge>
               </div>

               <div className="rounded-2xl border border-slate-300 dark:border-slate-800/60 shadow-[0_20px_50px_rgba(0,0,0,0.1)] dark:shadow-2xl overflow-hidden bg-white/60 dark:bg-slate-950/40 backdrop-blur-md">
                 <div className="overflow-x-auto">
                   <Table>
                     <TableHeader>
                       {/* Column Groups */}
                       <TableRow className="bg-slate-100/80 dark:bg-slate-900/50 border-b-2 border-slate-200 dark:border-slate-800">
                         <TableHead colSpan={2} className="px-6 py-4"></TableHead>
                         <TableHead colSpan={3} className="text-center font-bold text-[10px] uppercase tracking-[0.2em] text-blue-700 dark:text-blue-400 border-x border-slate-200/50 dark:border-slate-800/50 py-3">
                            <div className="flex items-center justify-center gap-1.5">
                              <Truck className="h-3 w-3" />
                              Fleet Operator
                            </div>
                         </TableHead>
                         <TableHead colSpan={2} className="text-center font-bold text-[10px] uppercase tracking-[0.2em] text-emerald-600 dark:text-emerald-400 border-x border-slate-100/50 dark:border-slate-800/50 py-3">
                            <div className="flex items-center justify-center gap-1.5">
                              <UserCircle className="h-3 w-3" />
                              Helper
                            </div>
                         </TableHead>
                         <TableHead colSpan={2} className="text-center font-bold text-[10px] uppercase tracking-[0.2em] text-purple-600 dark:text-purple-400 border-l border-slate-100/50 dark:border-slate-800/50 py-3">
                            <div className="flex items-center justify-center gap-1.5">
                              <ShieldCheck className="h-3 w-3" />
                              Logistics Crew
                            </div>
                         </TableHead>
                       </TableRow>

                       {/* Column Headers */}
                       <TableRow className="bg-slate-50/50 dark:bg-slate-900/30">
                         <TableHead className="w-[220px] px-6 font-bold text-slate-800 dark:text-slate-200 sticky left-0 bg-white dark:bg-slate-950/95 z-10 border-r border-slate-200/50">Areas</TableHead>
                         <TableHead className="w-[100px] text-center font-bold text-slate-800 dark:text-slate-200 border-r border-slate-200 dark:border-slate-800">Max # Days</TableHead>

                         {COLUMN_MAP.map((col) => (
                           <TableHead key={col.key} className="text-center min-w-[140px] px-4 py-4 border-r last:border-r-0 border-slate-200/50 dark:border-slate-800/50">
                             <div className="flex flex-col items-center gap-0.5">
                               <span className="text-xs font-bold text-slate-700 dark:text-slate-400 uppercase tracking-tighter">
                                 {col.label}
                               </span>
                             </div>
                           </TableHead>
                         ))}
                       </TableRow>
                     </TableHeader>

                     <TableBody>
                        {areas.length === 0 ? (
                          <TableRow>
                            <TableCell colSpan={9} className="h-32 text-center text-slate-400 italic">
                               No areas found in this category.
                            </TableCell>
                          </TableRow>
                        ) : (
                          areas.map((area) => (
                            <TableRow key={area.id} className="group hover:bg-blue-50/50 dark:hover:bg-blue-900/10 transition-colors border-b border-slate-200/60 dark:border-slate-800/50">
                              <TableCell className="px-6 py-4 font-semibold text-slate-950 dark:text-slate-100 sticky left-0 bg-white/95 dark:bg-slate-950/95 group-hover:bg-blue-50 dark:group-hover:bg-blue-900/20 z-10 border-r border-slate-200/30">
                                <div className="flex items-center gap-2">
                                  <span className="truncate max-w-[180px]">{area.area_name}</span>
                                </div>
                              </TableCell>
                              <TableCell className="text-center font-mono text-xs text-slate-600 border-r border-slate-200 dark:border-slate-800">
                                {area.max_days || "—"}
                              </TableCell>
                              {COLUMN_MAP.map((col) => {
                                const staff = staffByColumn[col.key];
                                const vtId = getVehicleTypeId(col.vehicleType);
                                const cellValue = getCellValue(area.area_id, col.key);
                                const isDirty = data?.matrix.find(m => 
                                  m.area_id === area.area_id && 
                                  m.staff_id === (staff?.staff_id || -1) && 
                                  m.vehicle_type_id === vtId
                                )?.wage_amount.toString() !== cellValue && cellValue !== "";

                                return (
                                  <TableCell key={col.key} className="p-1 px-2 border-r last:border-r-0 border-slate-200/40 dark:border-slate-800/30">
                                     {!staff ? (
                                       <div className="h-full w-full bg-slate-200/50 dark:bg-slate-800/50 rounded flex items-center justify-center">
                                          <AlertCircle className="h-3 w-3 text-slate-400" />
                                       </div>
                                     ) : (
                                       <div className="relative">
                                         <Input 
                                           type="number"
                                           value={cellValue}
                                           onChange={(e) => handleInputChange(area.area_id, col.key, e.target.value)}
                                           className={`h-9 text-center font-mono text-sm bg-transparent border-none focus:ring-1 focus:ring-blue-500/50 rounded-lg transition-all text-slate-900 dark:text-slate-100 ${
                                             isDirty ? "bg-amber-100/50 dark:bg-amber-900/10 text-amber-700" : ""
                                           }`}
                                           placeholder="0.00"
                                         />
                                         {isDirty && (
                                           <div className="absolute top-1 right-1 w-1.5 h-1.5 rounded-full bg-amber-400 animate-pulse" />
                                         )}
                                       </div>
                                     )}
                                  </TableCell>
                                );
                              })}
                            </TableRow>
                          ))
                        )}
                     </TableBody>
                   </Table>
                 </div>
               </div>
            </div>
          );
        })}

        {/* Empty State when searching */}
        {searchTerm && Object.values(areasByMode).every(arr => arr.filter(a => a.area_name.toLowerCase().includes(searchTerm.toLowerCase())).length === 0) && (
          <Card className="border-dashed border-2 bg-slate-50/50 dark:bg-slate-900/20">
             <CardContent className="flex flex-col items-center justify-center py-16 gap-4">
                <div className="p-4 bg-slate-200/50 rounded-full">
                  <Search className="h-8 w-8 text-slate-400" />
                </div>
                <div className="text-center space-y-1">
                  <p className="text-lg font-semibold text-slate-600">No results found</p>
                  <p className="text-sm text-slate-400">Try adjusting your search term to find areas.</p>
                </div>
                <Button variant="outline" onClick={() => setSearchTerm("")} className="rounded-xl">
                  Clear Search
                </Button>
             </CardContent>
          </Card>
        )}
      </div>

      <style jsx global>{`
        input[type=number]::-webkit-inner-spin-button, 
        input[type=number]::-webkit-outer-spin-button { 
          -webkit-appearance: none; 
          margin: 0; 
        }
      `}</style>
    </DashboardLayout>
  );
}

// @modules/wage/WageModule.tsx
"use client";
import React, { useEffect, useState } from "react";
import DashboardLayout from "@/components/layout/DashboardLayout";
import { Card, CardContent } from "@/components/ui/card";
import { toast } from "sonner";
import { Separator } from "@/components/ui/separator";
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Skeleton } from "@/components/ui/skeleton";

import type { Department, Employee, WagePayload, WageDataState, SalarySchedule } from "./types";
import * as wageApi from "./providers/wageApi"; // ✅ correct path

import EmployeeTable from "./components/EmployeeTable";
import PasswordDialog from "./components/PasswordDialog";
import WageModal from "./components/WageModal";
import { SalaryGradeManagement } from "./components/SalaryGradeManagement";

export function WageModule() {
  const [activeTab, setActiveTab] = useState("wage");
  const [isTabLoading, setIsTabLoading] = useState(false);
  const [departments, setDepartments] = useState<Department[]>([]);
  const [selectedDept, setSelectedDept] = useState<number | null>(null);
  const [employees, setEmployees] = useState<Employee[]>([]);
  const [totalEmployees, setTotalEmployees] = useState<number>(0);

  // Modals
  const [modalOpen, setModalOpen] = useState(false);
  const [selectedEmployee, setSelectedEmployee] = useState<Employee | null>(
    null
  );
  const [passwordDialogOpen, setPasswordDialogOpen] = useState(false);

  // Filters
  const [searchTerm, setSearchTerm] = useState("");
  const [loading, setLoading] = useState(true);
  const [refreshKey, setRefreshKey] = useState(0);

  // Sort & Pagination
  const [sortField, setSortField] = useState<keyof Employee>("user_id");
  const [sortOrder, setSortOrder] = useState<"asc" | "desc">("asc");
  const [currentPage, setCurrentPage] = useState(1);
  const [rowsPerPage, setRowsPerPage] = useState(5);

  // Salary schedules list (for the grade picker in WageTab)
  const [salarySchedules, setSalarySchedules] = useState<SalarySchedule[]>([]);

  // Optional cache
  const [previousDailyWage, setPreviousDailyWage] = useState<number | null>(
    null
  );

  const emptyWageData: WageDataState = {
    id: null,
    schedule_id: null,
    dailyWage: 0,
    dailyWageInput: "0.00",
    vacationLeave: 0,
    sickLeave: 0,
    isPaidHoliday: false,
    isCard: false,
    sss: "0.00",
    pagibig: "0.00",
    philhealth: "0.00",
    lastUpdatedBy: "",
    lastUpdateDate: "",
  };

  const [wageData, setWageData] = useState<WageDataState>(emptyWageData);

  const handleTabChange = (val: string) => {
    if (val === activeTab) return;
    setActiveTab(val);
    setIsTabLoading(true);
    setTimeout(() => setIsTabLoading(false), 300);
  };

  useEffect(() => {
    wageApi.fetchDepartments().then(setDepartments).catch(console.error);
  }, []);

  useEffect(() => {
    setLoading(true);
    wageApi
      .fetchEmployeesPaged({
        page: currentPage,
        pageSize: rowsPerPage,
        search: searchTerm,
        deptId: selectedDept,
        sortField,
        sortOrder,
      })
      .then(({ rows, total }) => {
        setEmployees(rows);
        setTotalEmployees(total);
      })
      .catch((err) => {
        console.error(err);
        toast.error("Failed to load employees.");
      })
      .finally(() => setLoading(false));
  }, [
    currentPage,
    rowsPerPage,
    searchTerm,
    selectedDept,
    sortField,
    sortOrder,
    refreshKey,
  ]);

  const handleRefresh = () => setRefreshKey((prev) => prev + 1);

  const handleReset = () => {
    setSearchTerm("");
    setSelectedDept(null);
    setSortField("user_id");
    setSortOrder("asc");
    setCurrentPage(1);
    handleRefresh();
  };

  const handleSort = (field: keyof Employee) => {
    if (sortField === field) {
      setSortOrder((s) => (s === "asc" ? "desc" : "asc"));
    } else {
      setSortField(field);
      setSortOrder("asc");
    }
  };

  const openPasswordDialog = (emp: Employee) => {
    setSelectedEmployee(emp);
    setPasswordDialogOpen(true);
  };

  const handlePasswordSubmit = async (passwordInput: string) => {
    try {
      const session = sessionStorage.getItem("user");
      if (!session) return alert("User not logged in.");
      const logged = JSON.parse(session);

      const apiUser = await wageApi.fetchUserById(logged.user_id);
      if (!apiUser) return alert("User record not found.");
      if (passwordInput !== apiUser.user_password)
        return alert("Incorrect password.");
      if (!selectedEmployee) return alert("No employee selected.");

      const ts = new Date().toISOString();
      const remarks = `Opened wage modal for ${selectedEmployee.user_fname} ${selectedEmployee.user_lname} at ${ts}`;
      await wageApi.logWageAccess(
        logged.user_id,
        selectedEmployee.user_id,
        remarks
      );

      // Load wage data + salary schedules in parallel
      await Promise.all([
        loadWageData(selectedEmployee.user_id),
        loadSalarySchedules(),
      ]);
      setPasswordDialogOpen(false);
      setModalOpen(true);
    } catch (e) {
      console.error(e);
      alert("Error verifying password. Try again.");
    }
  };

  const getUserFullName = async (userId: number | null) => {
    if (!userId && userId !== 0) return "Unknown";
    try {
      const u = await wageApi.fetchUserById(Number(userId));
      return u ? `${u.user_fname} ${u.user_lname}` : "Unknown";
    } catch {
      return "Unknown";
    }
  };

  const loadWageData = async (userId: number) => {
    try {
      const record = await wageApi.fetchWageByUser(userId);

      if (!record) {
        setWageData({ ...emptyWageData });
        setPreviousDailyWage(null);
        return;
      }

      const responsibleUserId = record.updated_by ?? record.created_by ?? null;
      const fullName = responsibleUserId
        ? await getUserFullName(responsibleUserId)
        : "";
      const lastDate = (
        record.updated_date ||
        record.created_date ||
        ""
      ).substring(0, 10);

      const dailyWageNum = Number(record.daily_wage) || 0;
      setPreviousDailyWage(dailyWageNum);

      const scheduleId =
        record.schedule_id !== undefined && record.schedule_id !== null
          ? Number(record.schedule_id)
          : null;

      setWageData({
        id: record.id ?? null,
        schedule_id: scheduleId,
        dailyWage: dailyWageNum,
        dailyWageInput: dailyWageNum.toFixed(2),
        vacationLeave: Number(record.vacation_leave_per_year) || 0,
        sickLeave: Number(record.sick_leave_per_year) || 0,
        isPaidHoliday: Number(record.paid_holiday) === 1,
        isCard: Number(record.isCard) === 1,
        sss: String(record.sss_contribution_monthly ?? "0.00"),
        pagibig: String(record.pagibig_contribution_monthly ?? "0.00"),
        philhealth: String(record.philhealth_contribution_monthly ?? "0.00"),
        lastUpdatedBy: fullName || "",
        lastUpdateDate: lastDate,
      });
    } catch (e) {
      console.error(e);
      toast.error("Failed to load wage data.");
    }
  };

  const loadSalarySchedules = async () => {
    try {
      const rows = await wageApi.fetchSalarySchedules();
      setSalarySchedules(rows);
    } catch (e) {
      console.error("[Wage] Failed to load salary schedules", e);
      // Non-critical; leave list empty so tab degrades gracefully
    }
  };

  const saveWageData = async () => {
    const session = sessionStorage.getItem("user");
    if (!session) return alert("User session missing.");
    const logged = JSON.parse(session);

    if (!selectedEmployee) return alert("No employee selected.");
    if (!window.confirm(`Save settings for ${selectedEmployee.user_fname}?`))
      return;

    const now = new Date();
    const todayYmd = `${now.getFullYear()}-${String(
      now.getMonth() + 1
    ).padStart(2, "0")}-${String(now.getDate()).padStart(2, "0")}`;

    let currentRecord = null;
    try {
      currentRecord = await wageApi.fetchWageByUser(selectedEmployee.user_id);
    } catch (e) {
      console.error("[Wage] Failed to refetch current wage record", e);
      currentRecord = null;
    }

    const existingId =
      (currentRecord?.id ?? null) !== null
        ? Number(currentRecord?.id)
        : wageData.id;

    const prevWageNum =
      currentRecord?.daily_wage !== undefined &&
      currentRecord?.daily_wage !== null
        ? Number(currentRecord.daily_wage) || 0
        : previousDailyWage !== null
        ? previousDailyWage
        : 0;

    const nextWageNum = Number(wageData.dailyWage) || 0;

    const prevWageFixed = prevWageNum.toFixed(2);
    const nextWageFixed = nextWageNum.toFixed(2);

    const wageChanged =
      existingId !== null ? prevWageFixed !== nextWageFixed : nextWageNum > 0;

    const payload: WagePayload = {
      user_id: selectedEmployee.user_id,
      daily_wage: nextWageNum,
      vacation_leave_per_year: Number(wageData.vacationLeave) || 0,
      sick_leave_per_year: Number(wageData.sickLeave) || 0,
      paid_holiday: wageData.isPaidHoliday ? 1 : 0,
      isCard: wageData.isCard ? 1 : 0,
      updated_by: logged.user_id,
      sss_contribution_monthly: wageData.sss,
      pagibig_contribution_monthly: wageData.pagibig,
      philhealth_contribution_monthly: wageData.philhealth,
      // Persist the salary grade link (null clears it)
      schedule_id: wageData.schedule_id ?? null,
      ...(wageChanged ? { cutoff_wage_date_update: todayYmd } : {}),
    };

    try {
      if (existingId) {
        await wageApi.patchWage(existingId, payload);
      } else {
        payload.cutoff_wage_date_update = todayYmd;
        await wageApi.createWage(payload);
      }

      if (wageChanged) {
        try {
          const cutoff = await wageApi.findCutoffSettingByDate(todayYmd);
          const cutoffId =
            cutoff?.id !== undefined && cutoff?.id !== null
              ? Number(cutoff.id)
              : null;

          let fallbackCutoffId = cutoffId;
          if (!fallbackCutoffId) {
            const currentDay = now.getDate();
            // If day is 26th up to end of month, or 1st up to 10th
            if (currentDay >= 26 || currentDay <= 10) {
              fallbackCutoffId = 1;
            } else {
              // Day is 11th up to 25th
              fallbackCutoffId = 2;
            }

            console.warn(
              "[Wage] No cutoff_settings row matched date",
              todayYmd,
              `- proceeding with fallback cutoff_id = ${fallbackCutoffId}`
            );
          }

          console.log("[Wage] Attempting to create proration log...", {
            user_id: selectedEmployee.user_id,
            previous_daily_wage: existingId ? Number(prevWageFixed) : 0,
            new_daily_wage: Number(nextWageFixed),
            effective_date: todayYmd,
            cutoff_id: fallbackCutoffId,
            updated_by: logged.user_id,
          });

          await wageApi.createWageProrationLog({
            user_id: selectedEmployee.user_id,
            previous_daily_wage: existingId ? Number(prevWageFixed) : 0,
            new_daily_wage: Number(nextWageFixed),
            effective_date: todayYmd,
            cutoff_id: fallbackCutoffId,
            updated_by: logged.user_id,
          });
          console.log("[Wage] Proration log created successfully!");
        } catch (e: unknown) {
          console.error("[Wage] Proration log failed to create", e);
          const msg = e instanceof Error ? e.message : String(e);
          toast.error(
            `Wage saved, but proration log failed: ${msg}. Check console.`
          );
        }
      }

      toast.success("Wage information saved.");
      await loadWageData(selectedEmployee.user_id);
      setModalOpen(false);
    } catch (e) {
      console.error(e);
      toast.error("Failed to save wage data.");
    }
  };

  return (
    <DashboardLayout>
      <div className="space-y-6 font-sans">
        <div className="flex flex-col gap-1 px-1 max-w-7xl mx-auto w-full">
          <div className="flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
            <div>
              <h1 className="text-2xl font-bold tracking-tight text-gray-900 dark:text-gray-100">
                {activeTab === "wage"
                  ? "Wage Management"
                  : "Salary Grade Management"}
              </h1>
              <p className="text-sm text-gray-500 dark:text-gray-400">
                {activeTab === "wage"
                  ? "Manage individual employee wage configurations and records."
                  : "Manage standardized salary schedules and grade steps."}
              </p>
            </div>

            <Tabs
              value={activeTab}
              onValueChange={handleTabChange}
              className="w-full sm:w-auto mt-2 sm:mt-0"
            >
              <TabsList className="grid w-full grid-cols-2">
                <TabsTrigger value="wage">Wage Management</TabsTrigger>
                <TabsTrigger value="salary-grade">Salary Grade</TabsTrigger>
              </TabsList>
            </Tabs>
          </div>
          <Separator className="mt-4" />
        </div>

        <div className="max-w-7xl mx-auto w-full">
          <Tabs value={activeTab} onValueChange={handleTabChange} className="w-full">
            <TabsContent value="wage" className="mt-0 outline-none">
              <Card className="border shadow-sm bg-white dark:bg-gray-900 py-0">
                <CardContent className="p-6">
                  {isTabLoading ? (
                    <div className="space-y-4">
                      <div className="flex justify-between items-center">
                        <Skeleton className="h-10 w-[200px]" />
                        <Skeleton className="h-10 w-[250px]" />
                      </div>
                      <div className="space-y-2 mt-4">
                        <Skeleton className="h-12 w-full" />
                        <Skeleton className="h-12 w-full" />
                        <Skeleton className="h-12 w-full" />
                        <Skeleton className="h-12 w-full" />
                        <Skeleton className="h-12 w-full" />
                      </div>
                    </div>
                  ) : (
                    <EmployeeTable
                      employees={employees}
                      departments={departments}
                      loading={loading}
                      selectedDept={selectedDept}
                      setSelectedDept={setSelectedDept}
                      searchTerm={searchTerm}
                      setSearchTerm={setSearchTerm}
                      onOpenPassword={openPasswordDialog}
                      handleSort={handleSort as (key: keyof Employee) => void}
                      rowsPerPage={rowsPerPage}
                      setRowsPerPage={setRowsPerPage}
                      currentPage={currentPage}
                      setCurrentPage={setCurrentPage}
                      totalEmployees={totalEmployees}
                      onRefresh={handleRefresh}
                      onReset={handleReset}
                    />
                  )}
                </CardContent>
              </Card>
            </TabsContent>

            <TabsContent value="salary-grade" className="mt-0 outline-none">
              <Card className="border shadow-sm bg-white dark:bg-gray-900 py-0">
                <CardContent className="p-6">
                  {isTabLoading ? (
                    <div className="space-y-4">
                      <div className="flex justify-between items-center">
                        <Skeleton className="h-10 w-[200px]" />
                        <Skeleton className="h-10 w-[150px]" />
                      </div>
                      <div className="space-y-2 mt-4">
                        <Skeleton className="h-12 w-full" />
                        <Skeleton className="h-12 w-full" />
                        <Skeleton className="h-12 w-full" />
                        <Skeleton className="h-12 w-full" />
                        <Skeleton className="h-12 w-full" />
                      </div>
                    </div>
                  ) : (
                    <SalaryGradeManagement />
                  )}
                </CardContent>
              </Card>
            </TabsContent>
          </Tabs>
        </div>
      </div>

      <PasswordDialog
        open={passwordDialogOpen}
        onOpenChange={setPasswordDialogOpen}
        onSubmit={handlePasswordSubmit}
      />

      <WageModal
        open={modalOpen}
        onOpenChange={setModalOpen}
        selectedEmployee={selectedEmployee}
        wageData={wageData}
        setWageData={(upd) => setWageData((prev) => ({ ...prev, ...upd }))}
        onSave={saveWageData}
        salarySchedules={salarySchedules}
      />
    </DashboardLayout>
  );
}

export default WageModule;

// @modules/wage/components/EmployeeTable.tsx
"use client";

import React from "react";
import { Button } from "@/components/ui/button";
import {
  Select,
  SelectContent,
  SelectItem,
  SelectTrigger,
  SelectValue,
} from "@/components/ui/select";
import { Input } from "@/components/ui/input";
import {
  Table,
  TableBody,
  TableCell,
  TableHead,
  TableHeader,
  TableRow,
} from "@/components/ui/table";
import { Separator } from "@/components/ui/separator";
import { Search, RotateCcw, RefreshCcw } from "lucide-react";
import type { Department, Employee } from "../types";

type Props = {
  employees: Employee[];
  departments: Department[];
  loading: boolean;
  selectedDept: number | null;
  setSelectedDept: (dept: number | null) => void;
  searchTerm: string;
  setSearchTerm: (term: string) => void;
  handleSort: (key: "user_id" | "user_fname" | "user_lname") => void;
  onOpenPassword: (emp: Employee) => void;
  currentPage: number;
  setCurrentPage: (page: number) => void;
  rowsPerPage: number;
  setRowsPerPage: (rows: number) => void;
  totalEmployees: number;
  onRefresh: () => void;
  onReset: () => void;
};

export default function EmployeeTable({
  employees,
  departments,
  loading,
  selectedDept,
  setSelectedDept,
  searchTerm,
  setSearchTerm,
  handleSort,
  onOpenPassword,
  currentPage,
  setCurrentPage,
  rowsPerPage,
  setRowsPerPage,
  totalEmployees,
  onRefresh,
  onReset,
}: Props) {
  const totalPages = Math.ceil(totalEmployees / rowsPerPage) || 1;

  return (
    <div className="w-full space-y-4">
      {/* --- Filter / Toolbar Section --- */}
      <div className="flex flex-col md:flex-row gap-4 items-end justify-between mt-4">
        {/* Left Side: Search (Grows to fill) */}
        <div className="flex-1 w-full md:max-w-md space-y-1">
          <label className="text-xs font-medium text-gray-500">
            Search employee
          </label>
          <div className="relative">
            <Search className="absolute left-2.5 top-2.5 h-4 w-4 text-gray-400" />
            <Input
              placeholder="Type name..."
              value={searchTerm}
              onChange={(e) => setSearchTerm(e.target.value)}
              className="pl-9 h-10"
            />
          </div>
        </div>

        {/* Right Side: Filters & Actions (Compact) */}
        <div className="flex flex-wrap gap-3 w-full md:w-auto">
          {/* Department Filter - Fixed Width */}
          <div className="space-y-1 w-full md:w-[200px]">
            <label className="text-xs font-medium text-gray-500">
              Department
            </label>
            <Select
              value={selectedDept !== null ? selectedDept.toString() : "all"}
              onValueChange={(val) =>
                setSelectedDept(val === "all" ? null : Number(val))
              }
            >
              <SelectTrigger className="h-10">
                <SelectValue placeholder="All Departments" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="all">All Departments</SelectItem>
                {departments.map((dept) => (
                  <SelectItem
                    key={dept.department_id}
                    value={dept.department_id.toString()}
                  >
                    {dept.department_name}
                  </SelectItem>
                ))}
              </SelectContent>
            </Select>
          </div>

          {/* Sort By - Fixed Width */}
          <div className="space-y-1 w-full md:w-[160px]">
            <label className="text-xs font-medium text-gray-500">Sort By</label>
            <Select
              onValueChange={(val: "user_id" | "user_fname" | "user_lname") => handleSort(val)}
              defaultValue="user_id"
            >
              <SelectTrigger className="h-10">
                <SelectValue placeholder="Sort By" />
              </SelectTrigger>
              <SelectContent>
                <SelectItem value="user_id">Employee ID</SelectItem>
                <SelectItem value="user_fname">First Name</SelectItem>
                <SelectItem value="user_lname">Last Name</SelectItem>
              </SelectContent>
            </Select>
          </div>

          {/* Quick Actions - Auto Width */}
          <div className="space-y-1">
            <label className="text-xs font-medium text-gray-500">
              Quick Actions
            </label>
            <div className="flex gap-2">
              <Button
                variant="outline"
                className="h-10 px-3 gap-2 text-gray-600 border-gray-300"
                onClick={onReset}
                title="Reset Filters"
              >
                <RotateCcw className="h-4 w-4" />
                <span className="hidden lg:inline">Reset</span>
              </Button>
              <Button
                className="h-10 px-4 gap-2 bg-blue-600 hover:bg-blue-700 text-white"
                onClick={onRefresh}
              >
                <RefreshCcw className="h-4 w-4" />
                Refresh
              </Button>
            </div>
          </div>
        </div>
      </div>

      {/* --- Visual Separator --- */}
      <Separator className="my-4" />

      {/* --- Table Section --- */}
      <div className="border rounded-md overflow-hidden">
        <Table>
          <TableHeader className="bg-gray-50 dark:bg-gray-800">
            <TableRow>
              <TableHead className="w-[100px] text-gray-600 font-semibold">
                No.
              </TableHead>
              <TableHead className="text-gray-600 font-semibold">
                Name
              </TableHead>
              <TableHead className="text-gray-600 font-semibold">
                Department
              </TableHead>
              <TableHead className="text-right text-gray-600 font-semibold pr-6">
                Action
              </TableHead>
            </TableRow>
          </TableHeader>
          <TableBody>
            {loading ? (
              Array.from({ length: 5 }).map((_, i) => (
                <TableRow key={i}>
                  <TableCell>
                    <div className="h-4 w-8 bg-gray-200 rounded animate-pulse" />
                  </TableCell>
                  <TableCell>
                    <div className="h-4 w-32 bg-gray-200 rounded animate-pulse" />
                  </TableCell>
                  <TableCell>
                    <div className="h-4 w-24 bg-gray-200 rounded animate-pulse" />
                  </TableCell>
                  <TableCell className="text-right">
                    <div className="h-4 w-20 bg-gray-200 rounded animate-pulse inline-block" />
                  </TableCell>
                </TableRow>
              ))
            ) : employees.length === 0 ? (
              <TableRow>
                <TableCell
                  colSpan={4}
                  className="h-24 text-center text-gray-500"
                >
                  No employees found.
                </TableCell>
              </TableRow>
            ) : (
              employees.map((emp) => {
                const deptName =
                  departments.find(
                    (d) => d.department_id === emp.user_department
                  )?.department_name ?? "N/A";
                return (
                  <TableRow
                    key={emp.user_id}
                    className="hover:bg-gray-50 dark:hover:bg-gray-800/50"
                  >
                    <TableCell className="font-medium text-gray-500">
                      {emp.user_id}
                    </TableCell>
                    <TableCell className="font-medium text-gray-900 dark:text-gray-100">
                      {emp.user_fname} {emp.user_lname}
                    </TableCell>
                    <TableCell className="text-gray-600 dark:text-gray-300">
                      {deptName}
                    </TableCell>
                    <TableCell className="text-right pr-4">
                      <Button
                        variant="outline"
                        size="sm"
                        className="text-blue-600 border-blue-200 hover:bg-blue-50 hover:text-blue-700"
                        onClick={() => onOpenPassword(emp)}
                      >
                        View Wage Info
                      </Button>
                    </TableCell>
                  </TableRow>
                );
              })
            )}
          </TableBody>
        </Table>
      </div>

      {/* --- Pagination Section --- */}
      <div className="flex flex-col sm:flex-row justify-between items-center gap-4 pt-2">
        <div className="text-sm text-gray-500">
          Showing{" "}
          {employees.length > 0 ? (currentPage - 1) * rowsPerPage + 1 : 0} to{" "}
          {Math.min(currentPage * rowsPerPage, totalEmployees)} of{" "}
          {totalEmployees} entries
        </div>

        <div className="flex items-center gap-2">
          <Button
            variant="outline"
            size="sm"
            onClick={() => setCurrentPage(Math.max(1, currentPage - 1))}
            disabled={currentPage === 1}
            className="h-8 px-3 text-gray-600"
          >
            Prev
          </Button>
          <div className="text-sm font-medium px-2">
            Page {currentPage} / {totalPages}
          </div>
          <Button
            variant="outline"
            size="sm"
            onClick={() =>
              setCurrentPage(Math.min(totalPages, currentPage + 1))
            }
            disabled={currentPage === totalPages || totalPages === 0}
            className="h-8 px-3 text-gray-600"
          >
            Next
          </Button>
        </div>
      </div>
    </div>
  );
}

